  var XROWS = ["3/4 Sit-Up~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Lie down on the floor and secure your feet. Your legs should be bent at the knees.~Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position. Flex your hips and spine to raise your torso toward your knees. At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.~Pulling on the neck with the hands.", "90/90 Hamstring~Mobility~stretch~0~None~2.3~h~0~Hamstrings, Calves~Lie on your back, with one leg extended straight out.~With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position. Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.~Bouncing into the stretch or pushing into pain.", "Ab Crunch Machine~Abs & core~crunch~2~Gym machine~3.5~r~1~Abdominals~Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.~At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet. After a second pause, slowly return to the starting position as you breathe in.~Pulling on the neck with the hands.", "Ab Roller~Abs & core~crunch~2~Gym equipment (see steps)~5.0~r~1~Abdominals, Shoulders~Hold the Ab Roller with both hands and kneel on the floor.~Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position. Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement. After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out.~Pulling on the neck with the hands.", "Adductor~Mobility~stretch~1~A foam roller~2.3~h~1~Adductors~Lie face down with one leg on a foam roll.~Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated. While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.~Bouncing into the stretch or pushing into pain.", "Adductor/Groin~Mobility~stretch~0~None~2.3~h~1~Adductors~Lie on your back with your feet raised towards the ceiling.~Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position. Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so. Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.~Bouncing into the stretch or pushing into pain.", "Advanced Kettlebell Windmill~Abs & core~crunch~1~A kettlebell~3.5~r~1~Abdominals, Glutes, Hamstrings, Shoulders~Clean and press a kettlebell overhead with one arm.~Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell. Lower yourself as far as possible. Pause for a second and reverse the motion back to the starting position.~Pulling on the neck with the hands.", "Air Bike~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.~Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position. Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out. Go back to the initial position as you breathe in.~Pulling on the neck with the hands.", "All Fours Quad Stretch~Mobility~stretch~0~None~2.3~h~1~Quadriceps, Quadriceps~Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.~Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors. Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.~Bouncing into the stretch or pushing into pain.", "Alternate Hammer Curl~Biceps~curl~1~Dumbbells~3.5~rs~0~Biceps, Forearms~Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.~The palms of the hands should be facing your torso. This will be your starting position. While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move. Slowly begin to bring the dumbbells back to starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Alternate Heel Touchers~Abs & core~crunch~0~None~3.5~rs~0~Abdominals~Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.~Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement. Now go back slowly to the starting position as you inhale. Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale.~Pulling on the neck with the hands.", "Alternate Incline Dumbbell Curl~Biceps~curl~1~Dumbbells~3.5~rs~0~Biceps, Forearms~Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso. This will be your starting position.~While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move. Slowly begin to bring the dumbbell back to starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Alternate Leg Diagonal Bound~Quads~squat~0~None~8.0~rs~0~Quadriceps, Abductors, Adductors, Calves~Assume a comfortable stance with one foot slightly in front of the other.~Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound. It may help to use a line on the ground to guage distance from side to side.~Letting the knees cave inward or the heels lift.", "Alternating Cable Shoulder Press~Shoulders~ohpress~2~Cable machine~5.0~rs~0~Shoulders, Triceps~Move the cables to the bottom of the tower and select an appropriate weight.~Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press one side directly over head. After pausing at the top, return to the starting position and repeat on the opposite side.~Arching the lower back to push the weight up.", "Alternating Deltoid Raise~Shoulders~frontraise~1~Dumbbells~3.5~rs~0~Shoulders~In a standing position, hold a pair of dumbbells at your side.~Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating. Return the weights to your side. On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height. Return the weights to the starting position and continue alternating to the front and side.~Swinging the weight up with the body.", "Alternating Floor Press~Chest~bench~1~A kettlebell~5.0~rs~0~Chest, Abdominals, Shoulders, Triceps~Lie on the floor with two kettlebells next to your shoulders.~Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward. Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell. Raise the kettlebell and repeat on the opposite side.~Bouncing the weight or lifting the hips off the bench.", "Alternating Hang Clean~Hamstrings~rdl~1~A kettlebell~5.0~rs~1~Hamstrings, Biceps, Calves, Forearms~Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.~Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so. Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.~Rounding the lower back instead of hinging at the hips.", "Alternating Kettlebell Press~Shoulders~ohpress~1~A kettlebell~5.0~rs~1~Shoulders, Triceps~Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.~Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary . Lower the pressed kettlebell to the starting position and immediately press with your other arm.~Arching the lower back to push the weight up.", "Alternating Kettlebell Row~Back~row~1~A kettlebell~3.5~rs~1~Middle back, Biceps, Lats~Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.~Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage. Lower the kettlebell in the working arm and repeat with your other arm.~Rounding the back or jerking the weight with the arms only.", "Alternating Renegade Row~Back~row~1~A kettlebell~5.0~rs~2~Middle back, Abdominals, Biceps, Chest~Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.~Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side. Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.~Rounding the back or jerking the weight with the arms only.", "Ankle On The Knee~Mobility~stretch~0~None~2.3~h~0~Glutes~From a lying position, bend your knees and keep your feet on the floor.~Place your ankle of one foot on your opposite knee. Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides.~Bouncing into the stretch or pushing into pain.", "Anterior Tibialis-SMR~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Calves~Begin seated on the ground with your legs bent and your feet on the floor.~Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg.~Bouncing into the stretch or pushing into pain.", "Anti-Gravity Press~Shoulders~ohpress~2~Barbell and plates~5.0~r~0~Shoulders, Middle back, Traps, Triceps~Place a bar on the ground behind the head of an incline bench.~Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position. To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement. Return to the starting position and repeat to complete the set.~Arching the lower back to push the weight up.", "Arm Circles~Mobility~stretch~0~None~2.3~h~0~Shoulders, Traps~Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.~Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement. Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.~Bouncing into the stretch or pushing into pain.", "Arnold Dumbbell Press~Shoulders~ohpress~1~Dumbbells~5.0~r~1~Shoulders, Triceps~Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.~Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward. Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement. After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise.~Arching the lower back to push the weight up.", "Around The Worlds~Chest~bench~1~Dumbbells~5.0~r~1~Chest, Shoulders~Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.~Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement. Reverse the movement to return the weight to the starting position as you exhale.~Bouncing the weight or lifting the hips off the bench.", "Back Flyes - With Bands~Shoulders~frontraise~1~A resistance band~5.0~r~0~Shoulders, Middle back, Triceps~Run a band around a stationary post like that of a squat rack.~Grab the band by the handles and stand back so that the tension in the band rises. Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position. As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.~Swinging the weight up with the body.", "Backward Medicine Ball Throw~Shoulders~ohpress~1~A medicine ball~8.0~r~0~Shoulders~This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.~Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs. Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner. Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.~Arching the lower back to push the weight up.", "Balance Board~Calves~calf~2~Gym equipment (see steps)~5.0~r~0~Calves, Hamstrings, Quadriceps~Place a balance board in front of you.~Stand up on it and try to balance yourself. Hold the balance for as long as desired.~Bouncing at the bottom instead of a full, slow stretch.", "Ball Leg Curl~Hamstrings~bridge~1~An exercise ball~3.5~r~0~Hamstrings, Calves, Glutes~Begin on the floor laying on your back with your feet on top of the ball.~Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position. Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet. Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings. After a brief pause, return to the starting position.~Arching the lower back instead of squeezing the glutes.", "Band Assisted Pull-Up~Back~pullup~2~Gym equipment (see steps)~5.0~r~0~Lats, Abdominals, Forearms, Middle back~Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.~Pull the end of the band down, and place one bent knee into the loop, ensuring it won't slip out. Take a medium to wide grip on the bar. This will be your starting position. Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements. After a brief pause, return to the starting position.~Kipping or not lowering all the way.", "Band Good Morning~Hamstrings~rdl~1~A resistance band~6.0~r~0~Hamstrings, Glutes, Lower back~Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.~Keeping your legs straight, extend through the hips to come to a near vertical position. Ensure that you do not round your back as you go down back to the starting position.~Rounding the lower back instead of hinging at the hips.", "Band Good Morning (Pull Through)~Hamstrings~rdl~1~A resistance band~6.0~r~0~Hamstrings, Glutes, Lower back~Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.~Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent. Return to the starting position be driving through with the hips to come back to a standing position.~Rounding the lower back instead of hinging at the hips.", "Band Hip Adductions~Glutes~bridge~1~A resistance band~3.5~r~0~Adductors~Anchor a band around a solid post or other object.~Stand with your left side to the post, and put your right foot through the band, getting it around the ankle. Stand up straight and hold onto the post if needed. This will be your starting position. Keeping the knee straight, raise your right legs out to the side as far as you can. Return to the starting position and repeat for the desired rep count. Switch sides.~Arching the lower back instead of squeezing the glutes.", "Band Skull Crusher~Triceps~pushdown~1~A resistance band~3.5~r~0~Triceps~Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.~Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position. Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.~Letting the elbows drift away from the sides.", "Barbell Ab Rollout~Abs & core~crunch~2~Barbell and plates~5.0~r~1~Abdominals, Lower back, Shoulders~For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.~While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don't, you will work out your shoulders and back more than the abs.~Pulling on the neck with the hands.", "Barbell Ab Rollout - On Knees~Abs & core~crunch~2~Barbell and plates~5.0~r~2~Abdominals, Lower back, Shoulders~Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.~Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position. Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement. After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out.~Pulling on the neck with the hands.", "Barbell Bench Press - Medium Grip~Chest~bench~2~Barbell and plates~5.0~r~0~Chest, Shoulders, Triceps~Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.~From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest. After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.~Bouncing the weight or lifting the hips off the bench.", "Barbell Curls Lying Against An Incline~Biceps~curl~2~Barbell and plates~3.5~r~0~Biceps~Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.~While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms. After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.~Swinging the body or moving the elbows forward.", "Barbell Full Squat~Quads~squat~2~Barbell and plates~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position. Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up.~Letting the knees cave inward or the heels lift.", "Barbell Glute Bridge~Glutes~bridge~2~Barbell and plates~6.0~r~1~Glutes, Calves, Hamstrings~Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.~Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet. Extend as far as possible, then reverse the motion to return to the starting position.~Arching the lower back instead of squeezing the glutes.", "Barbell Guillotine Bench Press~Chest~bench~2~Barbell and plates~5.0~r~1~Chest, Shoulders, Triceps~Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.~As you breathe in, bring the bar down slowly until it is about 1 inch from your neck. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up. When you are done, place the bar back in the rack.~Bouncing the weight or lifting the hips off the bench.", "Barbell Hack Squat~Quads~squat~2~Barbell and plates~5.0~r~1~Quadriceps, Calves, Forearms, Hamstrings~Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.~While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down. Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.~Letting the knees cave inward or the heels lift.", "Barbell Incline Bench Press - Medium Grip~Chest~bench~2~Barbell and plates~5.0~r~0~Chest, Shoulders, Triceps~Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.~As you breathe in, come down slowly until you feel the bar on you upper chest. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up. When you are done, place the bar back in the rack.~Bouncing the weight or lifting the hips off the bench.", "Barbell Incline Shoulder Raise~Shoulders~frontraise~2~Barbell and plates~5.0~r~0~Shoulders, Chest~Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.~While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out. Bring back the bar to the starting position as you breathe in.~Swinging the weight up with the body.", "Barbell Lunge~Quads~lunge~2~Barbell and plates~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint.~Letting the front knee drift inward or leaning the torso forward.", "Barbell Rear Delt Row~Shoulders~ohpress~2~Barbell and plates~5.0~r~0~Shoulders, Biceps, Lats, Middle back~Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.~Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter \"T\". Now you are ready to begin the exercise. While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out.~Arching the lower back to push the weight up.", "Barbell Rollout from Bench~Abs & core~crunch~2~Barbell and plates~5.0~r~1~Abdominals, Glutes, Hamstrings, Lats~Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.~To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement. When the bar has been moved as far forward as possible, return to the starting position.~Pulling on the neck with the hands.", "Barbell Seated Calf Raise~Calves~calf~2~Barbell and plates~3.5~r~0~Calves~Place a block about 12 inches in front of a flat bench.~Sit on the bench and place the ball of your feet on the block. Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position. Raise up on your toes as high as possible as you squeeze the calves and as you breathe out. After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.~Bouncing at the bottom instead of a full, slow stretch.", "Barbell Shoulder Press~Shoulders~ohpress~2~Barbell and plates~5.0~r~1~Shoulders, Chest, Triceps~Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).~Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position. Lower the bar down to the shoulders slowly as you inhale. Lift the bar back up to the starting position as you exhale.~Arching the lower back to push the weight up.", "Barbell Shrug Behind The Back~Back~row~2~Barbell and plates~3.5~r~0~Traps, Forearms, Middle back~Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.~Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times. Slowly return to the starting position as you breathe in.~Rounding the back or jerking the weight with the arms only.", "Barbell Side Bend~Abs & core~crunch~2~Barbell and plates~3.5~r~0~Abdominals, Lower back~Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.~While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary. Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.~Pulling on the neck with the hands.", "Barbell Side Split Squat~Quads~lunge~2~Barbell and plates~5.0~r~0~Quadriceps, Calves, Hamstrings, Lower back~Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.~Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body. Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement. After performing the recommended amount of reps, repeat the movement with the opposite leg.~Letting the front knee drift inward or leaning the torso forward.", "Barbell Squat~Quads~squat~2~Barbell and plates~5.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position.~Letting the knees cave inward or the heels lift.", "Barbell Squat To A Bench~Quads~squat~2~Barbell and plates~5.0~r~2~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.~Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out.~Letting the knees cave inward or the heels lift.", "Barbell Step Ups~Quads~stepup~2~Barbell and plates~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.~Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up. Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.~Pushing off the back foot instead of the working leg.", "Barbell Walking Lunge~Quads~lunge~2~Barbell and plates~5.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~Begin standing with your feet shoulder width apart and a barbell across your upper back.~Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot. Drive through the heel of your lead foot and extend both knees to raise yourself back up. Step forward with your rear foot, repeating the lunge on the opposite leg.~Letting the front knee drift inward or leaning the torso forward.", "Battling Ropes~Shoulders~ohpress~2~Gym equipment (see steps)~5.0~r~0~Shoulders, Chest, Forearms~For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.~Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can. As you let that arm drop to the starting position, raise the opposite side. Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.~Arching the lower back to push the weight up.", "Behind Head Chest Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~2~Chest, Shoulders~Sit upright on the floor with your partner behind you.~Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position. Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving. Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.~Bouncing into the stretch or pushing into pain.", "Bench Dips~Triceps~dips~0~None~5.0~r~0~Triceps, Chest, Shoulders~For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.~Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down. Using your triceps to bring your torso up again, lift yourself back to the starting position.~Dropping too deep and letting the shoulders roll forward.", "Bench Jump~Quads~jacks~0~None~8.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.~Perform a short squat in preparation for the jump; swing your arms behind you. Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up. Jump over the bench, landing with the knees bent, absorbing the impact through the legs. Turn around and face the opposite direction, then jump back over the bench.~Landing heavily on the heels.", "Bench Press - Powerlifting~Triceps~bench~2~Barbell and plates~6.0~r~1~Triceps, Chest, Forearms, Lats~Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.~However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times. Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.~Bouncing the weight or lifting the hips off the bench.", "Bench Press - With Bands~Chest~bench~1~A resistance band~5.0~r~0~Chest, Shoulders, Triceps~Using a flat bench secure a band under the leg of the bench that is nearest to your head.~Once the band is secure, grab it by both handles and lie down on the bench. Extend your arms so that you are holding the band handles in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times. As you breathe out, bring the handles up using your pectoral muscles.~Bouncing the weight or lifting the hips off the bench.", "Bench Press with Chains~Triceps~bench~2~Barbell and plates~6.0~r~2~Triceps, Chest, Lats, Shoulders~Adjust the leader chain, shortening it to the desired length. Place the chains on the sleeves of the bar.~Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders.~Bouncing the weight or lifting the hips off the bench.", "Bench Sprint~Quads~squat~2~Gym equipment (see steps)~8.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~Stand on the ground with one foot resting on a bench or box with your heel close to the edge.~Push off with your foot on top of the bench, extending through the hip and knee. Land with the opposite foot on top of the box, returning your other foot back to the start position. Continue alternating from one foot to another to complete the set.~Letting the knees cave inward or the heels lift.", "Bent-Arm Barbell Pullover~Back~row~2~Barbell and plates~5.0~r~1~Lats, Chest, Lats, Shoulders~Lie on a flat bench with a barbell using a shoulder grip width.~Hold the bar straight over your chest with a bend in your arms. This will be your starting position. While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest. At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.~Rounding the back or jerking the weight with the arms only.", "Bent-Arm Dumbbell Pullover~Chest~bench~1~Dumbbells~5.0~r~1~Chest, Lats, Shoulders, Triceps~Place a dumbbell standing up on a flat bench.~Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well. Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell.~Bouncing the weight or lifting the hips off the bench.", "Bent-Knee Hip Raise~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Lay flat on the floor with your arms next to your sides.~Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches. Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.~Pulling on the neck with the hands.", "Bent Over Dumbbell Rear Delt Raise With Head On Bench~Shoulders~frontraise~1~Dumbbells~3.5~r~0~Shoulders~Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.~While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.~Swinging the weight up with the body.", "Bent Over Low-Pulley Side Lateral~Shoulders~ohpress~2~Cable machine~3.5~r~0~Shoulders, Lower back, Middle back, Traps~Select a weight and hold the handle of the low pulley with your right hand.~Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position. Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.~Arching the lower back to push the weight up.", "Bent Over One-Arm Long Bar Row~Back~row~2~Barbell and plates~5.0~rs~0~Middle back, Biceps, Lats, Lower back~Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.~Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent. Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position. Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement.~Rounding the back or jerking the weight with the arms only.", "Bent Over Two-Arm Long Bar Row~Back~row~2~Barbell and plates~5.0~r~1~Middle back, Biceps, Lats~Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.~Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent. Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position. Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement.~Rounding the back or jerking the weight with the arms only.", "Bent Over Two-Dumbbell Row~Back~row~1~Dumbbells~5.0~r~0~Middle back, Biceps, Lats, Shoulders~With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.~While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second. Slowly lower the weight again to the starting position as you inhale.~Rounding the back or jerking the weight with the arms only.", "Bent Over Two-Dumbbell Row With Palms In~Back~row~1~Dumbbells~5.0~r~0~Middle back, Biceps, Lats~With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.~While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second. Slowly lower the weight again to the starting position as you inhale.~Rounding the back or jerking the weight with the arms only.", "Bent Press~Abs & core~crunch~1~A kettlebell~5.0~r~2~Abdominals, Glutes, Hamstrings, Lower back~Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.~Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground. Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.~Pulling on the neck with the hands.", "Bicycling~Cardio~cycle~2~Gym equipment (see steps)~7.0~t~0~Quadriceps, Calves, Glutes, Hamstrings~To begin, seat yourself on the bike and adjust the seat to your height.~Move slowly and with control through the full range.~A seat set too low, which strains the knees.", "Bicycling, Stationary~Cardio~cycle~2~Gym machine~7.0~t~0~Quadriceps, Calves, Glutes, Hamstrings~To begin, seat yourself on the bike and adjust the seat to your height.~Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.~A seat set too low, which strains the knees.", "Board Press~Triceps~bench~2~Barbell and plates~6.0~r~1~Triceps, Chest, Forearms, Lats~Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6's, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.~Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times.~Bouncing the weight or lifting the hips off the bench.", "Body-Up~Triceps~pushdown~0~None~3.5~r~1~Triceps, Abdominals, Forearms~Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.~Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement. Slowly lower your forearms back to the ground by allowing the elbows to flex.~Letting the elbows drift away from the sides.", "Body Tricep Press~Triceps~pushdown~0~None~3.5~r~0~Triceps~Position a bar in a rack at chest height.~Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position. Begin by flexing the elbow, lowering yourself towards the bar. Pause, and then reverse the motion by extending the elbows. Progress from bodyweight by adding chains over your shoulders.~Letting the elbows drift away from the sides.", "Bodyweight Flyes~Chest~bench~2~EZ curl bar~3.5~r~1~Chest, Abdominals, Shoulders, Triceps~Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.~Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight. Place your hands on the bars. This will be your starting position. Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion. After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement.~Bouncing the weight or lifting the hips off the bench.", "Bodyweight Mid Row~Back~row~2~Gym equipment (see steps)~5.0~r~1~Middle back, Biceps, Lats~Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.~Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus. After a brief pause, return to the starting position.~Rounding the back or jerking the weight with the arms only.", "Bodyweight Squat~Quads~squat~0~None~5.0~r~0~Quadriceps, Glutes, Hamstrings~Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.~Begin the movement by flexing your knees and hips, sitting back with your hips. Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.~Letting the knees cave inward or the heels lift.", "Bodyweight Walking Lunge~Quads~lunge~0~None~5.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~Begin standing with your feet shoulder width apart and your hands on your hips.~Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot. Drive through the heel of your lead foot and extend both knees to raise yourself back up. Step forward with your rear foot, repeating the lunge on the opposite leg.~Letting the front knee drift inward or leaning the torso forward.", "Bosu Ball Cable Crunch With Side Bends~Abs & core~crunch~2~Cable machine~3.5~r~0~Abdominals~Connect a standard handle to each arm of a cable machine, and position them in the most downward position.~Grab a Bosu Ball and position it in front and center of the cable machine. Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it. With both hands, reach back and grab the handle of each cable. With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level. Keep your arms straight and in-line with the upward angle of the cable.~Pulling on the neck with the hands.", "Bottoms-Up Clean From The Hang Position~Forearms~curl~1~A kettlebell~5.0~r~1~Forearms, Biceps, Shoulders~Initiate the exercise by standing upright with a kettlebell in one hand.~Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.~Swinging the body or moving the elbows forward.", "Bottoms Up~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.~To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor. After a brief pause, return to the starting position.~Pulling on the neck with the hands.", "Box Jump (Multiple Response)~Hamstrings~rdl~2~Gym equipment (see steps)~8.0~r~0~Hamstrings, Abductors, Adductors, Calves~Assume a relaxed stance facing the box or platform approximately an arm's length away. Arms should be down at the sides and legs slightly bent.~Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform. Immediately drop or jump back down to the original starting place; then repeat the sequence.~Rounding the lower back instead of hinging at the hips.", "Box Skip~Hamstrings~rdl~2~Gym equipment (see steps)~8.0~r~0~Hamstrings, Abductors, Adductors, Calves~You will need several boxes lined up about 8 feet apart.~Begin facing the first box with one leg slightly behind the other. Drive off the back leg, attempting to gain as much height with the hips as possible. Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box. Then, step to the next box and repeat.~Rounding the lower back instead of hinging at the hips.", "Box Squat with Bands~Quads~squat~2~Barbell and plates~6.0~r~2~Quadriceps, Abductors, Adductors, Calves~Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don't move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.~Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.~Letting the knees cave inward or the heels lift.", "Box Squat with Chains~Quads~squat~2~Barbell and plates~5.0~r~2~Quadriceps, Abductors, Adductors, Calves~Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.~To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.~Letting the knees cave inward or the heels lift.", "Brachialis-SMR~Mobility~stretch~1~A foam roller~2.3~h~1~Biceps~Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.~Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides.~Bouncing into the stretch or pushing into pain.", "Bradford/Rocky Presses~Shoulders~ohpress~2~Barbell and plates~5.0~r~0~Shoulders, Triceps~Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.~Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms. Now lower the bar down to the back of the head slowly as you inhale. Lift the bar back up to the starting position as you exhale. Lower the bar down to the starting position slowly as you inhale. This is one repetition. Alternate in this manner until you complete the recommended amount of repetitions.~Arching the lower back to push the weight up.", "Butt-Ups~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.~Arch your back slightly out rather than keeping your back completely straight. Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you'll end up in a high bridge position. Exhale as you perform this portion of the movement. Lower back down slowly to your starting position as you breathe in. Tip: Don't let your back sag downwards.~Pulling on the neck with the hands.", "Butt Lift (Bridge)~Glutes~bridge~0~None~3.5~r~0~Glutes, Hamstrings~Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.~Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second. Slowly go back to the starting position as you breathe in.~Arching the lower back instead of squeezing the glutes.", "Butterfly~Chest~bench~2~Gym machine~3.5~r~0~Chest~Sit on the machine with your back flat on the pad.~Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position. Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second. Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.~Bouncing the weight or lifting the hips off the bench.", "Cable Chest Press~Chest~bench~2~Cable machine~5.0~r~0~Chest, Shoulders, Triceps~Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.~Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement. After pausing at full extension, return to th starting position, keeping tension on the cables. You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.~Bouncing the weight or lifting the hips off the bench.", "Cable Deadlifts~Quads~squat~2~Cable machine~5.0~r~0~Quadriceps, Forearms, Glutes, Hamstrings~Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.~To begin, squat down be flexing your hips and knees until you can reach the handles. After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement. After reaching a full standing position, Return to the starting position and repeat.~Letting the knees cave inward or the heels lift.", "Cable Hammer Curls - Rope Attachment~Biceps~curl~2~Cable machine~3.5~r~0~Biceps~Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.~Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary. Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position. Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.~Swinging the body or moving the elbows forward.", "Cable Hip Adduction~Quads~squat~2~Cable machine~3.5~r~0~Quadriceps~Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.~Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley. Now step out and away from the stack with a wide stance and grasp the bar of the pulley system. Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position. Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip.~Letting the knees cave inward or the heels lift.", "Cable Incline Pushdown~Back~row~2~Cable machine~3.5~r~0~Lats~Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.~Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position. Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.~Rounding the back or jerking the weight with the arms only.", "Cable Incline Triceps Extension~Triceps~pushdown~2~Cable machine~3.5~r~0~Triceps~Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.~Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor. Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second. Slowly go back to the starting position.~Letting the elbows drift away from the sides.", "Cable Internal Rotation~Shoulders~ohpress~2~Cable machine~5.0~r~0~Shoulders~Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley's height, you can use a flat bench to sit on instead.~Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position. Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times. Slowly go back to the initial position.~Arching the lower back to push the weight up.", "Cable Iron Cross~Chest~bench~2~Cable machine~3.5~r~0~Chest~Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.~Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a \"T\". This will be your starting position. Keeping the elbows extended, pull your arms straight to your sides. Return your arms back to the starting position after a pause at the peak contraction. Continue the movement for the prescribed number of repetitions.~Bouncing the weight or lifting the hips off the bench.", "Cable Judo Flip~Abs & core~crunch~2~Cable machine~5.0~r~0~Abdominals~Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.~Twist your body away from the pulley as you bring the rope over your shoulder like you're performing a judo flip. Shift your weight between your feet as you twist and crunch forward, pulling the cable downward. Return to the starting position and repeat until failure. Then, reposition and repeat the same series of movements on the opposite side.~Pulling on the neck with the hands.", "Cable Lying Triceps Extension~Triceps~pushdown~2~Cable machine~3.5~r~0~Triceps~Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.~With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position. Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement. Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.~Letting the elbows drift away from the sides.", "Cable One Arm Tricep Extension~Triceps~pushdown~2~Cable machine~3.5~rs~0~Triceps~With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.~Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position. As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement.~Letting the elbows drift away from the sides.", "Cable Preacher Curl~Biceps~curl~2~Cable machine~3.5~r~0~Biceps, Forearms~Place a preacher bench about 2 feet in front of a pulley machine.~Attach a straight bar to the low pulley. Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley. Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position. Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.~Swinging the body or moving the elbows forward.", "Cable Rear Delt Fly~Shoulders~frontraise~2~Cable machine~3.5~r~0~Shoulders~Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.~Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position. Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement. Pause at the end of the motion before returning the handles to the start position.~Swinging the weight up with the body.", "Cable Reverse Crunch~Abs & core~crunch~2~Cable machine~3.5~r~0~Abdominals~Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.~Sit down with your feet toward the pulley and attach the cable to your ankles. Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are. With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor. Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle.~Pulling on the neck with the hands.", "Cable Rope Overhead Triceps Extension~Triceps~pushdown~2~Cable machine~3.5~r~0~Triceps~Attach a rope to the bottom pulley of the pulley machine.~Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position. Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.~Letting the elbows drift away from the sides.", "Cable Rope Rear-Delt Rows~Shoulders~ohpress~2~Cable machine~5.0~r~0~Shoulders, Biceps, Middle back~Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.~Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out. Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position. Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back.~Arching the lower back to push the weight up.", "Cable Russian Twists~Abs & core~crunch~2~Cable machine~5.0~r~0~Abdominals~Connect a standard handle attachment, and position the cable to a middle pulley position.~Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are. Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation.~Pulling on the neck with the hands.", "Cable Seated Crunch~Abs & core~crunch~2~Cable machine~3.5~r~0~Abdominals~Seat on a flat bench with your back facing a high pulley.~Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position. With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step. As you inhale, go back to the initial position slowly.~Pulling on the neck with the hands.", "Cable Seated Lateral Raise~Shoulders~frontraise~2~Cable machine~3.5~r~0~Shoulders, Middle back, Traps~Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.~Now sit at the edge of the flat bench behind you with your feet placed in front of your knees. Bend forward while keeping your back flat and rest your torso on the thighs. Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.~Swinging the weight up with the body.", "Cable Shoulder Press~Shoulders~ohpress~2~Cable machine~5.0~r~0~Shoulders, Triceps~Move the cables to the bottom of the towers and select an appropriate weight.~Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press the handles directly over head. After pausing at the top, return to the starting position and repeat.~Arching the lower back to push the weight up.", "Cable Shrugs~Back~cablerow~2~Cable machine~3.5~r~0~Traps~Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.~Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position. Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down. Lower the bar back to the original position.~Rocking the whole body back and forth.", "Cable Wrist Curl~Forearms~curl~2~Cable machine~3.5~r~0~Forearms~Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.~Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees. Start out by curling your wrist upwards and exhaling. Keep the contraction for a second. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.~Swinging the body or moving the elbows forward.", "Calf-Machine Shoulder Shrug~Back~row~2~Gym machine~3.5~r~0~Traps~Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.~Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second. Slowly return to the starting position as you inhale.~Rounding the back or jerking the weight with the arms only.", "Calf Press~Calves~calf~2~Gym machine~3.5~r~0~Calves~Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.~Select an appropriate weight, and grasp the handles. This will be your starting position. Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible. After a brief pause, reverse the motion and repeat.~Bouncing at the bottom instead of a full, slow stretch.", "Calf Press On The Leg Press Machine~Calves~calf~2~Gym machine~3.5~r~0~Calves~Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.~Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle.~Bouncing at the bottom instead of a full, slow stretch.", "Calf Raise On A Dumbbell~Calves~calf~1~Dumbbells~3.5~r~1~Calves~Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.~Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position. Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward. Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.~Bouncing at the bottom instead of a full, slow stretch.", "Calf Raises - With Bands~Calves~calf~1~A resistance band~3.5~r~0~Calves~Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.~While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position. Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement. After a one second contraction, slowly go back down to the starting position.~Bouncing at the bottom instead of a full, slow stretch.", "Calf Stretch Elbows Against Wall~Mobility~stretch~0~None~2.3~h~0~Calves~Stand facing a wall from a couple feet away.~Lean against the wall, placing your weight on your forearms. Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively.~Bouncing into the stretch or pushing into pain.", "Calf Stretch Hands Against Wall~Mobility~stretch~0~None~2.3~h~0~Calves~Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.~Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line. Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.~Bouncing into the stretch or pushing into pain.", "Calves-SMR~Mobility~stretch~1~A foam roller~2.3~h~1~Calves~Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.~Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg.~Bouncing into the stretch or pushing into pain.", "Car Drivers~Shoulders~ohpress~2~Barbell and plates~3.5~r~0~Shoulders, Forearms~While standing upright, hold a barbell plate in both hands at the 3 and 9 o'clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.~Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side. Reverse the motion, turning it all the way to the opposite side.~Arching the lower back to push the weight up.", "Carioca Quick Step~Glutes~lunge~0~None~8.0~r~0~Adductors, Abdominals, Abductors, Calves~Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.~With your right foot, quick step behind and pull the knee up. Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.~Letting the front knee drift inward or leaning the torso forward.", "Cat Stretch~Mobility~stretch~0~None~2.3~h~0~Lower back, Middle back, Traps~Position yourself on the floor on your hands and knees.~Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop. Hold for 15 seconds.~Bouncing into the stretch or pushing into pain.", "Catch and Overhead Throw~Back~row~1~A medicine ball~8.0~r~0~Lats, Abdominals, Chest, Shoulders~Begin standing while facing a wall or a partner.~Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward. Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.~Rounding the back or jerking the weight with the arms only.", "Chain Handle Extension~Triceps~pushdown~2~Gym equipment (see steps)~6.0~r~1~Triceps~You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.~Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated. Pause at the lockout, and reverse the motion to return to the starting position.~Letting the elbows drift away from the sides.", "Chain Press~Chest~bench~2~Gym equipment (see steps)~6.0~r~1~Chest, Shoulders, Triceps~Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.~Lower the chains by flexing the elbows, unloading some of the chain onto the floor. Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout.~Bouncing the weight or lifting the hips off the bench.", "Chair Leg Extended Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~0~Hamstrings, Adductors~Sit upright in a chair and grip the seat on the sides.~Raise one leg, extending the knee, flexing the ankle as you do so. Slowly move that leg outward as far as you can, and then back to the center and down.~Bouncing into the stretch or pushing into pain.", "Chair Lower Back Stretch~Mobility~stretch~0~None~2.3~h~0~Lats, Lower back~Sit upright on a chair.~Bend to one side with your arm over your head. You can hold onto the chair with your free hand. Hold for 10 seconds, and repeat for your other side.~Bouncing into the stretch or pushing into pain.", "Chair Squat~Quads~squat~2~Gym machine~5.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.~Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position. Slowly lower the bar by bending the knees as you maintain a straight posture with the head up.~Letting the knees cave inward or the heels lift.", "Chair Upper Body Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~0~Shoulders, Biceps, Chest~Sit on the edge of a chair, gripping the back of it.~Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds.~Bouncing into the stretch or pushing into pain.", "Chest And Front Of Shoulder Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~0~Chest, Shoulders~Start off by standing with your legs together, holding a bodybar or a broomstick.~Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down. Carefully lift the pole up and behind your head.~Bouncing into the stretch or pushing into pain.", "Chest Push from 3 point stance~Chest~bench~1~A medicine ball~8.0~r~0~Chest, Abdominals, Shoulders, Triceps~Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.~To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw. As you execute the second step, explosively release the ball forward as hard as possible.~Bouncing the weight or lifting the hips off the bench.", "Chest Push (multiple response)~Chest~bench~1~A medicine ball~8.0~r~0~Chest, Abdominals, Shoulders, Triceps~Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.~Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible. Follow through by falling forward, catching yourself with your hands. Immediately return to an upright position. Repeat for the desired number of repetitions.~Bouncing the weight or lifting the hips off the bench.", "Chest Push (single response)~Chest~bench~1~A medicine ball~8.0~rs~0~Chest, Abdominals, Shoulders, Triceps~Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.~Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible. Follow through by falling forward, catching yourself with your hands.~Bouncing the weight or lifting the hips off the bench.", "Chest Push with Run Release~Chest~bench~1~A medicine ball~8.0~r~0~Chest, Abdominals, Shoulders, Triceps~Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.~While taking your first step draw the medicine ball into your chest. As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!~Bouncing the weight or lifting the hips off the bench.", "Chest Stretch on Stability Ball~Mobility~stretch~1~An exercise ball~2.3~h~0~Chest~Get on your hands and knees next to an exercise ball.~Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position. Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm.~Bouncing into the stretch or pushing into pain.", "Chin To Chest Stretch~Mobility~stretch~0~None~2.3~h~0~Neck, Traps~Get into a seated position on the floor.~Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds.~Bouncing into the stretch or pushing into pain.", "Clean~Full body~rdl~2~Barbell and plates~6.0~r~1~Hamstrings, Calves, Forearms, Glutes~With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.~Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.~Rounding the lower back instead of hinging at the hips.", "Clean Deadlift~Full body~deadlift~2~Barbell and plates~6.0~r~0~Hamstrings, Forearms, Glutes, Lower back~Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.~Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar's path. After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended.~Rounding the back or jerking the weight off the floor.", "Clean Pull~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Forearms, Glutes, Hamstrings~With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.~Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.~Letting the knees cave inward or the heels lift.", "Clean Shrug~Full body~row~2~Barbell and plates~6.0~r~0~Traps, Forearms, Shoulders~Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.~Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.~Rounding the back or jerking the weight with the arms only.", "Clean and Jerk~Full body~ohpress~2~Barbell and plates~6.0~r~2~Shoulders, Abdominals, Glutes, Hamstrings~With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.~Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.~Arching the lower back to push the weight up.", "Clean and Press~Shoulders~ohpress~2~Barbell and plates~5.0~r~1~Shoulders, Abdominals, Calves, Glutes~Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.~Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body. As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible.~Arching the lower back to push the weight up.", "Clean from Blocks~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.~Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out. As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so.~Letting the knees cave inward or the heels lift.", "Clock Push-Up~Chest~pushup~0~None~5.0~r~1~Chest, Shoulders, Triceps~Move into a prone position on the floor, supporting your weight on your hands and toes.~Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position. Descend by flexing at the elbow, lowering your chest toward the ground. At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to \"jump\" 12-18 inches to one side. As you accelerate up, move your outside foot away from your direction of travel.~Letting the hips sag or flaring the elbows wide.", "Close-Grip Barbell Bench Press~Triceps~bench~2~Barbell and plates~5.0~r~0~Triceps, Chest, Shoulders~Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.~As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again.~Bouncing the weight or lifting the hips off the bench.", "Close-Grip Dumbbell Press~Triceps~pushdown~1~Dumbbells~5.0~r~0~Triceps, Chest, Shoulders~Place a dumbbell standing up on a flat bench.~Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor. Grasp the dumbbell with both hands and hold it straight over your chest at arm's length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position. Initiate the movement by lowering the dumbbell to your chest.~Letting the elbows drift away from the sides.", "Close-Grip EZ-Bar Curl with Band~Biceps~curl~2~EZ curl bar~3.5~r~0~Biceps, Forearms~Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.~While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard. Slowly begin to bring the bar back to starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Close-Grip EZ-Bar Press~Triceps~pushdown~2~EZ curl bar~5.0~r~0~Triceps, Chest, Shoulders~Lie on a flat bench with an EZ bar loaded to an appropriate weight.~Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position. Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement. Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.~Letting the elbows drift away from the sides.", "Close-Grip EZ Bar Curl~Biceps~curl~2~Barbell and plates~3.5~r~0~Biceps, Forearms~Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.~While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard. Slowly begin to bring the bar back to starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Close-Grip Front Lat Pulldown~Back~latpull~2~Cable machine~5.0~r~0~Lats, Biceps, Middle back, Shoulders~Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.~Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.~Leaning far back or pulling behind the neck.", "Close-Grip Push-Up off of a Dumbbell~Triceps~pushup~0~None~5.0~r~1~Triceps, Abdominals, Chest, Shoulders~Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.~Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag. Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step. After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions.~Letting the hips sag or flaring the elbows wide.", "Close-Grip Standing Barbell Curl~Biceps~curl~2~Barbell and plates~3.5~r~0~Biceps, Forearms~Hold a barbell with both hands, palms up and a few inches apart.~Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement. Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight.~Swinging the body or moving the elbows forward.", "Cocoons~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.~To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion. After a brief pause, return to the starting position.~Pulling on the neck with the hands.", "Concentration Curls~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps, Forearms~Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.~Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position. While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move.~Swinging the body or moving the elbows forward.", "Cross-Body Crunch~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Lie flat on your back and bend your knees about 60 degrees.~Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position. Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement.~Pulling on the neck with the hands.", "Cross Over - With Bands~Chest~bench~1~A resistance band~5.0~r~0~Chest, Biceps, Shoulders~Secure an exercise band around a stationary post.~While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band. Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter \"T\") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.~Bouncing the weight or lifting the hips off the bench.", "Crossover Reverse Lunge~Mobility~stretch~0~None~2.3~h~1~Lower back, Abdominals, Abductors, Glutes~Stand with your feet shoulder width apart. This will be your starting position.~Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg. After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion.~Bouncing into the stretch or pushing into pain.", "Crunch - Hands Overhead~Abs & core~crunch~0~None~3.5~r~0~Abdominals~Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.~Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position. Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don't move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second. Slowly lower down to the starting position as you inhale.~Pulling on the neck with the hands.", "Crunch - Legs On Exercise Ball~Abs & core~crunch~0~None~3.5~r~0~Abdominals~Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.~Place your feet three to four inches apart and point your toes inward so they touch. Place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head. Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position. Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back.~Pulling on the neck with the hands.", "Crunches~Abs & core~crunch~0~None~3.5~r~0~Abdominals~Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.~Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head. While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor. Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor.~Pulling on the neck with the hands.", "Cuban Press~Shoulders~ohpress~1~Dumbbells~5.0~r~1~Shoulders, Traps~Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the \"scarecrow\" position. This will be your starting position.~To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor. Now press the dumbbells by extending at the elbows, straightening your arms overhead. Return to the starting position as you breathe in by reversing the steps.~Arching the lower back to push the weight up.", "Dancer's Stretch~Mobility~stretch~0~None~2.3~h~0~Lower back, Abductors, Glutes~Sit up on the floor.~Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor. Place your left arm on your right leg and your right hand on the floor. Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.~Bouncing into the stretch or pushing into pain.", "Deadlift with Bands~Back~deadlift~2~Barbell and plates~6.0~r~2~Lower back, Forearms, Glutes, Hamstrings~To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.~With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar. Lower the bar by bending at the hips and guiding it to the floor.~Rounding the back or jerking the weight off the floor.", "Deadlift with Chains~Back~deadlift~2~Barbell and plates~6.0~r~2~Lower back, Forearms, Glutes, Hamstrings~You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.~Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.~Rounding the back or jerking the weight off the floor.", "Decline Close-Grip Bench To Skull Crusher~Triceps~pushdown~2~Barbell and plates~5.0~r~1~Triceps, Chest, Shoulders~Secure your legs at the end of the decline bench and slowly lay down on the bench.~Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack. Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.~Letting the elbows drift away from the sides.", "Decline Crunch~Abs & core~crunch~0~None~3.5~r~1~Abdominals~Secure your legs at the end of the decline bench and lie down.~Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head. While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it. Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench.~Pulling on the neck with the hands.", "Decline Dumbbell Bench Press~Chest~bench~1~Dumbbells~5.0~r~0~Chest, Shoulders, Triceps~Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.~Once you are laying down, move the dumbbells in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor. As you breathe out, push the dumbbells up using your pectoral muscles.~Bouncing the weight or lifting the hips off the bench.", "Decline Dumbbell Flyes~Chest~bench~1~Dumbbells~5.0~r~0~Chest~Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.~Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position. With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement.~Bouncing the weight or lifting the hips off the bench.", "Decline Dumbbell Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~r~0~Triceps~Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.~Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position. As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.~Letting the elbows drift away from the sides.", "Decline EZ Bar Triceps Extension~Triceps~pushdown~2~Barbell and plates~3.5~r~0~Triceps~Secure your legs at the end of the decline bench and slowly lay down on the bench.~Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.~Letting the elbows drift away from the sides.", "Decline Oblique Crunch~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Secure your legs at the end of the decline bench and slowly lay down on the bench.~Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor. Put one hand beside your head and the other on your thigh. This will be your starting position. Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.~Pulling on the neck with the hands.", "Decline Reverse Crunch~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don't let your body slip down from this position.~Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position. While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest. Hold the contraction for a second and move your legs back to the starting position while inhaling.~Pulling on the neck with the hands.", "Decline Smith Press~Chest~bench~2~Gym machine~5.0~r~0~Chest, Shoulders, Triceps~Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.~As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso. After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so. When the set is complete, lock the bar back in the rack.~Bouncing the weight or lifting the hips off the bench.", "Deficit Deadlift~Back~deadlift~2~Barbell and plates~6.0~r~1~Lower back, Forearms, Glutes, Hamstrings~Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.~With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar. Lower the bar by bending at the hips and guiding it to the floor.~Rounding the back or jerking the weight off the floor.", "Depth Jump Leap~Quads~jacks~2~Gym equipment (see steps)~8.0~r~0~Quadriceps, Abductors, Adductors, Calves~For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.~Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer. Begin by dropping off the initial box, landing and simultaneously taking off with both feet. Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact.~Landing heavily on the heels.", "Dip Machine~Triceps~dips~2~Gym machine~5.0~r~0~Triceps, Chest, Shoulders~Sit securely in a dip machine, select the weight and firmly grasp the handles.~Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle. As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle. Now slowly let your arms come back up to the starting position as you inhale.~Dropping too deep and letting the shoulders roll forward.", "Dips - Chest Version~Chest~dips~2~Gym equipment (see steps)~5.0~r~1~Chest, Shoulders, Triceps~For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.~While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest. Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.~Dropping too deep and letting the shoulders roll forward.", "Dips - Triceps Version~Triceps~dips~0~None~5.0~r~0~Triceps, Chest, Shoulders~To get into the starting position, hold your body at arm's length with your arms nearly locked above the bars.~Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm. Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.~Dropping too deep and letting the shoulders roll forward.", "Donkey Calf Raises~Calves~calf~2~Gym equipment (see steps)~3.5~r~1~Calves~For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.~Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position. Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time.~Bouncing at the bottom instead of a full, slow stretch.", "Double Kettlebell Alternating Hang Clean~Hamstrings~rdl~1~A kettlebell~5.0~rs~1~Hamstrings, Biceps, Calves, Forearms~Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.~Clean one kettlebell to your shoulder and hold on to the other kettlebell. With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up.~Rounding the lower back instead of hinging at the hips.", "Double Kettlebell Jerk~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Calves, Quadriceps, Triceps~Hold a kettlebell by the handle in each hand.~Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum.~Arching the lower back to push the weight up.", "Double Kettlebell Push Press~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Calves, Quadriceps, Triceps~Clean two kettlebells to your shoulders.~Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead. Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.~Arching the lower back to push the weight up.", "Double Kettlebell Snatch~Shoulders~ohpress~1~A kettlebell~5.0~r~2~Shoulders, Glutes, Hamstrings, Quadriceps~Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.~Swing the kettlebells between your legs forcefully and reverse the direction. Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.~Arching the lower back to push the weight up.", "Double Kettlebell Windmill~Abs & core~crunch~1~A kettlebell~3.5~r~1~Abdominals, Glutes, Hamstrings, Shoulders~Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.~Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.~Pulling on the neck with the hands.", "Double Leg Butt Kick~Quads~squat~0~None~8.0~r~0~Quadriceps, Abductors, Adductors, Calves~Begin standing with your knees slightly bent.~Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height. As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks. Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.~Letting the knees cave inward or the heels lift.", "Downward Facing Balance~Glutes~bridge~1~An exercise ball~3.5~h~1~Glutes, Abdominals, Hamstrings~Lie facedown on top of an exercise ball.~While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.~Arching the lower back instead of squeezing the glutes.", "Drop Push~Chest~bench~2~Gym equipment (see steps)~8.0~r~1~Chest, Shoulders, Triceps~Position low boxes or other platforms 2-3 feet apart.~Move to a pushup position between them, supporting yourself by placing your hands on the boxes. With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm.~Bouncing the weight or lifting the hips off the bench.", "Dumbbell Alternate Bicep Curl~Biceps~curl~1~Dumbbells~3.5~rs~0~Biceps, Forearms~Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.~While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move. Slowly begin to bring the dumbbell back to the starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Dumbbell Bench Press with Neutral Grip~Chest~bench~1~Dumbbells~5.0~r~0~Chest, Shoulders, Triceps~Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.~Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position. Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso. Pause, then extend the elbow and return to the starting position.~Bouncing the weight or lifting the hips off the bench.", "Dumbbell Bicep Curl~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps, Forearms~Stand up straight with a dumbbell in each hand at arm's length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.~Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position.~Swinging the body or moving the elbows forward.", "Dumbbell Clean~Hamstrings~rdl~1~Dumbbells~5.0~r~1~Hamstrings, Calves, Forearms, Glutes~Begin standing with a dumbbell in each hand with your feet shoulder width apart.~Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position. To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached. After full extension, rebend the hips and knees to receive the weight in a squat position.~Rounding the lower back instead of hinging at the hips.", "Dumbbell Flyes~Chest~bench~1~Dumbbells~3.5~r~0~Chest~Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.~Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you're pressing them, but stop and hold just before you lock out. This will be your starting position. With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest.~Bouncing the weight or lifting the hips off the bench.", "Dumbbell Incline Row~Back~row~1~Dumbbells~5.0~r~0~Middle back, Biceps, Forearms, Lats~Using a neutral grip, lean into an incline bench.~Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position. Retract the shoulder blades and flex the elbows to row the dumbbells to your side. Pause at the top of the motion, and then return to the starting position.~Rounding the back or jerking the weight with the arms only.", "Dumbbell Incline Shoulder Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~0~Shoulders, Triceps~Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.~Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position. While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out. Bring back the dumbbells to the starting position as you breathe in.~Swinging the weight up with the body.", "Dumbbell Lunges~Quads~lunge~1~Dumbbells~5.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.~Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.~Letting the front knee drift inward or leaning the torso forward.", "Dumbbell Lying One-Arm Rear Lateral Raise~Shoulders~frontraise~1~Dumbbells~3.5~rs~1~Shoulders, Middle back~While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability.~Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position. Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.~Swinging the weight up with the body.", "Dumbbell Lying Pronation~Forearms~curl~1~Dumbbells~3.5~r~1~Forearms~Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.~Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.~Swinging the body or moving the elbows forward.", "Dumbbell Lying Rear Lateral Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~1~Shoulders~While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.~Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position. Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.~Swinging the weight up with the body.", "Dumbbell Lying Supination~Forearms~curl~1~Dumbbells~3.5~r~1~Forearms~Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.~Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.~Swinging the body or moving the elbows forward.", "Dumbbell One-Arm Shoulder Press~Shoulders~ohpress~1~Dumbbells~5.0~rs~1~Shoulders, Triceps~Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.~Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. Rotate the wrist so that the palm of your hand is facing forward. This is your starting position. As you exhale, push the dumbbell up until your arm is fully extended. After a second pause, slowly come down back to the starting position as you inhale.~Arching the lower back to push the weight up.", "Dumbbell One-Arm Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~rs~1~Triceps~Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.~Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface. Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.~Letting the elbows drift away from the sides.", "Dumbbell One-Arm Upright Row~Shoulders~ohpress~1~Dumbbells~5.0~rs~1~Shoulders, Biceps, Traps~Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs.~Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position. Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm.~Arching the lower back to push the weight up.", "Dumbbell Prone Incline Curl~Biceps~curl~1~Dumbbells~3.5~r~1~Biceps~Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).~Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor. Now keep your elbows in by your side and face the palms forward. This will be your starting position. Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times. Lower the dumbbells until your arms are fully extended.~Swinging the body or moving the elbows forward.", "Dumbbell Raise~Shoulders~frontraise~1~Dumbbells~5.0~r~0~Shoulders, Biceps~Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back.~Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement. Lower the dumbbells back down slowly to the starting position.~Swinging the weight up with the body.", "Dumbbell Rear Lunge~Quads~lunge~1~Dumbbells~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.~Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important.~Letting the front knee drift inward or leaning the torso forward.", "Dumbbell Scaption~Shoulders~ohpress~1~Dumbbells~3.5~r~0~Shoulders, Traps~This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.~Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement. Continue until your arms are parallel to the ground, and then return to the starting position.~Arching the lower back to push the weight up.", "Dumbbell Seated Box Jump~Quads~jacks~1~Dumbbells~8.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.~Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward. Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend. Step down and return to the starting position.~Landing heavily on the heels.", "Dumbbell Seated One-Leg Calf Raise~Calves~calf~1~Dumbbells~3.5~rs~0~Calves~Place a block on the floor about 12 inches from a flat bench.~Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee. Now place the ball of your left foot on the block. This will be your starting position. Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second. Slowly return to the starting position, stretching as far down as possible.~Bouncing at the bottom instead of a full, slow stretch.", "Dumbbell Shoulder Press~Shoulders~ohpress~1~Dumbbells~5.0~r~1~Shoulders, Triceps~While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.~Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position. Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position. Now, exhale and push the dumbbells upward until they touch at the top. Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.~Arching the lower back to push the weight up.", "Dumbbell Squat~Quads~goblet~1~Dumbbells~5.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).~Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.~Letting the chest drop forward.", "Dumbbell Squat To A Bench~Quads~goblet~1~Dumbbells~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).~Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.~Letting the chest drop forward.", "Dumbbell Tricep Extension -Pronated Grip~Triceps~pushdown~1~Dumbbells~3.5~r~0~Triceps~Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.~The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position. Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in. Then, exhale and use your triceps to return the weight to the starting position.~Letting the elbows drift away from the sides.", "Dynamic Back Stretch~Mobility~stretch~0~None~2.3~h~0~Lats~Stand with your feet shoulder width apart. This will be your starting position.~Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head.~Bouncing into the stretch or pushing into pain.", "Dynamic Chest Stretch~Mobility~stretch~0~None~2.3~h~0~Chest, Middle back~Stand with your hands together, arms extended directly in front of you. This will be your starting position.~Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so.~Bouncing into the stretch or pushing into pain.", "Elbow Circles~Mobility~stretch~0~None~2.3~h~0~Shoulders, Traps~Sit or stand with your feet slightly apart.~Place your hands on your shoulders with your elbows at shoulder level and pointing out. Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle.~Bouncing into the stretch or pushing into pain.", "Elbow to Knee~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.~Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee. Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.~Pulling on the neck with the hands.", "Elbows Back~Mobility~stretch~0~None~2.3~h~0~Chest, Shoulders~Stand up straight.~Place both hands on your lower back, fingers pointing downward and elbows out. Then gently pull your elbows back aiming to touch them together.~Bouncing into the stretch or pushing into pain.", "Elevated Back Lunge~Quads~lunge~2~Barbell and plates~5.0~r~1~Quadriceps, Glutes, Hamstrings~Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.~Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position. Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor. Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating.~Letting the front knee drift inward or leaning the torso forward.", "Elevated Cable Rows~Back~row~2~Cable machine~5.0~r~1~Lats, Middle back, Traps~Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.~Place it on the seat of the cable row machine. Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the V-bar handles. With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out.~Rounding the back or jerking the weight with the arms only.", "Exercise Ball Crunch~Abs & core~crunch~1~An exercise ball~3.5~r~0~Abdominals~Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).~Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position. With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball.~Pulling on the neck with the hands.", "Exercise Ball Pull-In~Abs & core~crunch~1~An exercise ball~5.0~r~0~Abdominals~Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.~Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position. While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles.~Pulling on the neck with the hands.", "Extended Range One-Arm Kettlebell Floor Press~Chest~bench~1~A kettlebell~5.0~rs~0~Chest, Shoulders, Triceps~Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.~Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position.~Bouncing the weight or lifting the hips off the bench.", "External Rotation~Shoulders~ohpress~1~Dumbbells~3.5~r~0~Shoulders~Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.~Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso. Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times).~Arching the lower back to push the weight up.", "External Rotation with Band~Shoulders~ohpress~1~A resistance band~5.0~r~0~Shoulders~Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.~Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position. With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position. Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.~Arching the lower back to push the weight up.", "External Rotation with Cable~Shoulders~ohpress~2~Cable machine~3.5~r~0~Shoulders~Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away.~Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position. With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position. Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.~Arching the lower back to push the weight up.", "Face Pull~Shoulders~ohpress~2~Cable machine~5.0~r~1~Shoulders, Middle back~Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.~Move slowly and with control through the full range.~Arching the lower back to push the weight up.", "Fast Skipping~Quads~squat~0~None~8.0~r~0~Quadriceps, Abductors, Adductors, Calves~Start in a relaxed position with one leg slightly forward. This will be your starting position.~Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth. Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.~Letting the knees cave inward or the heels lift.", "Finger Curls~Forearms~curl~2~Barbell and plates~3.5~r~0~Forearms~Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.~Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position. Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers. Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.~Swinging the body or moving the elbows forward.", "Flat Bench Cable Flyes~Chest~bench~2~Cable machine~3.5~r~1~Chest~Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.~Lay flat on the bench and keep your feet on the ground. Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip. Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.~Bouncing the weight or lifting the hips off the bench.", "Flat Bench Leg Pull-In~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Lie on an exercise mat or a flat bench with your legs off the end.~Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position. Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second. As you breathe in, slowly return to the starting position.~Pulling on the neck with the hands.", "Flat Bench Lying Leg Raise~Abs & core~legraise~0~None~3.5~r~0~Abdominals~Lie with your back flat on a bench and your legs extended in front of you off the end.~Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position. As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second. Now, as you inhale, slowly lower your legs back down to the starting position.~Arching the lower back off the floor.", "Flexor Incline Dumbbell Curls~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps~Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.~Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand. Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position. Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale.~Swinging the body or moving the elbows forward.", "Floor Glute-Ham Raise~Hamstrings~rdl~0~None~3.5~r~1~Hamstrings, Calves, Glutes~You can use a partner for this exercise or brace your feet under something stable.~Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position. Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward. Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position.~Rounding the lower back instead of hinging at the hips.", "Floor Press~Triceps~bench~2~Barbell and plates~6.0~r~1~Triceps, Chest, Shoulders~Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.~Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight. Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.~Bouncing the weight or lifting the hips off the bench.", "Floor Press with Chains~Triceps~bench~2~Barbell and plates~6.0~r~1~Triceps, Chest, Shoulders~Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.~Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks. Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.~Bouncing the weight or lifting the hips off the bench.", "Foot-SMR~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Calves~This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.~Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet.~Bouncing into the stretch or pushing into pain.", "Frankenstein Squat~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Abdominals, Calves, Glutes~This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.~Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don't round the thoracic spine. Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place.~Letting the knees cave inward or the heels lift.", "Freehand Jump Squat~Quads~squat~0~None~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Cross your arms over your chest.~With your head up and your back straight, position your feet at shoulder width. Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor. Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement. When you touch the floor again, immediately squat down and jump again.~Letting the knees cave inward or the heels lift.", "Frog Hops~Mobility~stretch~0~None~2.3~h~1~Quadriceps, Calves, Glutes, Hamstrings~Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.~Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times.~Bouncing into the stretch or pushing into pain.", "Frog Sit-Ups~Abs & core~crunch~0~None~3.5~r~1~Abdominals~Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.~Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other. Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape. Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.~Pulling on the neck with the hands.", "Front Barbell Squat~Quads~squat~2~Barbell and plates~5.0~r~2~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.~Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.~Letting the knees cave inward or the heels lift.", "Front Barbell Squat To A Bench~Quads~squat~2~Barbell and plates~5.0~r~2~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.~Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.~Letting the knees cave inward or the heels lift.", "Front Box Jump~Hamstrings~rdl~2~Gym equipment (see steps)~8.0~r~0~Hamstrings, Abductors, Adductors, Calves~Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.~Perform a short squat in preparation for jumping, swinging your arms behind you. Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up. Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time.~Rounding the lower back instead of hinging at the hips.", "Front Cable Raise~Shoulders~frontraise~2~Cable machine~3.5~r~0~Shoulders~Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.~Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms' length with the palms of the hand facing your thighs. This will be your starting position. While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor.~Swinging the weight up with the body.", "Front Cone Hops (or hurdle hops)~Quads~squat~2~Gym equipment (see steps)~8.0~r~0~Quadriceps, Abductors, Adductors, Calves~Set up a row of cones or other small barriers, placing them a few feet apart.~Stand in front of the first cone with your feet shoulder width apart. This will be your starting position. Begin by jumping with both feet over the first cone, swinging both arms as you jump. Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone. Continue until you have jumped over all of the cones.~Letting the knees cave inward or the heels lift.", "Front Dumbbell Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~0~Shoulders~Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.~While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause. Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.~Swinging the weight up with the body.", "Front Incline Dumbbell Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~0~Shoulders~Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.~Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position. Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.~Swinging the weight up with the body.", "Front Leg Raises~Mobility~stretch~0~None~2.3~h~0~Hamstrings~Stand next to a chair or other support, holding on with one hand.~Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs.~Bouncing into the stretch or pushing into pain.", "Front Plate Raise~Shoulders~frontraise~2~Gym equipment (see steps)~3.5~r~1~Shoulders~While standing straight, hold a barbell plate in both hands at the 3 and 9 o'clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.~Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well. As you inhale, slowly lower the plate back down to the starting position.~Swinging the weight up with the body.", "Front Raise And Pullover~Chest~bench~2~Barbell and plates~5.0~r~0~Chest, Lats, Shoulders, Triceps~Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.~Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position. Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.~Bouncing the weight or lifting the hips off the bench.", "Front Squat (Clean Grip)~Quads~squat~2~Barbell and plates~5.0~r~1~Quadriceps, Abdominals, Glutes, Hamstrings~To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.~Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position. Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves.~Letting the knees cave inward or the heels lift.", "Front Squats With Two Kettlebells~Quads~goblet~1~A kettlebell~5.0~r~1~Quadriceps, Calves, Glutes~Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.~Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up. Rise back up by driving through your heels and repeat.~Letting the chest drop forward.", "Front Two-Dumbbell Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~0~Shoulders~Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.~While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. As you inhale, lower the dumbbells back down slowly to the starting position.~Swinging the weight up with the body.", "Full Range-Of-Motion Lat Pulldown~Back~latpull~2~Cable machine~5.0~r~1~Lats, Biceps, Middle back, Shoulders~Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.~Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat.~Leaning far back or pulling behind the neck.", "Gironda Sternum Chins~Back~pullup~2~Gym equipment (see steps)~5.0~r~1~Lats, Biceps, Middle back~Grasp the pull-up bar with a shoulder width underhand grip.~Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position. Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.~Kipping or not lowering all the way.", "Glute Ham Raise~Hamstrings~rdl~2~Gym machine~6.0~r~1~Hamstrings, Calves, Glutes~Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.~Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright. Return to the starting position, keeping your descent under control.~Rounding the lower back instead of hinging at the hips.", "Glute Kickback~Glutes~bridge~0~None~5.0~r~0~Glutes, Hamstrings~Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.~As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it. Go back to the initial position as you inhale and now repeat with the left leg. Continue to alternate legs until all of the recommended repetitions have been performed.~Arching the lower back instead of squeezing the glutes.", "Good Morning off Pins~Hamstrings~rdl~2~Barbell and plates~6.0~r~1~Hamstrings, Abdominals, Glutes, Lower back~Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.~Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position.~Rounding the lower back instead of hinging at the hips.", "Gorilla Chin/Crunch~Abs & core~crunch~0~None~5.0~r~1~Abdominals, Biceps, Lats~Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.~Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position. As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time. Slowly start to inhale as you return to the starting position.~Pulling on the neck with the hands.", "Groin and Back Stretch~Mobility~stretch~0~None~2.3~h~1~Adductors~Sit on the floor with your knees bent and feet together.~Interlock your fingers behind your head. This will be your starting position. Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions.~Bouncing into the stretch or pushing into pain.", "Groiners~Mobility~stretch~0~None~2.3~h~1~Adductors~Begin in a pushup position on the floor. This will be your starting position.~Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so. Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions.~Bouncing into the stretch or pushing into pain.", "Hack Squat~Quads~squat~2~Gym machine~5.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.~Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position). Now straighten your legs without locking the knees. This will be your starting position.~Letting the knees cave inward or the heels lift.", "Hammer Curls~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps~Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.~The palms of the hands should be facing your torso. This will be your starting position. Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.~Swinging the body or moving the elbows forward.", "Hammer Grip Incline DB Bench Press~Chest~bench~1~Dumbbells~5.0~r~0~Chest, Shoulders, Triceps~Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.~By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width. Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.~Bouncing the weight or lifting the hips off the bench.", "Hamstring-SMR~Mobility~stretch~1~A foam roller~2.3~h~0~Hamstrings~In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.~Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching. Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg.~Bouncing into the stretch or pushing into pain.", "Hamstring Stretch~Mobility~stretch~0~None~2.3~h~0~Hamstrings~Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.~Loop a belt, band, or rope over the ball of your foot. This will be your starting position. Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg.~Bouncing into the stretch or pushing into pain.", "Handstand Push-Ups~Shoulders~ohpress~0~None~5.0~r~2~Shoulders, Triceps~With your back to the wall bend at the waist and place both hands on the floor at shoulder width.~Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down. Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.~Arching the lower back to push the weight up.", "Hang Clean~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Calves, Forearms, Glutes~Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.~Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.~Letting the knees cave inward or the heels lift.", "Hang Clean - Below the Knees~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Calves, Forearms, Glutes~Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.~Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull.~Letting the knees cave inward or the heels lift.", "Hang Snatch~Full body~rdl~2~Barbell and plates~6.0~r~2~Hamstrings, Abdominals, Calves, Forearms~Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.~Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side. As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead. Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control.~Rounding the lower back instead of hinging at the hips.", "Hang Snatch - Below Knees~Full body~rdl~2~Barbell and plates~6.0~r~2~Hamstrings, Abdominals, Calves, Forearms~Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.~Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side. As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead. Return to a standing position with the weight overhead, and then return the weight to the floor under control.~Rounding the lower back instead of hinging at the hips.", "Hanging Bar Good Morning~Hamstrings~rdl~2~Barbell and plates~6.0~r~1~Hamstrings, Abdominals, Glutes, Lower back~Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.~Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment. Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.~Rounding the lower back instead of hinging at the hips.", "Hanging Pike~Abs & core~hangraise~0~None~5.0~r~2~Abdominals~Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar.~Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position. Pull your legs up as you exhale until you almost touch your shins with the bar above you. Tip: Try to straighten your legs as much as possible while at the top. Lower your legs as slowly as possible until you reach the starting position. Tip: Avoid swinging and using momentum at all times.~Swinging the body to lift the legs.", "Heaving Snatch Balance~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Abdominals, Forearms, Glutes~This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with.~Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat. Return to a standing position.~Letting the knees cave inward or the heels lift.", "Heavy Bag Thrust~Chest~bench~2~Gym equipment (see steps)~8.0~r~0~Chest, Abdominals, Shoulders, Triceps~Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.~Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body. Receive the bag as it swings back by reversing these steps.~Bouncing the weight or lifting the hips off the bench.", "High Cable Curls~Biceps~curl~2~Cable machine~5.0~r~1~Biceps~Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.~Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps. Slowly bring back the arms to the starting position.~Swinging the body or moving the elbows forward.", "Hip Circles (prone)~Mobility~stretch~0~None~2.3~h~0~Abductors, Adductors~Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.~Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee. Perform this slowly for a number of repetitions, and repeat on the other side.~Bouncing into the stretch or pushing into pain.", "Hip Extension with Bands~Glutes~bridge~1~A resistance band~5.0~r~0~Glutes, Hamstrings~Secure one end of the band to the lower portion of a post and attach the other to one ankle.~Facing the attachment point of the band, hold on to the column to stabilize yourself. Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight. Return the leg to the starting position.~Arching the lower back instead of squeezing the glutes.", "Hip Flexion with Band~Quads~squat~1~A resistance band~5.0~r~0~Quadriceps~Secure one end of the band to the lower portion of a post and attach the other to one ankle.~Face away from the attachment point of the band. Keeping your head and your chest up, raise your knee up to 90 degrees and pause. Return the leg to the starting position.~Letting the knees cave inward or the heels lift.", "Hip Lift with Band~Glutes~bridge~1~A resistance band~6.0~r~0~Glutes, Calves, Hamstrings~After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn't have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won't move.~Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position. Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can. Pause at the top of the motion, and return to the starting position.~Arching the lower back instead of squeezing the glutes.", "Hug A Ball~Mobility~stretch~1~An exercise ball~2.3~h~0~Lower back, Calves, Glutes~Seat yourself on the floor.~Straddle an exercise ball between both legs and lower your hips down toward the floor. Hug your arms around the ball to support your body. Adjust your legs so that your feet are flat on the floor and your knees line up over your ankles. Keep a good grip on the ball so it doesn't roll away from you and send you back onto your buttocks.~Bouncing into the stretch or pushing into pain.", "Hug Knees To Chest~Mobility~stretch~0~None~2.3~h~0~Lower back, Glutes~Lie down on your back and pull both knees up to your chest.~Hold your arms under the knees, not over (that would put to much pressure on your knee joints). Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles.~Bouncing into the stretch or pushing into pain.", "Hurdle Hops~Hamstrings~rdl~2~Gym equipment (see steps)~8.0~r~0~Hamstrings, Abductors, Adductors, Calves~Set up a row of hurdles or other small barriers, placing them a few feet apart.~Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position. Begin by jumping with both feet over the first hurdle, swinging both arms as you jump. Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles.~Rounding the lower back instead of hinging at the hips.", "Hyperextensions (Back Extensions)~Back~superman~2~Gym equipment (see steps)~3.5~r~0~Lower back, Glutes, Hamstrings~Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.~Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction. With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms. Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement.~Over-arching or straining the neck.", "Hyperextensions With No Hyperextension Bench~Back~superman~0~None~5.0~r~1~Lower back, Glutes, Hamstrings~With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.~With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms. Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first).~Over-arching or straining the neck.", "IT Band and Glute Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Abductors~Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position.~Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side.~Bouncing into the stretch or pushing into pain.", "Iliotibial Tract-SMR~Mobility~stretch~1~A foam roller~2.3~h~1~Abductors~Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.~Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching. Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg.~Bouncing into the stretch or pushing into pain.", "Incline Barbell Triceps Extension~Triceps~pushdown~2~Barbell and plates~3.5~r~1~Triceps, Forearms~Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.~Lie back on an incline bench set at any angle between 45-75-degrees. Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position. Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.~Letting the elbows drift away from the sides.", "Incline Bench Pull~Back~row~2~Barbell and plates~3.5~r~0~Middle back, Lats, Shoulders~Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.~Let the arms hang to your sides fully extended as they point to the floor. Turn the wrists until your hands have a pronated (palms down) grip. Now flare the elbows out. This will be your starting position. As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back.~Rounding the back or jerking the weight with the arms only.", "Incline Cable Chest Press~Chest~bench~2~Cable machine~5.0~r~0~Chest, Shoulders, Triceps~Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.~Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement. After pausing at full extension, return to the starting position, keeping tension on the cables.~Bouncing the weight or lifting the hips off the bench.", "Incline Cable Flye~Chest~bench~2~Cable machine~3.5~r~1~Chest, Shoulders~To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).~Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand. With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position. With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement.~Bouncing the weight or lifting the hips off the bench.", "Incline Dumbbell Bench With Palms Facing In~Chest~bench~1~Dumbbells~5.0~r~0~Chest, Shoulders, Triceps~Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.~By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width. Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.~Bouncing the weight or lifting the hips off the bench.", "Incline Dumbbell Flyes~Chest~bench~1~Dumbbells~5.0~r~0~Chest, Shoulders~Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.~Extend your arms above you with a slight bend at the elbows. Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position. As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.~Bouncing the weight or lifting the hips off the bench.", "Incline Dumbbell Flyes - With A Twist~Chest~bench~1~Dumbbells~5.0~r~0~Chest, Shoulders~Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.~Extend your arms above you with a slight bend at the elbows. Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position. As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.~Bouncing the weight or lifting the hips off the bench.", "Incline Hammer Curls~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps~Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.~Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary. Continue to the top of the movement and pause, then slowly return to the start position.~Swinging the body or moving the elbows forward.", "Incline Inner Biceps Curl~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps~Hold a dumbbell in each hand and lie back on an incline bench.~The dumbbells should be at arm's length hanging at your sides and your palms should be facing out. This will be your starting position. Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.~Swinging the body or moving the elbows forward.", "Incline Push-Up Close-Grip~Triceps~pushup~0~None~5.0~r~0~Triceps, Chest, Shoulders~Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.~Place your hands next to one another on the bar. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.~Letting the hips sag or flaring the elbows wide.", "Incline Push-Up Depth Jump~Chest~pushup~2~Gym equipment (see steps)~8.0~r~0~Chest, Shoulders, Triceps~For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps.~Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position. Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb the impact.~Letting the hips sag or flaring the elbows wide.", "Incline Push-Up Medium~Chest~pushup~0~None~5.0~r~0~Chest, Abdominals, Shoulders, Triceps~Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.~Place your hands on the bar, with your hands about shoulder width apart. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.~Letting the hips sag or flaring the elbows wide.", "Incline Push-Up Reverse Grip~Chest~pushup~0~None~5.0~r~0~Chest, Abdominals, Shoulders, Triceps~Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.~Place your hands on the bar palms up, with your hands about shoulder width apart. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.~Letting the hips sag or flaring the elbows wide.", "Incline Push-Up Wide~Chest~pushup~0~None~5.0~r~0~Chest, Abdominals, Shoulders, Triceps~Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.~Place your hands on the bar, with your hands wider than shoulder width. Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.~Letting the hips sag or flaring the elbows wide.", "Intermediate Groin Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Hamstrings~Lie on your back with your legs extended. Loop a belt, rope, or band around one of your feet, and swing that leg as far to the side as you can. This will be your starting position.~Pull gently on the belt to create tension in your groin and hamstring muscles. Hold for 10-20 seconds, and repeat on the other side.~Bouncing into the stretch or pushing into pain.", "Intermediate Hip Flexor and Quad Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Quadriceps~Lie face down on the floor, with a rope, belt, or band looped around one foot.~Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your knee and your hip should come off of the floor, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and repeat on the other leg.~Bouncing into the stretch or pushing into pain.", "Internal Rotation with Band~Shoulders~ohpress~1~A resistance band~3.5~r~0~Shoulders~Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.~Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position. With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position. Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.~Arching the lower back to push the weight up.", "Inverted Row with Straps~Back~row~2~Gym equipment (see steps)~5.0~r~0~Middle back, Biceps, Lats~Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.~Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement. Pause at the top of the motion, and return yourself to the start position.~Rounding the back or jerking the weight with the arms only.", "Iron Crosses (stretch)~Mobility~stretch~0~None~2.3~h~1~Quadriceps~Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position.~To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand. Promptly return the leg to the starting postion, and quickly repeat with the other leg. Continue alternating for 10-20 repetitions.~Bouncing into the stretch or pushing into pain.", "Isometric Chest Squeezes~Chest~pushup~0~None~8.0~h~0~Chest, Shoulders, Triceps~While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).~Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. Hold for the recommended number of seconds. Now release the tension slowly. Rest for the recommended amount of time and repeat.~Letting the hips sag or flaring the elbows wide.", "Isometric Neck Exercise - Front And Back~Mobility~stretch~0~None~3.5~h~0~Neck~With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.~Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. Hold for the recommended number of seconds. Now release the tension slowly. Rest for the recommended amount of time and repeat with your hands placed on the back side of your head.~Bouncing into the stretch or pushing into pain.", "Isometric Neck Exercise - Sides~Mobility~stretch~0~None~3.5~h~0~Neck~With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.~Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. Hold for the recommended number of seconds. Now release the tension slowly. Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head.~Bouncing into the stretch or pushing into pain.", "Isometric Wipers~Chest~pushup~0~None~5.0~r~0~Chest, Abdominals, Shoulders, Triceps~Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position.~Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body. Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side.~Letting the hips sag or flaring the elbows wide.", "JM Press~Triceps~bench~2~Barbell and plates~5.0~r~0~Triceps, Chest, Shoulders~Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.~Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward. As you exhale, press the bar back up by using the triceps to perform a close grip bench press.~Bouncing the weight or lifting the hips off the bench.", "Jackknife Sit-Up~Abs & core~jacks~0~None~5.0~r~0~Abdominals~Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.~As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor. While inhaling, lower your arms and legs back to the starting position.~Landing heavily on the heels.", "Janda Sit-Up~Abs & core~crunch~0~None~3.5~r~0~Abdominals~Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position.~As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax. As you inhale, slowly go back in a controlled manner to the starting position.~Pulling on the neck with the hands.", "Jefferson Squats~Quads~squat~2~Barbell and plates~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Place a barbell on the floor.~Stand in the middle of the bar length wise. Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side. Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar.~Letting the knees cave inward or the heels lift.", "Jerk Balance~Full body~ohpress~2~Barbell and plates~6.0~r~1~Shoulders, Glutes, Hamstrings, Quadriceps~This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.~Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight. Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead.~Arching the lower back to push the weight up.", "Jerk Dip Squat~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Abdominals, Calves~This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable.~Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet.~Letting the knees cave inward or the heels lift.", "Jogging, Treadmill~Cardio~run~2~Gym machine~7.0~t~0~Quadriceps, Glutes, Hamstrings~To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.~Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.~Starting too fast and losing good posture.", "Kettlebell Arnold Press~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Triceps~Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.~Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion. Return the kettlebell to the starting position, with the palm facing in.~Arching the lower back to push the weight up.", "Kettlebell Dead Clean~Hamstrings~rdl~1~A kettlebell~5.0~r~1~Hamstrings, Calves, Glutes, Lower back~Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.~Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out.~Rounding the lower back instead of hinging at the hips.", "Kettlebell Figure 8~Abs & core~crunch~1~A kettlebell~3.5~r~1~Abdominals, Hamstrings, Shoulders~Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.~Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions.~Pulling on the neck with the hands.", "Kettlebell Halo~Shoulders~ohpress~1~A kettlebell~5.0~r~0~Shoulders, Traps, Middle back, Abdominals~Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.~Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head. Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout. Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction. Move slowly and keep your head, hips and lower back still.~Arching the lower back to push the weight up.", "Kettlebell Halo with Overhead Extension~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Triceps, Traps, Middle back~Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.~Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here. From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head. Bend your elbows to lower the kettlebell back to the pause position behind your head, under control. Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.~Arching the lower back to push the weight up.", "Kettlebell Hang Clean~Hamstrings~rdl~1~A kettlebell~5.0~r~1~Hamstrings, Calves, Glutes, Lower back~Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.~Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep your head up at all times.~Rounding the lower back instead of hinging at the hips.", "Kettlebell One-Legged Deadlift~Hamstrings~deadlift~1~A kettlebell~5.0~rs~1~Hamstrings, Glutes, Lower back~Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.~Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance. Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position.~Rounding the back or jerking the weight off the floor.", "Kettlebell Overhead Triceps Extension~Triceps~pushdown~1~A kettlebell~3.5~r~0~Triceps, Shoulders, Abdominals~Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.~Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position. Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward. Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout. Keep your ribcage down and avoid arching your lower back as you extend.~Letting the elbows drift away from the sides.", "Kettlebell Pass Between The Legs~Abs & core~crunch~1~A kettlebell~5.0~r~1~Abdominals, Glutes, Hamstrings, Shoulders~Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.~Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a \"W\". Go back and forth for several repetitions.~Pulling on the neck with the hands.", "Kettlebell Pirate Ships~Shoulders~ohpress~1~A kettlebell~5.0~r~0~Shoulders, Abdominals~With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.~Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion. Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.~Arching the lower back to push the weight up.", "Kettlebell Pistol Squat~Quads~goblet~1~A kettlebell~5.0~r~2~Quadriceps, Calves, Glutes, Hamstrings~Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.~Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you. Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up. Lower yourself again and repeat.~Letting the chest drop forward.", "Kettlebell Seated Press~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Triceps~Sit on the floor and spread your legs out comfortably.~Clean one kettlebell to your shoulder. Press the kettlebell up and out until it is locked out overhead. Return to the starting position.~Arching the lower back to push the weight up.", "Kettlebell Seesaw Press~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Triceps~Clean two kettlebells two your shoulders.~Press one kettlebell. Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides.~Arching the lower back to push the weight up.", "Kettlebell Sumo High Pull~Back~row~1~A kettlebell~5.0~r~1~Traps, Adductors, Glutes, Hamstrings~Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.~Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position.~Rounding the back or jerking the weight with the arms only.", "Kettlebell Thruster~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Quadriceps, Triceps~Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.~Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can. At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward. As you begin the next repetition, return the weights to the shoulders.~Arching the lower back to push the weight up.", "Kettlebell Turkish Get-Up (Lunge style)~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Abdominals, Hamstrings, Quadriceps~Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.~Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.~Arching the lower back to push the weight up.", "Kettlebell Turkish Get-Up (Squat style)~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Abdominals, Calves, Hamstrings~Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.~Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.~Arching the lower back to push the weight up.", "Kettlebell Windmill~Abs & core~crunch~1~A kettlebell~5.0~r~1~Abdominals, Glutes, Hamstrings, Shoulders~Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.~Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times. Pause for a second after reaching the ground and reverse the motion back to the starting position.~Pulling on the neck with the hands.", "Kipping Muscle Up~Back~row~2~Gym equipment (see steps)~5.0~r~1~Lats, Abdominals, Biceps, Forearms~Grip the rings using a false grip, with the base of your palms on top of the rings.~Begin with a movement swinging your legs backward slightly. Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.~Rounding the back or jerking the weight with the arms only.", "Knee Across The Body~Mobility~stretch~0~None~2.3~h~0~Glutes, Abductors, Lower back~Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn't need to touch the floor if you're tight.)~Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides.~Bouncing into the stretch or pushing into pain.", "Knee Circles~Mobility~stretch~0~None~2.3~h~0~Calves, Hamstrings, Quadriceps~Stand with your legs together and hands by your waist.~Now move your knees in a circular motion as you breathe normally.~Bouncing into the stretch or pushing into pain.", "Knee/Hip Raise On Parallel Bars~Abs & core~crunch~2~Gym equipment (see steps)~3.5~r~0~Abdominals~Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.~The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position. Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise. Slowly go back to the starting position as you breathe in.~Pulling on the neck with the hands.", "Knee Tuck Jump~Hamstrings~rdl~0~None~8.0~r~0~Hamstrings, Abductors, Adductors, Calves~Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.~Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands. Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend.~Rounding the lower back instead of hinging at the hips.", "Kneeling Arm Drill~Shoulders~ohpress~0~None~8.0~r~0~Shoulders, Abdominals~This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.~Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint. As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible. Switch knees and repeat.~Arching the lower back to push the weight up.", "Kneeling Cable Crunch With Alternating Oblique Twists~Abs & core~crunch~2~Cable machine~3.5~rs~0~Abdominals~Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.~Grab the rope with both hands and kneel approximately two feet back from the tower. Position the rope behind your head with your hands by your ears. Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees. Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.~Pulling on the neck with the hands.", "Kneeling Cable Triceps Extension~Triceps~pushdown~2~Cable machine~3.5~r~1~Triceps~Place a bench sideways in front of a high pulley machine.~Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down. Face away from the machine and kneel. Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.~Letting the elbows drift away from the sides.", "Kneeling Forearm Stretch~Mobility~stretch~0~None~2.3~h~0~Forearms~Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.~Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds.~Bouncing into the stretch or pushing into pain.", "Kneeling High Pulley Row~Back~row~2~Cable machine~5.0~r~0~Lats, Biceps, Middle back~Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.~Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out. After pausing briefly, slowly return to the starting position.~Rounding the back or jerking the weight with the arms only.", "Kneeling Hip Flexor~Mobility~stretch~0~None~2.3~h~0~Quadriceps, Quadriceps~Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.~Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side.~Bouncing into the stretch or pushing into pain.", "Kneeling Jump Squat~Full body~squat~2~Barbell and plates~6.0~r~2~Glutes, Calves, Hamstrings, Quadriceps~Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.~Sit back with your hips until your glutes touch your feet, keeping your head and chest up. Explode up with your hips, generating enough power to land with your feet flat on the floor. Continue with the squat by driving through your heels and extending the knees to come to a standing position.~Letting the knees cave inward or the heels lift.", "Kneeling Single-Arm High Pulley Row~Back~row~2~Cable machine~5.0~rs~0~Lats, Biceps, Middle back~Attach a single handle to a high pulley and make your weight selection.~Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position. Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you. After a brief pause, return to the starting position.~Rounding the back or jerking the weight with the arms only.", "Kneeling Squat~Glutes~squat~2~Barbell and plates~6.0~r~1~Glutes, Abdominals, Hamstrings, Lower back~Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.~With your head looking forward, sit back with your butt until you touch your calves. Reverse the motion, returning the torso to an upright position.~Letting the knees cave inward or the heels lift.", "Landmine 180's~Abs & core~crunch~2~Barbell and plates~5.0~r~0~Abdominals, Glutes, Lower back, Shoulders~Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.~Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position. Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise. Reverse the motion to swing the weight all the way to the opposite side. Continue alternating the movement until the set is complete.~Pulling on the neck with the hands.", "Landmine Linear Jammer~Shoulders~ohpress~2~Barbell and plates~5.0~r~1~Shoulders, Abdominals, Calves, Chest~Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.~Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position. In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed. Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible. Return to the starting position.~Arching the lower back to push the weight up.", "Lateral Bound~Glutes~bridge~0~None~8.0~r~0~Adductors, Abductors, Calves, Glutes~Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.~Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg. Immediately push off and extend, attempting to bound to the side as far as possible. Upon landing, immediately push off in the opposite direction, returning to your original start position. Continue back and forth for several repetitions.~Arching the lower back instead of squeezing the glutes.", "Lateral Box Jump~Glutes~bridge~2~Gym equipment (see steps)~8.0~r~0~Adductors, Abductors, Calves, Glutes~Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.~Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side. Bring your knees high enough to ensure your feet have good clearance over the box. Land on the center of the box, using your legs to absorb the impact. Carefully jump down to the other side of the box, and continue going back and forth for several repetitions.~Arching the lower back instead of squeezing the glutes.", "Lateral Cone Hops~Glutes~bridge~2~Gym equipment (see steps)~8.0~r~0~Adductors, Abductors, Calves, Glutes~Position a number of cones in a row several feet apart.~Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position. Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone. Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.~Arching the lower back instead of squeezing the glutes.", "Lateral Raise - With Bands~Shoulders~frontraise~1~A resistance band~3.5~r~0~Shoulders~To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.~Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement. Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.~Swinging the weight up with the body.", "Latissimus Dorsi-SMR~Mobility~stretch~1~A foam roller~2.3~h~0~Lats~While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position.~Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides.~Bouncing into the stretch or pushing into pain.", "Leg-Over Floor Press~Chest~bench~1~A kettlebell~5.0~r~1~Chest, Shoulders, Triceps~Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side. Your free arm can be extended out to your side for support.~Press the kettlebll into a locked out position. Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.~Bouncing the weight or lifting the hips off the bench.", "Leg-Up Hamstring Stretch~Mobility~stretch~0~None~2.3~h~0~Hamstrings~Lie flat on your back, bend one knee, and put that foot flat on the floor to stabilize your spine.~Extend the other leg in the air. If you're tight, you wont be able to straighten it. That's okay. Extend the knee so that the sole of the lifted foot faces the ceiling (or as close as you can get it). Slowly straighten the legs as much as possible and then pull the leg toward your nose. Switch sides.~Bouncing into the stretch or pushing into pain.", "Leg Extensions~Quads~squat~2~Gym machine~3.5~r~0~Quadriceps~For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.~Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position. Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.~Letting the knees cave inward or the heels lift.", "Leg Lift~Glutes~bridge~0~None~3.5~r~0~Glutes, Hamstrings~While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.~With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement. Slowly bring the raised leg back to the floor as you breathe in.~Arching the lower back instead of squeezing the glutes.", "Leg Pull-In~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.~Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor. Return to the starting position as you inhale.~Pulling on the neck with the hands.", "Leverage Chest Press~Chest~bench~2~Gym machine~5.0~r~0~Chest, Shoulders, Triceps~Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.~Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.~Bouncing the weight or lifting the hips off the bench.", "Leverage Deadlift~Quads~squat~2~Gym machine~5.0~r~0~Quadriceps, Glutes, Hamstrings~Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position.~Return the weight to the starting position.~Letting the knees cave inward or the heels lift.", "Leverage Decline Chest Press~Chest~bench~2~Gym machine~5.0~r~0~Chest, Shoulders, Triceps~Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.~Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.~Bouncing the weight or lifting the hips off the bench.", "Leverage High Row~Back~row~2~Gym machine~5.0~r~0~Middle back, Lats~Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.~Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.~Rounding the back or jerking the weight with the arms only.", "Leverage Incline Chest Press~Chest~bench~2~Gym machine~5.0~r~0~Chest, Shoulders, Triceps~Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.~Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.~Bouncing the weight or lifting the hips off the bench.", "Leverage Iso Row~Back~row~2~Gym machine~5.0~r~0~Lats, Biceps, Middle back~Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.~Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.~Rounding the back or jerking the weight with the arms only.", "Leverage Shoulder Press~Shoulders~ohpress~2~Gym machine~5.0~r~0~Shoulders, Triceps~Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.~Press the handles upward by extending through the elbow. After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.~Arching the lower back to push the weight up.", "Leverage Shrug~Back~row~2~Gym machine~3.5~r~0~Traps, Forearms~Load the pins to an appropriate weight. Position yourself directly between the handles.~Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position. Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.~Rounding the back or jerking the weight with the arms only.", "Linear 3-Part Start Technique~Hamstrings~rdl~0~None~8.0~r~0~Hamstrings, Calves, Quadriceps~This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.~Place your right hand onto the line, and thing bring your nose close to your left knee. Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position. Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.~Rounding the lower back instead of hinging at the hips.", "Linear Acceleration Wall Drill~Hamstrings~rdl~0~None~8.0~r~0~Hamstrings, Calves, Glutes, Quadriceps~Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.~Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground. Switch legs, raising the opposite knee, and then attacking the ground straight down.~Rounding the lower back instead of hinging at the hips.", "Linear Depth Jump~Quads~jacks~2~Gym equipment (see steps)~8.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.~To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex. Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform. Land softly, asborbing the impact through the legs.~Landing heavily on the heels.", "London Bridges~Back~row~2~Gym equipment (see steps)~5.0~r~1~Lats, Biceps, Forearms, Middle back~Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized.~Stand on the bar, using the rope to balance yourself. This will be your starting position. Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground. Keeping your body straight, reverse the motion, going hand over hand back to the starting position.~Rounding the back or jerking the weight with the arms only.", "Looking At Ceiling~Mobility~stretch~0~None~2.3~h~0~Quadriceps~Kneel on the floor, holding your heels with both hands.~Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back.~Bouncing into the stretch or pushing into pain.", "Low Cable Crossover~Chest~bench~2~Cable machine~3.5~r~0~Chest, Shoulders~To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.~Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position. With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up. Return your arms back to the starting position after a brief pause.~Bouncing the weight or lifting the hips off the bench.", "Low Cable Triceps Extension~Triceps~pushdown~2~Cable machine~3.5~r~0~Triceps~Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.~Grab the outside of the rope ends with your palms facing each other (neutral grip). Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position. As you breathe out, extend your lower arms until they are straight and vertical.~Letting the elbows drift away from the sides.", "Low Pulley Row To Neck~Shoulders~ohpress~2~Cable machine~5.0~r~0~Shoulders, Biceps, Middle back, Traps~Sit on a low pulley row machine with a rope attachment.~Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position. While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor.~Arching the lower back to push the weight up.", "Lower Back-SMR~Mobility~stretch~1~A foam roller~2.3~h~0~Lower back~In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position.~Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side.~Bouncing into the stretch or pushing into pain.", "Lower Back Curl~Mobility~stretch~0~None~2.3~h~0~Abdominals~Lie on your stomach with your arms out to your sides. This will be your starting position.~Using your lower back muscles, extend your spine lifting your chest off of the ground. Do not use your arms to push yourself up. Keep your head up during the movement. Repeat for 10-20 repetitions.~Bouncing into the stretch or pushing into pain.", "Lunge Pass Through~Hamstrings~rdl~1~A kettlebell~5.0~r~1~Hamstrings, Calves, Glutes, Quadriceps~Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.~Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground. As you lunge, pass the kettlebell under your front leg to your opposite hand. Pressing through the heel of your foot, return to the starting position.~Rounding the lower back instead of hinging at the hips.", "Lunge Sprint~Quads~lunge~2~Gym machine~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position.~Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so. At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from your back foot. Jump up and reverse the position of your legs.~Letting the front knee drift inward or leaning the torso forward.", "Lying Bent Leg Groin~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~2~Adductors~Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position.~Attempt to squeeze your knees together, while your partner prevents any movement from occurring. After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.~Bouncing into the stretch or pushing into pain.", "Lying Cable Curl~Biceps~curl~2~Cable machine~3.5~r~1~Biceps~Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.~Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight. With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position. While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.~Swinging the body or moving the elbows forward.", "Lying Cambered Barbell Row~Back~row~2~Barbell and plates~3.5~r~0~Middle back, Biceps, Lats, Traps~Place a cambered bar underneath an exercise bench.~Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position. As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal. After a second hold at the top, lower back down to the starting position slowly as you inhale.~Rounding the back or jerking the weight with the arms only.", "Lying Close-Grip Bar Curl On High Pulley~Biceps~curl~2~Cable machine~3.5~r~0~Biceps~Place a flat bench in front of a high pulley or lat pulldown machine.~Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width. Lie on your back with your head over the end of the bench. Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position. As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position.~Swinging the body or moving the elbows forward.", "Lying Close-Grip Barbell Triceps Extension Behind The Head~Triceps~pushdown~2~Barbell and plates~3.5~r~1~Triceps~While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.~Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times. As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.~Letting the elbows drift away from the sides.", "Lying Close-Grip Barbell Triceps Press To Chin~Triceps~pushdown~2~EZ curl bar~3.5~r~1~Triceps~While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.~Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position. As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin. As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion.~Letting the elbows drift away from the sides.", "Lying Crossover~Mobility~stretch~0~None~2.3~h~2~Abductors~Lie on your back with your legs extended.~Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position. Attempt to raise the bent knee off of the ground as your partner prevents any actual movement. After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side.~Bouncing into the stretch or pushing into pain.", "Lying Dumbbell Tricep Extension~Triceps~pushdown~1~Dumbbells~3.5~r~1~Triceps, Chest, Shoulders~Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.~As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears. At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.~Letting the elbows drift away from the sides.", "Lying Face Down Plate Neck Resistance~Mobility~stretch~2~Gym equipment (see steps)~3.5~r~1~Neck~Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.~While keeping the plate secure on the back of your head slowly lower your head (as in saying \"yes\") as you breathe in. Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.~Bouncing into the stretch or pushing into pain.", "Lying Face Up Plate Neck Resistance~Mobility~stretch~2~Gym equipment (see steps)~3.5~r~1~Neck~Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position.~While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in. Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.~Bouncing into the stretch or pushing into pain.", "Lying Glute~Mobility~stretch~0~None~2.3~h~2~Glutes, Abductors~Lie on your back with your partner kneeling beside you.~Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position. Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg. After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest.~Bouncing into the stretch or pushing into pain.", "Lying Hamstring~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~2~Hamstrings, Calves~Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position.~With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds. Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete.~Bouncing into the stretch or pushing into pain.", "Lying High Bench Barbell Curl~Biceps~curl~2~Barbell and plates~3.5~r~1~Biceps~Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.~While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second. As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.~Swinging the body or moving the elbows forward.", "Lying Leg Curls~Hamstrings~bridge~2~Gym machine~3.5~r~0~Hamstrings~Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.~Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position. As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second. As you inhale, bring the legs back to the initial position.~Arching the lower back instead of squeezing the glutes.", "Lying Machine Squat~Quads~squat~2~Gym machine~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.~Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.~Letting the knees cave inward or the heels lift.", "Lying One-Arm Lateral Raise~Shoulders~frontraise~1~Dumbbells~3.5~rs~1~Shoulders~While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability.~Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position. Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.~Swinging the weight up with the body.", "Lying Prone Quadriceps~Mobility~stretch~0~None~2.3~h~2~Quadriceps~Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position.~Attempt to extend your knee while your partner prevents any actual movement. After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors. After 10-20 seconds, switch sides.~Bouncing into the stretch or pushing into pain.", "Lying Rear Delt Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~1~Shoulders~While holding a dumbbell in each hand, lay with your chest down on a flat bench.~Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position. Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.~Swinging the weight up with the body.", "Lying Supine Dumbbell Curl~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps~Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.~Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip). While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your starting position.~Swinging the body or moving the elbows forward.", "Lying T-Bar Row~Back~row~2~Gym machine~5.0~r~1~Middle back, Biceps, Lats~Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.~Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize. Lift the bar off the rack and extend your arms in front of you. This will be your starting position. As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles.~Rounding the back or jerking the weight with the arms only.", "Lying Triceps Press~Triceps~pushdown~2~EZ curl bar~3.5~r~1~Triceps~Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.~Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position. As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary. At that point, use the triceps to bring the weight back up to the starting position as you breathe out.~Letting the elbows drift away from the sides.", "Machine Bench Press~Chest~bench~2~Gym machine~5.0~r~0~Chest, Shoulders, Triceps~Sit down on the Chest Press Machine and select the weight.~Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms. Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.~Bouncing the weight or lifting the hips off the bench.", "Machine Bicep Curl~Biceps~curl~2~Gym machine~3.5~r~0~Biceps~Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.~Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm. Pause at the top of the movement, and then slowly return the weight to the starting position. Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.~Swinging the body or moving the elbows forward.", "Machine Preacher Curls~Biceps~curl~2~Gym machine~3.5~r~0~Biceps~Sit down on the Preacher Curl Machine and select the weight.~Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position. Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.~Swinging the body or moving the elbows forward.", "Machine Shoulder (Military) Press~Shoulders~ohpress~2~Gym machine~5.0~r~0~Shoulders, Triceps~Sit down on the Shoulder Press Machine and select the weight.~Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position. Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second. Lower the handles slowly back to the starting position as you inhale.~Arching the lower back to push the weight up.", "Machine Triceps Extension~Triceps~pushdown~2~Gym machine~3.5~r~0~Triceps~Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.~Perform the movement by extending the elbow, pulling your lower arm away from your upper arm. Pause at the completion of the movement, and then slowly return the weight to the starting position. Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.~Letting the elbows drift away from the sides.", "Medicine Ball Chest Pass~Chest~bench~1~A medicine ball~8.0~r~0~Chest, Shoulders, Triceps~You will need a partner for this exercise. Lacking one, this movement can be performed against a wall.~Begin facing your partner holding the medicine ball at your torso with both hands. Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw. Your partner should catch the ball, and throw it back to you. Receive the throw with both hands at chest height.~Bouncing the weight or lifting the hips off the bench.", "Medicine Ball Full Twist~Abs & core~crunch~1~A medicine ball~8.0~r~0~Abdominals, Shoulders~For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.~Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner. For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise. Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure.~Pulling on the neck with the hands.", "Medicine Ball Scoop Throw~Shoulders~ohpress~1~A medicine ball~8.0~r~0~Shoulders, Abdominals, Hamstrings, Quadriceps~Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.~Begin by thrusting the hips forward as you extend through the legs, jumping up. As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you.~Arching the lower back to push the weight up.", "Middle Back Shrug~Back~row~1~Dumbbells~3.5~r~1~Middle back~Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.~As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms. As you inhale go back to the starting position.~Rounding the back or jerking the weight with the arms only.", "Middle Back Stretch~Mobility~stretch~0~None~2.3~h~0~Middle back, Abdominals, Lats, Lower back~Stand so your feet are shoulder width apart and your hands are on your hips.~Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side.~Bouncing into the stretch or pushing into pain.", "Mixed Grip Chin~Back~row~2~Gym equipment (see steps)~5.0~r~2~Middle back, Biceps, Lats~Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.~Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up. After a second contraction at the top, start to slowly come down as you inhale.~Rounding the back or jerking the weight with the arms only.", "Monster Walk~Glutes~bridge~1~A resistance band~5.0~r~0~Abductors~Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.~To begin, take short steps forward alternating your left and right foot. After several steps, do just the opposite and walk backward to where you started.~Arching the lower back instead of squeezing the glutes.", "Mountain Climbers~Quads~squat~0~None~8.0~r~0~Quadriceps, Chest, Hamstrings, Shoulders~Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.~Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.~Letting the knees cave inward or the heels lift.", "Moving Claw Series~Hamstrings~rdl~0~None~8.0~r~0~Hamstrings, Calves, Quadriceps~This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.~Reload the quad as the leg moves back forward, attacking the ground on the next step. Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.~Rounding the lower back instead of hinging at the hips.", "Muscle Snatch~Full body~rdl~2~Barbell and plates~6.0~r~1~Hamstrings, Glutes, Lower back, Quadriceps~Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.~Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. Continue raising the bar to the overhead position, without rebending the knees.~Rounding the lower back instead of hinging at the hips.", "Muscle Up~Back~row~2~Gym equipment (see steps)~5.0~r~1~Lats, Abdominals, Biceps, Forearms~Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.~As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement. Maintaining control and stability, extend through the elbow to complete the motion. Use care when lowering yourself to the ground.~Rounding the back or jerking the weight with the arms only.", "Narrow Stance Hack Squats~Quads~squat~2~Gym machine~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.~Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position). Now straighten your legs without locking the knees.~Letting the knees cave inward or the heels lift.", "Narrow Stance Leg Press~Quads~squat~2~Gym machine~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.~Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position. As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle. Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.~Letting the knees cave inward or the heels lift.", "Narrow Stance Squats~Quads~squat~2~Barbell and plates~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up at all times (looking down will get you off balance) and maintain a straight back. This will be your starting position.~Letting the knees cave inward or the heels lift.", "Natural Glute Ham Raise~Hamstrings~rdl~0~None~5.0~r~1~Hamstrings, Calves, Glutes, Lower back~Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.~This will be your starting position. Lower yourself under control until your knees are almost completely straight. Remaining in control, raise yourself back up to the starting position. If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.~Rounding the lower back instead of hinging at the hips.", "Neck-SMR~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Neck~Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position.~Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds.~Bouncing into the stretch or pushing into pain.", "Neck Press~Chest~bench~2~Barbell and plates~5.0~r~1~Chest, Shoulders, Triceps~Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.~As you breathe in, come down slowly until you feel the bar on your neck. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up). When you are done, place the bar back in the rack.~Bouncing the weight or lifting the hips off the bench.", "Oblique Crunches~Abs & core~crunch~0~None~3.5~r~0~Abdominals~Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.~Make sure your feet are elevated and resting on a flat surface. Now lift the shoulder in which your hand is touching your head. Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.~Pulling on the neck with the hands.", "Oblique Crunches - On The Floor~Abs & core~crunch~0~None~3.5~r~0~Abdominals~Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.~Place your left hand behind your head. Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques. Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position. Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise.~Pulling on the neck with the hands.", "Olympic Squat~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.~Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel. At the moment the upper legs contact the lower, reverse the motion, driving the weight upward.~Letting the knees cave inward or the heels lift.", "On-Your-Back Quad Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~0~Quadriceps~Lie on a flat bench or step, and hang one leg and arm over the side.~Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back. Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you're holding up toward the ceiling. Switch sides.~Bouncing into the stretch or pushing into pain.", "On Your Side Quad Stretch~Mobility~stretch~0~None~2.3~h~0~Quadriceps~Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).~Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.~Bouncing into the stretch or pushing into pain.", "One-Arm Dumbbell Row~Back~row~1~Dumbbells~5.0~rs~0~Middle back, Biceps, Lats, Shoulders~Choose a flat bench and place a dumbbell on each side of it.~Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support. Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.~Rounding the back or jerking the weight with the arms only.", "One-Arm Flat Bench Dumbbell Flye~Chest~bench~1~Dumbbells~3.5~rs~0~Chest~Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.~By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position. Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon.~Bouncing the weight or lifting the hips off the bench.", "One-Arm High-Pulley Cable Side Bends~Abs & core~crunch~2~Cable machine~3.5~rs~0~Abdominals~Connect a standard handle to a tower. Move cable to highest pulley position.~Stand with side to cable. With one hand, reach up and grab handle with underhand grip. Pull down cable until elbow touches your side and the handle is by your shoulder. Position feet hip-width apart. Place free hand on hip to help gauge pivot point. Keep arm in static position. Contract oblique to bring the weight down in a side crunch. Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position.~Pulling on the neck with the hands.", "One-Arm Incline Lateral Raise~Shoulders~frontraise~1~Dumbbells~3.5~rs~0~Shoulders~Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.~Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position. While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second. While inhaling lower the weight across your body back into the starting position.~Swinging the weight up with the body.", "One-Arm Kettlebell Clean~Hamstrings~rdl~1~A kettlebell~5.0~rs~1~Hamstrings, Glutes, Lower back, Shoulders~Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.~Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. Return the weight to the starting position.~Rounding the lower back instead of hinging at the hips.", "One-Arm Kettlebell Clean and Jerk~Shoulders~ohpress~1~A kettlebell~5.0~rs~1~Shoulders~Hold a kettlebell by the handle.~Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight.~Arching the lower back to push the weight up.", "One-Arm Kettlebell Floor Press~Chest~bench~1~A kettlebell~5.0~rs~1~Chest, Triceps~Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.~Press the kettlebell straight up toward the ceiling, rotating your wrist. Lower the kettlebell back to the starting position and repeat.~Bouncing the weight or lifting the hips off the bench.", "One-Arm Kettlebell Jerk~Shoulders~ohpress~1~A kettlebell~5.0~rs~1~Shoulders, Calves, Quadriceps, Triceps~Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.~Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position. Lower the weight to perform the next repetition.~Arching the lower back to push the weight up.", "One-Arm Kettlebell Military Press To The Side~Shoulders~ohpress~1~A kettlebell~5.0~rs~1~Shoulders, Triceps~Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.~Look at the kettlebell and press it up and out until it is locked out overhead. Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.~Arching the lower back to push the weight up.", "One-Arm Kettlebell Para Press~Shoulders~ohpress~1~A kettlebell~5.0~rs~1~Shoulders, Triceps~Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.~Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead. Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.~Arching the lower back to push the weight up.", "One-Arm Kettlebell Push Press~Shoulders~ohpress~1~A kettlebell~5.0~rs~1~Shoulders, Calves, Quadriceps, Triceps~Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.~Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight. Lower the weight to perform the next repetition.~Arching the lower back to push the weight up.", "One-Arm Kettlebell Row~Back~row~1~A kettlebell~5.0~rs~1~Middle back, Biceps, Lats~Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.~Move slowly and with control through the full range.~Rounding the back or jerking the weight with the arms only.", "One-Arm Kettlebell Snatch~Shoulders~ohpress~1~A kettlebell~5.0~rs~2~Shoulders, Calves, Glutes, Hamstrings~Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.~Look straight ahead and swing the kettlebell back between your legs. Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead.~Arching the lower back to push the weight up.", "One-Arm Kettlebell Split Jerk~Shoulders~ohpress~1~A kettlebell~5.0~rs~1~Shoulders, Glutes, Hamstrings, Quadriceps~Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.~Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you. Keeping the weight overhead, return to a standing position and bring your feet together.~Arching the lower back to push the weight up.", "One-Arm Kettlebell Split Snatch~Shoulders~ohpress~1~A kettlebell~5.0~rs~2~Shoulders, Hamstrings, Quadriceps~Hold a kettlebell in one hand by the handle.~Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead. After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion. Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position.~Arching the lower back to push the weight up.", "One-Arm Long Bar Row~Back~row~2~Barbell and plates~5.0~rs~0~Middle back, Biceps, Lats~Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.~Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position. Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position. Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement. After a brief pause, return to the starting position.~Rounding the back or jerking the weight with the arms only.", "One-Arm Medicine Ball Slam~Abs & core~crunch~1~A medicine ball~5.0~rs~0~Abdominals, Lats, Shoulders~Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.~Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam. At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you. Catch the ball on the bounce and continue for the desired number of repetitions.~Pulling on the neck with the hands.", "One-Arm Open Palm Kettlebell Clean~Hamstrings~rdl~1~A kettlebell~5.0~rs~1~Hamstrings, Forearms, Glutes, Lower back~Place one kettlebell between your feet.~Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand. Throw the kettlebell out in front of you and catch the handle with one hand. Take the kettlebell to the floor and repeat. Make sure to work both arms.~Rounding the lower back instead of hinging at the hips.", "One-Arm Overhead Kettlebell Squats~Quads~goblet~1~A kettlebell~5.0~rs~2~Quadriceps, Calves, Glutes, Hamstrings~Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow. This will be your starting position.~Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up. Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet.~Letting the chest drop forward.", "One-Arm Side Deadlift~Quads~squat~2~Barbell and plates~5.0~rs~2~Quadriceps, Abdominals, Calves, Glutes~Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell.~Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position. Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position. Slowly bring the barbell back down while inhaling. Tip: Make sure to bend your knees while lowering the weight to avoid any injury from occurring.~Letting the knees cave inward or the heels lift.", "One-Arm Side Laterals~Shoulders~ohpress~1~Dumbbells~3.5~rs~0~Shoulders~Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.~Stand with a straight torso and have the dumbbell by your side at arm's length with the palm of the hand facing you. This will be your starting position. While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.~Arching the lower back to push the weight up.", "One-Legged Cable Kickback~Glutes~bridge~2~Cable machine~3.5~rs~1~Glutes, Hamstrings~Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.~Face the weight stack from a distance of about two feet, grasping the steel frame for support. While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction. Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.~Arching the lower back instead of squeezing the glutes.", "One Arm Against Wall~Mobility~stretch~0~None~2.3~h~0~Lats~From a standing position, place a bent arm against a wall or doorway.~Slowly lean toward your arm until you feel a stretch in your lats.~Bouncing into the stretch or pushing into pain.", "One Arm Chin-Up~Back~row~2~Gym equipment (see steps)~5.0~rs~2~Middle back, Biceps, Forearms, Lats~For this exercise, start out by placing a towel around a chin up bar.~Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel. Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement.~Rounding the back or jerking the weight with the arms only.", "One Arm Dumbbell Bench Press~Chest~bench~1~Dumbbells~5.0~rs~0~Chest, Shoulders, Triceps~Lie down on a flat bench with a dumbbell in one hand on top of your thigh.~By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly. Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position. Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times.~Bouncing the weight or lifting the hips off the bench.", "One Arm Dumbbell Preacher Curl~Biceps~curl~1~Dumbbells~3.5~rs~0~Biceps~Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.~As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb. Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions. Switch arms and repeat the movement.~Swinging the body or moving the elbows forward.", "One Arm Floor Press~Triceps~bench~2~Barbell and plates~5.0~rs~1~Triceps, Chest, Shoulders~Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.~Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso). Make sure the hand you are not using to lift the weight is placed by your side. Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).~Bouncing the weight or lifting the hips off the bench.", "One Arm Lat Pulldown~Back~latpull~2~Cable machine~5.0~rs~0~Lats, Biceps, Middle back~Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.~Pull the handle down, squeezing your elbow to your side as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handle to the starting position. For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.~Leaning far back or pulling behind the neck.", "One Arm Pronated Dumbbell Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~rs~0~Triceps~Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise.~Place your non lifting hand on your bicep for support. Slowly begin to lower the dumbbell down as you breathe in. Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise). Switch arms and repeat the movement.~Letting the elbows drift away from the sides.", "One Arm Supinated Dumbbell Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~rs~0~Triceps~Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise.~Place your non lifting hand on your bicep for support. Slowly begin to lower the dumbbell down as you breathe in. Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise). Switch arms and repeat the movement. Switch arms again and repeat the movement.~Letting the elbows drift away from the sides.", "One Half Locust~Mobility~stretch~0~None~2.3~h~0~Quadriceps, Abdominals, Biceps, Chest~Lie facedown on the floor.~Put your left hand under your left hipbone to pad your hip and pubic bone. Bend your right knee so you can hold the foot in your right hand. Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn't bother your back, you can try it with both arms and legs at the same time.~Bouncing into the stretch or pushing into pain.", "One Handed Hang~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~0~Lats, Biceps~Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides.~Move slowly and with control through the full range.~Bouncing into the stretch or pushing into pain.", "One Knee To Chest~Mobility~stretch~0~None~2.3~h~0~Glutes, Hamstrings, Lower back~Start off by lying on the floor.~Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap. Gently tug that knee toward your nose. Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.~Bouncing into the stretch or pushing into pain.", "One Leg Barbell Squat~Quads~squat~2~Barbell and plates~5.0~rs~2~Quadriceps, Calves, Glutes, Hamstrings~Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other.~Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest. Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat bench. Your other foot should be stationary in front of you. Keep your head up at all times as looking down will get you off balance and also maintain a straight back.~Letting the knees cave inward or the heels lift.", "Open Palm Kettlebell Clean~Hamstrings~rdl~1~A kettlebell~5.0~r~2~Hamstrings, Glutes, Lower back, Quadriceps~Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.~Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands. Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat.~Rounding the lower back instead of hinging at the hips.", "Otis-Up~Abs & core~crunch~2~Gym equipment (see steps)~5.0~r~0~Abdominals, Chest, Shoulders, Triceps~Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.~Initiate the movement by flexing the hips and spine to raise your torso up from the ground. As you move up, press the weight up so that it is above your head at the top of the movement. Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor.~Pulling on the neck with the hands.", "Overhead Cable Curl~Biceps~curl~2~Cable machine~3.5~r~1~Biceps~To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.~Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders. Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.~Swinging the body or moving the elbows forward.", "Overhead Lat~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~2~Lats, Triceps~Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.~Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so. After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides.~Bouncing into the stretch or pushing into pain.", "Overhead Slam~Back~row~1~A medicine ball~8.0~r~0~Lats~Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.~Initiate the countermovement by raising the ball above your head and fully extending your body. Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can. Receive the ball with both hands on the bounce and repeat the movement.~Rounding the back or jerking the weight with the arms only.", "Overhead Squat~Full body~squat~2~Barbell and plates~6.0~r~2~Quadriceps, Abdominals, Calves, Glutes~Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.~Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest. Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.~Letting the knees cave inward or the heels lift.", "Overhead Stretch~Mobility~stretch~0~None~2.3~h~0~Abdominals, Chest, Forearms, Lats~Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up.~To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso.~Bouncing into the stretch or pushing into pain.", "Overhead Triceps~Mobility~stretch~0~None~2.3~h~2~Triceps, Lats~Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position.~Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so. After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then switch sides.~Bouncing into the stretch or pushing into pain.", "Pallof Press With Rotation~Abs & core~crunch~2~Cable machine~5.0~r~0~Abdominals, Chest, Shoulders, Triceps~Connect a standard handle to a tower, and position the cable to shoulder height.~With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable. With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time. Facing forward, press the cable away from your chest. You core should be tight and engaged.~Pulling on the neck with the hands.", "Palms-Down Dumbbell Wrist Curl Over A Bench~Forearms~curl~1~Dumbbells~3.5~r~0~Forearms~Start out by placing two dumbbells on one side of a flat bench.~Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.~Swinging the body or moving the elbows forward.", "Palms-Down Wrist Curl Over A Bench~Forearms~curl~2~Barbell and plates~3.5~r~0~Forearms~Start out by placing a barbell on one side of a flat bench.~Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.~Swinging the body or moving the elbows forward.", "Palms-Up Barbell Wrist Curl Over A Bench~Forearms~curl~2~Barbell and plates~3.5~r~0~Forearms~Start out by placing a barbell on one side of a flat bench.~Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.~Swinging the body or moving the elbows forward.", "Palms-Up Dumbbell Wrist Curl Over A Bench~Forearms~curl~1~Dumbbells~3.5~r~0~Forearms~Start out by placing two dumbbells on one side of a flat bench.~Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.~Swinging the body or moving the elbows forward.", "Parallel Bar Dip~Triceps~dips~2~Gym equipment (see steps)~5.0~r~0~Triceps, Chest, Shoulders~Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.~Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. Reverse the motion by extending the elbow, pushing yourself back up into the starting position.~Dropping too deep and letting the shoulders roll forward.", "Pelvic Tilt Into Bridge~Mobility~stretch~0~None~2.3~h~1~Lower back~Lie down with your feet on the floor, heels directly under your knees.~Lift only your tailbone to the ceiling to stretch your lower back. (Don't lift the entire spine yet.) Pull in your stomach. To go into a bridge, lift the entire spine except the neck.~Bouncing into the stretch or pushing into pain.", "Peroneals-SMR~Mobility~stretch~1~A foam roller~2.3~h~1~Calves~Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.~Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg.~Bouncing into the stretch or pushing into pain.", "Peroneals Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Calves~In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.~With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.~Bouncing into the stretch or pushing into pain.", "Physioball Hip Bridge~Glutes~bridge~1~An exercise ball~5.0~r~0~Glutes, Hamstrings~Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.~Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge. Pause at the top of the motion and return to the starting position.~Arching the lower back instead of squeezing the glutes.", "Pin Presses~Triceps~bench~2~Barbell and plates~6.0~r~1~Triceps, Chest, Forearms, Lats~Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.~The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting. Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together.~Bouncing the weight or lifting the hips off the bench.", "Piriformis-SMR~Mobility~stretch~1~A foam roller~2.3~h~1~Glutes~Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.~Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides.~Bouncing into the stretch or pushing into pain.", "Plate Pinch~Forearms~curl~2~Gym equipment (see steps)~3.5~h~1~Forearms~Grab two wide-rimmed plates and put them together with the smooth sides facing outward~Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position. Squeeze the plate with your fingers and thumb. Hold this position for as long as you can. Switch arms and repeat the movements.~Swinging the body or moving the elbows forward.", "Plate Twist~Abs & core~crunch~2~Gym equipment (see steps)~5.0~r~1~Abdominals~Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.~Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position. Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement. Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times.~Pulling on the neck with the hands.", "Platform Hamstring Slides~Hamstrings~rdl~2~Gym equipment (see steps)~3.5~r~0~Hamstrings, Glutes~For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.~Begin the movement by flexing the knee, keeping your other leg straight. Continue bringing the heel closer to you, sliding it on the floor. At full knee flexion, reverse the movement to return to the starting position.~Rounding the lower back instead of hinging at the hips.", "Plie Dumbbell Squat~Quads~goblet~1~Dumbbells~5.0~r~0~Quadriceps, Abdominals, Calves, Glutes~Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.~Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position. Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise. Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.~Letting the chest drop forward.", "Plyo Kettlebell Pushups~Chest~pushup~1~A kettlebell~5.0~r~2~Chest, Shoulders, Triceps~Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.~Begin by lowering yourself as low as you can, keeping your back straight. Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth.~Letting the hips sag or flaring the elbows wide.", "Plyo Push-up~Chest~pushup~0~None~8.0~r~0~Chest, Shoulders, Triceps~Move into a prone position on the floor, supporting your weight on your hands and toes.~Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position. Descend by flexing at the elbow, lowering your chest towards the ground. At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground. Return to the starting position and repeat the exercise.~Letting the hips sag or flaring the elbows wide.", "Posterior Tibialis Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Calves~In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.~With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.~Bouncing into the stretch or pushing into pain.", "Power Clean~Hamstrings~rdl~2~Barbell and plates~5.0~r~1~Hamstrings, Calves, Forearms, Glutes~Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.~Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended. Place the bar about 1 inch in front of your shins and over the balls of your feet. Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted. Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.~Rounding the lower back instead of hinging at the hips.", "Power Clean from Blocks~Full body~rdl~2~Barbell and plates~6.0~r~1~Hamstrings, Quadriceps~With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.~Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight.~Rounding the lower back instead of hinging at the hips.", "Power Jerk~Full body~squat~2~Barbell and plates~6.0~r~2~Quadriceps, Abdominals, Calves, Glutes~Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.~Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.~Letting the knees cave inward or the heels lift.", "Power Partials~Shoulders~ohpress~1~Dumbbells~3.5~r~0~Shoulders~Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.~The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position. Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling. Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling.~Arching the lower back to push the weight up.", "Power Snatch~Full body~rdl~2~Barbell and plates~6.0~r~2~Hamstrings, Calves, Glutes, Lower back~Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.~Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.~Rounding the lower back instead of hinging at the hips.", "Power Snatch from Blocks~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Calves, Forearms, Glutes~Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.~Begin the first pull by driving through the front of the heels, raising the bar from the boxes. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side. As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead.~Letting the knees cave inward or the heels lift.", "Preacher Curl~Biceps~curl~2~Barbell and plates~3.5~r~0~Biceps~To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.~With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position. As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.~Swinging the body or moving the elbows forward.", "Preacher Hammer Dumbbell Curl~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps, Forearms~Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip).~As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height. Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.~Swinging the body or moving the elbows forward.", "Press Sit-Up~Abs & core~crunch~2~Barbell and plates~5.0~r~2~Abdominals, Chest, Shoulders, Triceps~To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.~While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles. Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.~Pulling on the neck with the hands.", "Prone Manual Hamstring~Hamstrings~rdl~0~None~3.5~h~0~Hamstrings~You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.~To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels. Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction.~Rounding the lower back instead of hinging at the hips.", "Prowler Sprint~Cardio~run~2~Gym equipment (see steps)~7.0~t~0~Hamstrings, Calves, Chest, Glutes~Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.~You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement. With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.~Starting too fast and losing good posture.", "Pull Through~Glutes~bridge~2~Cable machine~5.0~r~0~Glutes, Hamstrings, Lower back~Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.~Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.~Arching the lower back instead of squeezing the glutes.", "Push-Up Wide~Chest~pushup~0~None~5.0~r~0~Chest, Abdominals, Shoulders, Triceps~With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.~To begin, allow the elbows to flex, lowering your chest to the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step. After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions.~Letting the hips sag or flaring the elbows wide.", "Push-Ups - Close Triceps Position~Triceps~pushup~0~None~5.0~r~1~Triceps, Chest, Shoulders~Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms' length.~Lower yourself until your chest almost touches the floor as you inhale. Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step. After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.~Letting the hips sag or flaring the elbows wide.", "Push-Ups With Feet Elevated~Chest~pushup~0~None~5.0~r~0~Chest, Shoulders, Triceps~Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.~Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is. Lower yourself until your chest almost touches the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step. After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.~Letting the hips sag or flaring the elbows wide.", "Push-Ups With Feet On An Exercise Ball~Chest~pushup~1~An exercise ball~5.0~r~1~Chest, Shoulders, Triceps~Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.~Place your toes on top of an exercise ball. This will allow your body to be elevated. Lower yourself until your chest almost touches the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step. After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.~Letting the hips sag or flaring the elbows wide.", "Push Press - Behind the Neck~Full body~ohpress~2~Barbell and plates~6.0~r~1~Shoulders, Calves, Quadriceps, Triceps~Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path.~Using the momentum generated, finish pressing the weight overhead be extending through the arms. Return to the starting position, using your legs to absorb the impact.~Arching the lower back to push the weight up.", "Push Up to Side Plank~Chest~pushup~0~None~5.0~r~0~Chest, Abdominals, Shoulders, Triceps~Get into pushup position on the toes with your hands just outside of shoulder width.~Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight. Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank. Lower the arm back to the floor for another pushup and then twist to the other side.~Letting the hips sag or flaring the elbows wide.", "Pushups (Close and Wide Hand Positions)~Chest~pushup~0~None~5.0~r~0~Chest, Shoulders, Triceps~Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.~Lower yourself until your chest almost touches the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step. After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.~Letting the hips sag or flaring the elbows wide.", "Pyramid~Mobility~stretch~1~An exercise ball~2.3~h~0~Lower back, Shoulders~Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.~Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders.~Bouncing into the stretch or pushing into pain.", "Quad Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Quadriceps~Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.~With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides.~Bouncing into the stretch or pushing into pain.", "Quadriceps-SMR~Mobility~stretch~1~A foam roller~2.3~h~1~Quadriceps~Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.~Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides.~Bouncing into the stretch or pushing into pain.", "Quick Leap~Quads~squat~2~Gym equipment (see steps)~8.0~r~0~Quadriceps, Calves, Hamstrings~You will need a box for this exerise.~Begin facing the box standing 1-2 feet from its edge. By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat. Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing.~Letting the knees cave inward or the heels lift.", "Rack Delivery~Full body~ohpress~2~Barbell and plates~6.0~r~1~Shoulders, Forearms, Traps~This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs.~Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the throat. It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision. As the movement becomes smoother, speed and load can be increased before progressing further.~Arching the lower back to push the weight up.", "Rack Pull with Bands~Back~superman~2~Barbell and plates~6.0~r~1~Lower back, Forearms, Glutes, Hamstrings~Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension.~Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight. With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.~Over-arching or straining the neck.", "Rack Pulls~Back~superman~2~Barbell and plates~6.0~r~1~Lower back, Forearms, Glutes, Hamstrings~Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.~With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement. Return the weight to the pins and repeat.~Over-arching or straining the neck.", "Rear Leg Raises~Mobility~stretch~0~None~2.3~h~0~Quadriceps~Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.~Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides.~Bouncing into the stretch or pushing into pain.", "Recumbent Bike~Cardio~cycle~2~Gym machine~7.0~t~0~Quadriceps, Calves, Glutes, Hamstrings~To begin, seat yourself on the bike and adjust the seat to your height.~Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.~A seat set too low, which strains the knees.", "Return Push from Stance~Shoulders~ohpress~1~A medicine ball~8.0~r~0~Shoulders, Chest, Triceps~You will need a partner for this drill.~Begin in an athletic 2 or 3 point stance. At the signal, move into a position to receive the pass from your partner. Catch the medicine ball with both hands and immediately throw it back to your partner. You can modify this drill by running different routes.~Arching the lower back to push the weight up.", "Reverse Band Bench Press~Triceps~bench~2~Barbell and plates~6.0~r~1~Triceps, Chest, Forearms, Lats~Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell.~Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.~Bouncing the weight or lifting the hips off the bench.", "Reverse Band Box Squat~Quads~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Abductors, Adductors, Calves~Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.~Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.~Letting the knees cave inward or the heels lift.", "Reverse Band Deadlift~Back~deadlift~2~Barbell and plates~6.0~r~2~Lower back, Abductors, Adductors, Calves~Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.~Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.~Rounding the back or jerking the weight off the floor.", "Reverse Band Power Squat~Quads~squat~2~Barbell and plates~6.0~r~2~Quadriceps, Adductors, Calves, Glutes~Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar.~Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent.~Letting the knees cave inward or the heels lift.", "Reverse Band Sumo Deadlift~Hamstrings~deadlift~2~Barbell and plates~6.0~r~2~Hamstrings, Abductors, Adductors, Calves~Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell.~Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms. Take a breath, and then lower your hips, looking forward with your head with your chest up.~Rounding the back or jerking the weight off the floor.", "Reverse Barbell Curl~Biceps~curl~2~Barbell and plates~3.5~r~0~Biceps, Forearms~Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.~While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle. Slowly begin to bring the bar back to starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Reverse Barbell Preacher Curls~Biceps~curl~2~EZ curl bar~3.5~r~1~Biceps, Forearms~Grab an EZ-bar using a shoulder width and palms down (pronated) grip.~Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position. As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position. As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.~Swinging the body or moving the elbows forward.", "Reverse Cable Curl~Biceps~curl~2~Cable machine~3.5~r~0~Biceps, Forearms~Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.~While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle. Slowly begin to bring the bar back to starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Reverse Flyes~Shoulders~frontraise~1~Dumbbells~3.5~r~0~Shoulders~To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).~Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position. Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise. The arms should be elevated until they are parallel to the floor.~Swinging the weight up with the body.", "Reverse Flyes With External Rotation~Shoulders~frontraise~1~Dumbbells~3.5~r~1~Shoulders~To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.~Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position. Maintaining the slight bend of the elbows, move the weights out and away from each other in an arc motion while exhaling.~Swinging the weight up with the body.", "Reverse Grip Bent-Over Rows~Back~row~2~Barbell and plates~5.0~r~1~Middle back, Biceps, Lats, Shoulders~Stand erect while holding a barbell with a supinated grip (palms facing up).~Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.~Rounding the back or jerking the weight with the arms only.", "Reverse Grip Triceps Pushdown~Triceps~pushdown~2~Cable machine~3.5~r~0~Triceps~Start by setting a bar attachment (straight or e-z) on a high pulley machine.~Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position. Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.~Letting the elbows drift away from the sides.", "Reverse Hyperextension~Hamstrings~rdl~2~Gym machine~3.5~r~1~Hamstrings, Calves, Glutes~Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.~To begin the movement, flex the hips, pulling the legs forward. Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion. Return by again flexing the hip, pulling the carriage forward as far as you can.~Rounding the lower back instead of hinging at the hips.", "Reverse Machine Flyes~Shoulders~frontraise~2~Gym machine~3.5~r~0~Shoulders~Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.~In a semicircular motion, pull your hands out to your side and back, contracting your rear delts. Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint. Pause at the rear of the movement, and slowly return the weight to the starting position.~Swinging the weight up with the body.", "Reverse Plate Curls~Biceps~curl~2~Gym equipment (see steps)~3.5~r~0~Biceps, Forearms~Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o'clock position.~Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position. Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torso at this point. Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling~Swinging the body or moving the elbows forward.", "Reverse Triceps Bench Press~Triceps~bench~2~Barbell and plates~5.0~r~1~Triceps, Chest, Shoulders~Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.~As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again.~Bouncing the weight or lifting the hips off the bench.", "Rhomboids-SMR~Mobility~stretch~1~A foam roller~2.3~h~1~Middle back, Traps~Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.~Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds.~Bouncing into the stretch or pushing into pain.", "Ring Dips~Triceps~dips~2~Gym equipment (see steps)~5.0~r~1~Triceps, Chest, Shoulders~Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.~Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. Reverse the motion by extending the elbow, pushing yourself back up into the starting position.~Dropping too deep and letting the shoulders roll forward.", "Rocket Jump~Quads~jacks~0~None~8.0~r~0~Quadriceps, Calves, Hamstrings~Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.~To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.~Landing heavily on the heels.", "Rocking Standing Calf Raise~Calves~calf~2~Barbell and plates~3.5~r~0~Calves~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck).~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance. Also maintain a straight back and keep the knees with a slight bend; never locked. This will be your starting position.~Bouncing at the bottom instead of a full, slow stretch.", "Rocky Pull-Ups/Pulldowns~Back~pullup~2~Gym equipment (see steps)~5.0~r~1~Lats, Biceps, Middle back, Shoulders~Grab the pull-up bar with the palms facing forward using a wide grip.~As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position. Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position.~Kipping or not lowering all the way.", "Romanian Deadlift from Deficit~Full body~rdl~2~Barbell and plates~6.0~r~1~Hamstrings, Forearms, Glutes, Lower back~Begin standing while holding a bar at arm's length in front of you. You can stand on a raised platform to increase the range of motion.~Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings. Reverse the motion to return to the starting position.~Rounding the lower back instead of hinging at the hips.", "Rope Climb~Back~row~2~Gym equipment (see steps)~5.0~r~1~Lats, Biceps, Forearms, Middle back~Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.~Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly. Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest. Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope. To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion.~Rounding the back or jerking the weight with the arms only.", "Rope Crunch~Abs & core~crunch~2~Cable machine~3.5~r~0~Abdominals~Kneel 1-2 feet in front of a cable system with a rope attached.~After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position. To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down. Pause at the bottom of the motion, and then slowly return to the starting position. These can be done with twists or to the side to hit the obliques.~Pulling on the neck with the hands.", "Rope Jumping~Cardio~skip~2~Gym equipment (see steps)~7.0~t~1~Quadriceps, Calves, Hamstrings~Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.~Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running.~Jumping too high and landing on flat feet.", "Rope Straight-Arm Pulldown~Back~latpull~2~Cable machine~3.5~r~0~Lats~Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.~Keeping your arms straight, extend the shoulder to pull the rope down to your thighs. Pause at the bottom of the motion, squeezing your lats. Return to the starting position without allowing the weight to fully rest on the stack.~Leaning far back or pulling behind the neck.", "Round The World Shoulder Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~0~Shoulders, Biceps, Chest~Stand up straight with your legs together, holding a bodybar or broomstick.~Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out. Slowly lift your arms up behind your head. Don't force it if it gets hard to lift further.~Bouncing into the stretch or pushing into pain.", "Rowing, Stationary~Cardio~run~2~Gym machine~7.0~t~1~Quadriceps, Biceps, Calves, Glutes~To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.~There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.~Starting too fast and losing good posture.", "Runner's Stretch~Mobility~stretch~0~None~2.3~h~0~Hamstrings, Calves~It's easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.~Keep the front heel on the floor (if it lifts up, scoot your other leg further back). Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You'll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front.~Bouncing into the stretch or pushing into pain.", "Running, Treadmill~Cardio~run~2~Gym machine~7.0~t~0~Quadriceps, Calves, Glutes, Hamstrings~To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.~Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour for 30 minutes. Maintain proper posture as you run, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.~Starting too fast and losing good posture.", "Scissor Kick~Mobility~stretch~0~None~2.3~h~0~Abdominals~To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.~With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position. Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground. Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.~Bouncing into the stretch or pushing into pain.", "Scissors Jump~Quads~jacks~0~None~8.0~r~0~Quadriceps, Glutes, Hamstrings~Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.~Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift. As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front. As you land, absorb the impact through the legs by adopting the lunge position, and repeat.~Landing heavily on the heels.", "Seated Band Hamstring Curl~Hamstrings~bridge~2~Gym equipment (see steps)~3.5~r~0~Hamstrings~Secure a band close to the ground and place a bench a couple feet away from it.~Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position. Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor. Pause at the completion of the movement, and then slowly return to the starting position.~Arching the lower back instead of squeezing the glutes.", "Seated Barbell Military Press~Shoulders~ohpress~2~Barbell and plates~5.0~r~1~Shoulders, Triceps~Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.~Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position. Lower the bar down to the collarbone slowly as you inhale. Lift the bar back up to the starting position as you exhale.~Arching the lower back to push the weight up.", "Seated Barbell Twist~Abs & core~crunch~2~Barbell and plates~3.5~r~0~Abdominals~Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other.~Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended. Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position. While keeping your feet and head stationary, move your waist from side to side so that your oblique muscles feel the contraction. Only move from side to side as far as your waist will allow you to go.~Pulling on the neck with the hands.", "Seated Bent-Over One-Arm Dumbbell Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~rs~0~Triceps~Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you).~Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.~Letting the elbows drift away from the sides.", "Seated Bent-Over Rear Delt Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~1~Shoulders~Place a couple of dumbbells looking forward in front of a flat bench.~Sit on the end of the bench with your legs together and the dumbbells behind your calves. Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position. Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights.~Swinging the weight up with the body.", "Seated Bent-Over Two-Arm Dumbbell Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~r~1~Triceps~Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you).~Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.~Letting the elbows drift away from the sides.", "Seated Biceps~Mobility~stretch~0~None~2.3~h~2~Biceps, Chest, Shoulders~Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position.~Attempt to flex your elbows, while your partner prevents any actual movement. After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching.~Bouncing into the stretch or pushing into pain.", "Seated Cable Rows~Back~cablerow~2~Cable machine~5.0~r~0~Middle back, Biceps, Lats, Shoulders~For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.~Lean over as you keep the natural alignment of your back and grab the V-bar handles. With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.~Rocking the whole body back and forth.", "Seated Cable Shoulder Press~Shoulders~ohpress~2~Cable machine~5.0~r~0~Shoulders, Triceps~Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position.~Begin by extending through the elbow, pressing the handles together above your head. After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables. You can also execute this movement with your back off the pad and alternate hands.~Arching the lower back to push the weight up.", "Seated Calf Stretch~Mobility~stretch~0~None~2.3~h~0~Calves, Hamstrings, Lower back~Sit up straight on an exercise mat.~Bend one knee and put that foot on the floor to stabilize the torso. Straighten your other leg and flex your ankle. Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides.~Bouncing into the stretch or pushing into pain.", "Seated Close-Grip Concentration Barbell Curl~Biceps~curl~2~Barbell and plates~3.5~r~1~Biceps~Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor.~Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip: Your arm should be extended at arms length and the barbell should be above the floor. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out.~Swinging the body or moving the elbows forward.", "Seated Dumbbell Curl~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps~Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.~Rotate the palms of the hands so that they are facing your torso. This will be your starting position. While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.~Swinging the body or moving the elbows forward.", "Seated Dumbbell Inner Biceps Curl~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps~Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso.~Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position. While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips: Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.~Swinging the body or moving the elbows forward.", "Seated Dumbbell Palms-Down Wrist Curl~Forearms~curl~1~Dumbbells~3.5~r~0~Forearms~Start out by placing two dumbbells on the floor in front of a flat bench.~Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling.~Swinging the body or moving the elbows forward.", "Seated Dumbbell Palms-Up Wrist Curl~Forearms~curl~1~Dumbbells~3.5~r~0~Forearms~Start out by placing two dumbbells on the floor in front of a flat bench.~Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling.~Swinging the body or moving the elbows forward.", "Seated Dumbbell Press~Shoulders~ohpress~1~Dumbbells~5.0~r~0~Shoulders, Triceps~Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.~Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side. Rotate the wrists so that the palms of your hands are facing forward. This is your starting position. As you exhale, push the dumbbells up until they touch at the top. After a second pause, slowly come down back to the starting position as you inhale.~Arching the lower back to push the weight up.", "Seated Flat Bench Leg Pull-In~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.~Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement. After a second pause, go back to the starting position as you inhale.~Pulling on the neck with the hands.", "Seated Floor Hamstring Stretch~Mobility~stretch~0~None~2.3~h~0~Hamstrings, Calves~Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.~Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side.~Bouncing into the stretch or pushing into pain.", "Seated Front Deltoid~Mobility~stretch~0~None~2.3~h~2~Shoulders, Chest~Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position.~Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds. Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest. Hold for 10 to 20 seconds.~Bouncing into the stretch or pushing into pain.", "Seated Glute~Mobility~stretch~0~None~2.3~h~2~Glutes, Adductors~In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.~Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso. Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.~Bouncing into the stretch or pushing into pain.", "Seated Good Mornings~Back~deadlift~2~Barbell and plates~6.0~r~1~Lower back, Glutes~Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.~Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position. Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.~Rounding the back or jerking the weight off the floor.", "Seated Hamstring~Mobility~stretch~0~None~2.3~h~2~Hamstrings, Calves~In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.~Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso. Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.~Bouncing into the stretch or pushing into pain.", "Seated Hamstring and Calf Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~1~Hamstrings, Calves~Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position.~Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg.~Bouncing into the stretch or pushing into pain.", "Seated Head Harness Neck Resistance~Mobility~stretch~2~Gym equipment (see steps)~3.5~r~1~Neck~Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out.~Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands while elevating your torso back until it is almost perpendicular to the floor. Note: Your head and torso needs to be slightly tilted forward to perform this exercise. Now place both hands on top of your knees. This is the starting position.~Bouncing into the stretch or pushing into pain.", "Seated Leg Tucks~Abs & core~crunch~0~None~3.5~r~0~Abdominals~Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.~Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement. After a second pause, go back to the starting position as you inhale.~Pulling on the neck with the hands.", "Seated One-Arm Dumbbell Palms-Down Wrist Curl~Forearms~curl~1~Dumbbells~3.5~rs~1~Forearms~Sit on a flat bench with a dumbbell in your right hand.~Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position. Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement. Now curl the dumbbell as high as possible as you contract the forearms and as you exhale.~Swinging the body or moving the elbows forward.", "Seated One-Arm Dumbbell Palms-Up Wrist Curl~Forearms~curl~1~Dumbbells~3.5~rs~0~Forearms~Sit on a flat bench with a dumbbell in your right hand.~Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position. Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement. Now curl the dumbbell as high as possible as you contract the forearms and as you exhale.~Swinging the body or moving the elbows forward.", "Seated One-arm Cable Pulley Rows~Back~cablerow~2~Cable machine~5.0~rs~1~Middle back, Biceps, Lats, Traps~To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.~Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip. With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.~Rocking the whole body back and forth.", "Seated Overhead Stretch~Mobility~stretch~0~None~2.3~h~0~Abdominals~Sit up straight on an exercise mat.~Touch the soles of your feet together with your feet six to eight inches in front of your hips. Place one hand on the floor beside you and your other hand behind your head. Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides.~Bouncing into the stretch or pushing into pain.", "Seated Palm-Up Barbell Wrist Curl~Forearms~curl~2~Barbell and plates~3.5~r~0~Forearms~Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.~Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as possible while inhaling and keeping a tight grip. Now curl bar up as high as possible while flexing the forearms and exhaling.~Swinging the body or moving the elbows forward.", "Seated Palms-Down Barbell Wrist Curl~Forearms~curl~2~Barbell and plates~3.5~r~0~Forearms~Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.~Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as possible while inhaling and keeping a tight grip. Now curl bar up as high as possible while flexing the forearms and exhaling.~Swinging the body or moving the elbows forward.", "Seated Side Lateral Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~0~Shoulders~Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms' length. This will be your starting position.~While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top. Lower the dumbbells back down slowly to the starting position as you inhale.~Swinging the weight up with the body.", "Seated Triceps Press~Triceps~pushdown~1~Dumbbells~3.5~r~0~Triceps~Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm's length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.~Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step. Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.~Letting the elbows drift away from the sides.", "Seated Two-Arm Palms-Up Low-Pulley Wrist Curl~Forearms~curl~2~Cable machine~3.5~r~0~Forearms~Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.~Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up. Now hold the handle with both hands, palms up, using a shoulder-width grip. Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor. Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.~Swinging the body or moving the elbows forward.", "See-Saw Press (Alternating Side Press)~Shoulders~ohpress~1~Dumbbells~5.0~rs~1~Shoulders, Abdominals, Triceps~Grab a dumbbell with each hand and stand up erect.~Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position. Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side.~Arching the lower back to push the weight up.", "Shotgun Row~Back~row~2~Cable machine~5.0~r~0~Lats, Biceps, Middle back~Attach a single handle to a low cable.~After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position. Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go. After a brief pause, return to the starting position.~Rounding the back or jerking the weight with the arms only.", "Shoulder Circles~Mobility~stretch~0~None~2.3~h~0~Shoulders, Traps~With shoulders relaxed and arms resting loosely at your sides (or in your lap if you're seated), gently roll your shoulders forward, up, back, and down.~Reverse direction. You can do this exercise alternating shoulders or both at the same time.~Bouncing into the stretch or pushing into pain.", "Shoulder Press - With Bands~Shoulders~ohpress~1~A resistance band~5.0~r~0~Shoulders, Triceps~To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles and lift them so that the hands are at shoulder height at each side.~Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position. As you exhale, lift the handles up until your arms are fully extended overhead.~Arching the lower back to push the weight up.", "Shoulder Raise~Mobility~stretch~0~None~2.3~h~0~Shoulders, Lats~Relax your arms to your sides and raise your shoulders up toward your ears, then back down.~Move slowly and with control through the full range.~Bouncing into the stretch or pushing into pain.", "Shoulder Stretch~Mobility~stretch~0~None~2.3~h~0~Shoulders~Reach your left arm across your body and hold it straight.~Move slowly and with control through the full range.~Bouncing into the stretch or pushing into pain.", "Side-Lying Floor Stretch~Mobility~stretch~0~None~2.3~h~0~Lats~First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).~Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides.~Bouncing into the stretch or pushing into pain.", "Side Hop-Sprint~Quads~squat~2~Gym equipment (see steps)~8.0~r~0~Quadriceps, Abductors, Adductors, Calves~Stand to the side of a cone or hurdle.~Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started. Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.~Letting the knees cave inward or the heels lift.", "Side Lateral Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~0~Shoulders~Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.~While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top. Lower the dumbbells back down slowly to the starting position as you inhale.~Swinging the weight up with the body.", "Side Laterals to Front Raise~Shoulders~frontraise~1~Dumbbells~3.5~r~0~Shoulders, Traps~In a standing position, hold a pair of dumbbells at your side. This will be your starting position.~Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating. At the top of the exercise move the weights out in front of you, keeping your arms extended. Lower the weights with a controlled motion. On the next repetition, raise the weights in front of you to shoulder height before moving the weights laterally to your sides. Lower the weights to the starting position.~Swinging the weight up with the body.", "Side Leg Raises~Mobility~stretch~0~None~2.3~h~0~Adductors~Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position.~Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg.~Bouncing into the stretch or pushing into pain.", "Side Lying Groin Stretch~Mobility~stretch~0~None~2.3~h~0~Adductors, Hamstrings~Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.~Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder). Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides.~Bouncing into the stretch or pushing into pain.", "Side Neck Stretch~Mobility~stretch~0~None~2.3~h~0~Neck~Start with your shoulders relaxed, gently tilt your head towards your shoulder.~Assist stretch with a gentle pull on the side of the head.~Bouncing into the stretch or pushing into pain.", "Side Standing Long Jump~Quads~jacks~0~None~8.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.~Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can. Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body.~Landing heavily on the heels.", "Side To Side Chins~Back~pullup~2~Gym equipment (see steps)~5.0~r~1~Lats, Biceps, Forearms, Middle back~Grab the pull-up bar with the palms facing forward using a wide grip.~As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position. Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement.~Kipping or not lowering all the way.", "Side Wrist Pull~Mobility~stretch~0~None~2.3~h~0~Shoulders, Forearms, Lats~This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm.~Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don't pull too hard on the shoulders joint. Switch sides.~Bouncing into the stretch or pushing into pain.", "Side to Side Box Shuffle~Quads~squat~2~Gym equipment (see steps)~8.0~r~0~Quadriceps, Abductors, Adductors, Calves~Stand to one side of the box with your left foot resting on the middle of it.~To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement. Continue shuffling back and forth across the box.~Letting the knees cave inward or the heels lift.", "Single-Arm Cable Crossover~Chest~bench~2~Cable machine~3.5~rs~0~Chest~Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.~Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position. Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.~Bouncing the weight or lifting the hips off the bench.", "Single-Arm Linear Jammer~Shoulders~ohpress~2~Barbell and plates~5.0~rs~1~Shoulders, Chest, Triceps~Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.~Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position. Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force. Return to the starting position.~Arching the lower back to push the weight up.", "Single-Arm Push-Up~Chest~pushup~0~None~5.0~rs~1~Chest, Shoulders, Triceps~Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up.~Maintain good posture, and place your free hand behind your back. This will be your starting position. Lower yourself by allowing the elbow to flex until you touch the ground. Descend slowly, and reverse direction be extending the arm to return to the starting position.~Letting the hips sag or flaring the elbows wide.", "Single-Cone Sprint Drill~Quads~squat~2~Gym equipment (see steps)~8.0~rs~0~Quadriceps, Calves, Glutes, Hamstrings~This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.~Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action. Rest after three trips around the cone.~Letting the knees cave inward or the heels lift.", "Single-Leg High Box Squat~Quads~squat~2~Gym equipment (see steps)~5.0~rs~0~Quadriceps, Glutes, Hamstrings~Position a box in a rack. Secure a band or rope in place above the box.~Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance . Continue stepping up and down on the same leg before switching to the opposite side.~Letting the knees cave inward or the heels lift.", "Single-Leg Hop Progression~Quads~squat~2~Gym equipment (see steps)~8.0~rs~0~Quadriceps, Abductors, Adductors, Calves~Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.~Hop forward, jumping and landing with the same leg over the cone. Use a countermovement jump to hop from cone to cone. At the end, turn around and go back on the other leg.~Letting the knees cave inward or the heels lift.", "Single-Leg Lateral Hop~Quads~squat~2~Gym equipment (see steps)~8.0~rs~0~Quadriceps, Abductors, Adductors, Calves~Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.~To begin, execute a counterjump to hop sideways over the cone. Land on your jumping leg, and immediately rebound out of it by jumping back to the start position. Continue hopping back and forth.~Letting the knees cave inward or the heels lift.", "Single-Leg Leg Extension~Quads~squat~2~Gym machine~3.5~rs~0~Quadriceps~Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities.~Maintaining good posture, fully extend one leg, pausing at the top of the motion. Return to the starting position without letting the weight stop, keeping tension on the muscle.~Letting the knees cave inward or the heels lift.", "Single-Leg Stride Jump~Quads~jacks~2~Gym equipment (see steps)~8.0~rs~0~Quadriceps, Abductors, Adductors, Calves~Stand to the side of a box with your inside foot on top of it, close to the edge.~Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward. Land in the same position that you started, using your inside leg to decelerate the impact.~Landing heavily on the heels.", "Single Dumbbell Raise~Shoulders~frontraise~1~Dumbbells~3.5~rs~0~Shoulders, Forearms, Traps~With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position.~Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement. Return to the starting position and repeat for the recommended amount of repetitions.~Swinging the weight up with the body.", "Single Leg Butt Kick~Quads~squat~0~None~8.0~rs~0~Quadriceps, Calves, Hamstrings~Begin by standing on one leg, with the bent knee raised. This will be your start position.~Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg. Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg. Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill.~Letting the knees cave inward or the heels lift.", "Single Leg Push-off~Quads~squat~2~Gym equipment (see steps)~8.0~rs~0~Quadriceps, Calves, Hamstrings~Stand on the ground with one foot resting on the box, heel close to the edge.~Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee. Land with the same foot on top of the box, returning your other foot back to the start position.~Letting the knees cave inward or the heels lift.", "Sit Squats~Mobility~stretch~0~None~2.3~h~0~Quadriceps, Abductors, Glutes, Hamstrings~Stand with your feet shoulder width apart. This will be your starting position.~Begin the movement by flexing your knees and hips, sitting back with your hips. Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions.~Bouncing into the stretch or pushing into pain.", "Skating~Cardio~run~2~Gym equipment (see steps)~7.0~t~1~Quadriceps, Abductors, Adductors, Calves~Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury.~You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes to recover. A 150 lb person will typically burn about 175 calories in 30 minutes skating at a comfortable pace, similar to brisk walking.~Starting too fast and losing good posture.", "Sled Overhead Backward Walk~Shoulders~ohpress~2~Gym equipment (see steps)~5.0~r~0~Shoulders, Calves, Middle back, Quadriceps~Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.~Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position. Walk backwards, keeping your arms raised above your head. Avoid jerky movements.~Arching the lower back to push the weight up.", "Sled Overhead Triceps Extension~Triceps~pushdown~2~Gym equipment (see steps)~3.5~r~0~Triceps~Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.~Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position. Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps. Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability.~Letting the elbows drift away from the sides.", "Sled Reverse Flye~Shoulders~frontraise~2~Gym equipment (see steps)~3.5~r~0~Shoulders~Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.~Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position. Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this. Return to the starting position, taking a couple steps back to take the slack out of the line.~Swinging the weight up with the body.", "Sled Row~Back~row~2~Gym equipment (see steps)~5.0~r~0~Middle back, Biceps, Lats~Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line.~With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended. To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you. Take a step or two back to get tension in the line and repeat.~Rounding the back or jerking the weight with the arms only.", "Sledgehammer Swings~Abs & core~crunch~2~Gym equipment (see steps)~8.0~r~0~Abdominals, Calves, Forearms, Lats~You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.~If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head. As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.~Pulling on the neck with the hands.", "Smith Incline Shoulder Raise~Shoulders~frontraise~2~Barbell and plates~3.5~r~0~Shoulders, Chest~Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell.~Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the elbows. This will be your starting position. As you breathe out, lift the bar up until your arms are fully extended. Note: The contraction should be felt around the shoulders. After a second pause, bring the bar back down to the starting position as you breathe in. When you are done, place the bar back in the rack.~Swinging the weight up with the body.", "Smith Machine Behind the Back Shrug~Back~row~2~Gym machine~3.5~r~0~Traps, Shoulders~With the bar at thigh level, load an appropriate weight.~Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position. Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement. After a brief pause return the weight to the starting position.~Rounding the back or jerking the weight with the arms only.", "Smith Machine Bent Over Row~Back~row~2~Gym machine~5.0~r~0~Middle back, Biceps, Lats, Shoulders~Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.~Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.~Rounding the back or jerking the weight with the arms only.", "Smith Machine Calf Raise~Calves~calf~2~Gym machine~3.5~r~0~Calves~Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.~Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position. Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down. Return slowly to the starting position as you breathe in while lowering your heels.~Bouncing at the bottom instead of a full, slow stretch.", "Smith Machine Close-Grip Bench Press~Triceps~pushdown~2~Gym machine~5.0~r~0~Triceps, Chest, Shoulders~Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.~As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again.~Letting the elbows drift away from the sides.", "Smith Machine Decline Press~Chest~bench~2~Gym machine~5.0~r~0~Chest, Shoulders, Triceps~Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench.~Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position. Begin the movement by flexing your arms, lowering the bar to your chest. Pause briefly, and then extend your arms to push the weight back to the starting position. After completing the desired number of repetitions, rotate the bar to rack the weight.~Bouncing the weight or lifting the hips off the bench.", "Smith Machine Hang Power Clean~Hamstrings~rdl~2~Gym machine~5.0~r~1~Hamstrings, Glutes, Lower back, Quadriceps~Position the bar at knee height and load it to an appropriate weight.~Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position. Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure that you keep your arms straight during this part of the motion.~Rounding the lower back instead of hinging at the hips.", "Smith Machine Hip Raise~Abs & core~crunch~2~Gym machine~3.5~r~0~Abdominals~Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position.~Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion. After a brief pause, return the hips to the bench.~Pulling on the neck with the hands.", "Smith Machine Incline Bench Press~Chest~bench~2~Gym machine~5.0~r~0~Chest, Shoulders, Triceps~Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.~As you breathe in, come down slowly until you feel the bar on your upper chest. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up. When you are done, place the bar back in the rack.~Bouncing the weight or lifting the hips off the bench.", "Smith Machine Leg Press~Quads~squat~2~Gym machine~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position.~Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees. At the top of the motion, pause briefly before returning to the starting position.~Letting the knees cave inward or the heels lift.", "Smith Machine One-Arm Upright Row~Shoulders~ohpress~2~Gym machine~5.0~rs~0~Shoulders, Biceps, Traps~With the bar at thigh level, load an appropriate weight.~Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position. Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor. After a brief pause, return the weight to the starting position.~Arching the lower back to push the weight up.", "Smith Machine Overhead Shoulder Press~Shoulders~ohpress~2~Gym machine~5.0~r~0~Shoulders, Triceps~To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.~Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position. Slowly begin to lower the barbell until it is level with your chin while inhaling. Then lift the barbell back to the starting position using your shoulders while exhaling.~Arching the lower back to push the weight up.", "Smith Machine Pistol Squat~Quads~squat~2~Gym machine~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders.~Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3 Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position. Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows.~Letting the knees cave inward or the heels lift.", "Smith Machine Reverse Calf Raises~Calves~calf~2~Gym machine~3.5~r~0~Calves~Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar.~Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance. Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. This will be your starting position.~Bouncing at the bottom instead of a full, slow stretch.", "Smith Machine Stiff-Legged Deadlift~Hamstrings~rdl~2~Gym machine~5.0~r~0~Hamstrings, Glutes, Lower back~To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.~Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position. Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings.~Rounding the lower back instead of hinging at the hips.", "Smith Machine Upright Row~Back~row~2~Gym machine~5.0~r~0~Traps, Biceps, Middle back, Shoulders~To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.~Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position. Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.~Rounding the back or jerking the weight with the arms only.", "Smith Single-Leg Split Squat~Quads~lunge~2~Gym machine~5.0~rs~0~Quadriceps, Calves, Glutes, Hamstrings~To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.~Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Position your legs by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the bench. This will be your starting position Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up.~Letting the front knee drift inward or leaning the torso forward.", "Snatch~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Biceps, Glutes, Hamstrings~Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.~With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position. Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.~Letting the knees cave inward or the heels lift.", "Snatch Balance~Full body~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.~Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position. Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs. Continue to descend to full depth, and return to a standing position. Carefully lower the weight.~Letting the knees cave inward or the heels lift.", "Snatch Deadlift~Full body~deadlift~2~Barbell and plates~6.0~r~1~Hamstrings, Forearms, Glutes, Hamstrings~The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward.~Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees. At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion.~Rounding the back or jerking the weight off the floor.", "Snatch Pull~Hamstrings~rdl~2~Barbell and plates~5.0~r~1~Hamstrings, Calves, Glutes, Lower back~With a barbell on the floor close to the shins, take a wide snatch grip. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.~Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Next comes the second pull, the main source of acceleration for the pull. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.~Rounding the lower back instead of hinging at the hips.", "Snatch Shrug~Full body~row~2~Barbell and plates~6.0~r~1~Traps, Forearms, Shoulders~Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.~Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down.~Rounding the back or jerking the weight with the arms only.", "Snatch from Blocks~Full body~squat~2~Barbell and plates~6.0~r~2~Quadriceps, Calves, Forearms, Glutes~Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.~Begin the first pull by driving through the front of the heels, raising the bar from the boxes. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side. As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead.~Letting the knees cave inward or the heels lift.", "Speed Band Overhead Triceps~Triceps~pushdown~1~A resistance band~3.5~r~0~Triceps~For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.~To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position. To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place. Pause, and then return to the starting position.~Letting the elbows drift away from the sides.", "Speed Box Squat~Quads~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension.~Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn't so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max. Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position. Unrack the bar and position yourself in front of the box.~Letting the knees cave inward or the heels lift.", "Speed Squats~Quads~squat~2~Barbell and plates~5.0~r~2~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.~Letting the knees cave inward or the heels lift.", "Spell Caster~Abs & core~crunch~1~Dumbbells~5.0~r~0~Abdominals, Glutes, Shoulders~Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.~Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso. Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side. Continue alternating, rotating from one side to the other until the set is complete.~Pulling on the neck with the hands.", "Spider Crawl~Abs & core~crunch~0~None~5.0~r~0~Abdominals, Chest, Shoulders, Triceps~Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.~Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible. Return this leg to the starting position and repeat on the opposite side.~Pulling on the neck with the hands.", "Spider Curl~Biceps~curl~2~EZ curl bar~3.5~r~0~Biceps~Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.~Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench. Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.~Swinging the body or moving the elbows forward.", "Spinal Stretch~Mobility~stretch~0~None~2.3~h~0~Middle back, Lats, Lower back, Neck~Sit in a chair so your back is straight and your feet planted on the floor.~Interlace your fingers behind your head, elbows out and your chin down. Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee. Return to upright position and then repeat for your other side.~Bouncing into the stretch or pushing into pain.", "Split Clean~Full body~lunge~2~Barbell and plates~6.0~r~1~Quadriceps, Calves, Forearms, Glutes~With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.~Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.~Letting the front knee drift inward or leaning the torso forward.", "Split Jerk~Full body~lunge~2~Barbell and plates~6.0~r~1~Quadriceps, Glutes, Hamstrings, Shoulders~Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.~Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athlete's effort to push the bar up will drive them down.~Letting the front knee drift inward or leaning the torso forward.", "Split Jump~Quads~lunge~0~None~8.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.~Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift. As you jump, bring your feet together, and move them back to their initial positions as you land. Absorb the impact by reverting back to the starting position.~Letting the front knee drift inward or leaning the torso forward.", "Split Snatch~Full body~rdl~2~Barbell and plates~6.0~r~2~Hamstrings, Calves, Forearms, Glutes~Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.~Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.~Rounding the lower back instead of hinging at the hips.", "Split Squat with Dumbbells~Quads~lunge~1~Dumbbells~5.0~r~0~Quadriceps, Glutes, Hamstrings~Position yourself into a staggered stance with the rear foot elevated and front foot forward.~Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position. Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise. At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.~Letting the front knee drift inward or leaning the torso forward.", "Split Squats~Mobility~stretch~0~None~2.3~h~1~Hamstrings, Calves, Glutes, Quadriceps~Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.~As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg.~Bouncing into the stretch or pushing into pain.", "Squat Jerk~Quads~squat~2~Barbell and plates~5.0~r~2~Quadriceps, Calves, Glutes, Hamstrings~Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.~At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athlete's effort to push the bar up will drive them down. The feet should move forcefully to just outside the hips, turned out as necessary. Receive the bar with your body in a full squat and the arms fully extended overhead.~Letting the knees cave inward or the heels lift.", "Squat with Bands~Quads~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Adductors, Calves, Glutes~Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension.~Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent.~Letting the knees cave inward or the heels lift.", "Squat with Chains~Quads~squat~2~Barbell and plates~6.0~r~1~Quadriceps, Adductors, Calves, Glutes~To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.~Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent.~Letting the knees cave inward or the heels lift.", "Squat with Plate Movers~Quads~squat~2~Barbell and plates~5.0~r~1~Quadriceps, Abductors, Adductors, Calves~To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.~Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso. Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position. Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.~Letting the knees cave inward or the heels lift.", "Squats - With Bands~Quads~squat~1~A resistance band~5.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.~When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position. Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling. Use the heel of your feet to push your body up to the starting position as you exhale.~Letting the knees cave inward or the heels lift.", "Stairmaster~Cardio~run~2~Gym machine~7.0~t~1~Quadriceps, Calves, Glutes, Hamstrings~To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.~Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don't fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity. Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment.~Starting too fast and losing good posture.", "Standing Alternating Dumbbell Press~Shoulders~ohpress~1~Dumbbells~5.0~rs~0~Shoulders, Triceps~Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position.~Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement. After a brief pause, return the weight to the starting position.~Arching the lower back to push the weight up.", "Standing Barbell Calf Raise~Calves~calf~2~Barbell and plates~3.5~r~0~Calves~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position.~Bouncing at the bottom instead of a full, slow stretch.", "Standing Barbell Press Behind Neck~Shoulders~ohpress~2~Barbell and plates~5.0~r~1~Shoulders, Triceps~This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Your back should be kept straight while performing this exercise. This will be your starting position. Elevate the barbell overhead by fully extending your arms while breathing out.~Arching the lower back to push the weight up.", "Standing Bent-Over One-Arm Dumbbell Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~rs~0~Triceps, Shoulders~With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.~The upper arm should be close to the torso and parallel to the floor while the forearm is pointing towards the floor as the hand holds the weight. Tip: There should be a 90-degree angle between the forearm and the upper arm. This is your starting position. Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.~Letting the elbows drift away from the sides.", "Standing Bent-Over Two-Arm Dumbbell Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~r~0~Triceps~With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms should be close to the torso and parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights. Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.~Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arms are extended. Like many other arm exercises, only the forearm moves. After a second contraction at the top, slowly lower the dumbbells back to their starting position as you inhale.~Letting the elbows drift away from the sides.", "Standing Biceps Cable Curl~Biceps~curl~2~Cable machine~3.5~r~0~Biceps~Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.~While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle. Slowly begin to bring the curl bar back to starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Standing Biceps Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~0~Biceps, Chest, Shoulders~Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.~Raise your arms up and hold until you feel a stretch in your biceps.~Bouncing into the stretch or pushing into pain.", "Standing Bradford Press~Shoulders~ohpress~2~Barbell and plates~5.0~r~0~Shoulders, Triceps~Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position.~Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head. Lower the bar down to the back of the head until your elbow forms a right angle. Lift the bar back over your head by extending the elbows Lower the bar down to the starting position. Alternate in this manner until you complete the recommended amount of repetitions.~Arching the lower back to push the weight up.", "Standing Cable Chest Press~Chest~bench~2~Cable machine~5.0~r~0~Chest, Shoulders, Triceps~Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.~Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position. Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you. Pause at the top of the motion, and return to the starting position.~Bouncing the weight or lifting the hips off the bench.", "Standing Cable Lift~Abs & core~crunch~2~Cable machine~5.0~r~0~Abdominals, Shoulders~Connect a standard handle on a tower, and move the cable to the lowest pulley position.~With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable. With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended. In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.~Pulling on the neck with the hands.", "Standing Cable Wood Chop~Abs & core~crunch~2~Cable machine~5.0~r~0~Abdominals, Shoulders~Connect a standard handle to a tower, and move the cable to the highest pulley position.~With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable. With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended. In one motion, pull the handle down and across your body to your front knee while rotating your torso.~Pulling on the neck with the hands.", "Standing Calf Raises~Calves~calf~2~Gym machine~3.5~r~0~Calves~Adjust the padded lever of the calf raise machine to fit your height.~Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter.~Bouncing at the bottom instead of a full, slow stretch.", "Standing Concentration Curl~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps, Forearms~Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position.~Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause. Lower the dumbbell back to the starting position.~Swinging the body or moving the elbows forward.", "Standing Dumbbell Calf Raise~Calves~calf~1~Dumbbells~3.5~r~1~Calves~Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.~With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second. As you inhale, go back to the starting position by slowly lowering the heels.~Bouncing at the bottom instead of a full, slow stretch.", "Standing Dumbbell Press~Shoulders~ohpress~1~Dumbbells~5.0~r~0~Shoulders, Triceps~Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.~Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head. Pause, and slowly return the weight to the starting position.~Arching the lower back to push the weight up.", "Standing Dumbbell Reverse Curl~Biceps~curl~1~Dumbbells~3.5~r~1~Biceps, Forearms~To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position.~While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle. Slowly begin to bring the dumbbells back to starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Standing Dumbbell Straight-Arm Front Delt Raise Above Head~Shoulders~frontraise~1~Dumbbells~3.5~r~1~Shoulders~Hold the dumbbells in front of your thighs, palms facing your thighs.~Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position. Raise the dumbbells in a semicircular motion to arm's length overhead as you exhale. Slowly return to the starting position using the same path as you inhale.~Swinging the weight up with the body.", "Standing Dumbbell Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~r~0~Triceps~To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.~The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position. Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.~Letting the elbows drift away from the sides.", "Standing Dumbbell Upright Row~Back~row~1~Dumbbells~5.0~r~0~Traps, Biceps, Shoulders~Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.~Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement. Lower the dumbbells back down slowly to the starting position.~Rounding the back or jerking the weight with the arms only.", "Standing Elevated Quad Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~0~Quadriceps~Start by standing with your back about two to three feet away from a bench or step.~Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable. Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides.~Bouncing into the stretch or pushing into pain.", "Standing Front Barbell Raise Over Head~Shoulders~frontraise~2~Barbell and plates~3.5~r~1~Shoulders~To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other.~Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position. Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when performing each repetition. Once you feel the contraction, begin to lower the barbell back down to the starting position as you inhale.~Swinging the weight up with the body.", "Standing Gastrocnemius Calf Stretch~Mobility~stretch~0~None~2.3~h~0~Calves, Hamstrings~Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.~Support your weight on your left leg and place your left hand on your left thigh. Pull your right toes toward your knee until you feel a stretch in your calf.~Bouncing into the stretch or pushing into pain.", "Standing Hamstring and Calf Stretch~Mobility~stretch~2~Gym equipment (see steps)~2.3~h~0~Hamstrings~Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.~Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward. Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot.~Bouncing into the stretch or pushing into pain.", "Standing Hip Circles~Mobility~stretch~0~None~2.3~h~0~Abductors, Adductors~Begin standing on one leg, holding to a vertical support.~Raise the unsupported knee to 90 degrees. This will be your starting position. Open the hip as far as possible, attempting to make a big circle with your knee. Perform this movement slowly for a number of repetitions, and repeat on the other side.~Bouncing into the stretch or pushing into pain.", "Standing Hip Flexors~Mobility~stretch~0~None~2.3~h~0~Quadriceps~Stand up straight with the spine vertical, the left foot slightly in front of the right.~Bend both knees and lift the back heel off the floor as you press the right hip forward. You can't get a thorough, deep stretch in this position, however, because it's hard to relax the hip flexor and stand on it at the same time. Switch sides.~Bouncing into the stretch or pushing into pain.", "Standing Inner-Biceps Curl~Biceps~curl~1~Dumbbells~3.5~r~1~Biceps~Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder's width apart from each other.~Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position. While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your wrist should turn so that when the weights are fully elevated you have supinated grip (palms facing up). Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.~Swinging the body or moving the elbows forward.", "Standing Lateral Stretch~Mobility~stretch~0~None~2.3~h~0~Abdominals~Take a slightly wider than hip distance stance with your knees slightly bent.~Place your right hand on your right hip to support the spine. Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right. Keep your weight evenly distributed between both legs (don't lean into your left hip). Switch sides.~Bouncing into the stretch or pushing into pain.", "Standing Leg Curl~Hamstrings~bridge~2~Gym machine~3.5~r~0~Hamstrings~Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.~Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position. As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second. As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions. Perform the same exercise now for the left leg.~Arching the lower back instead of squeezing the glutes.", "Standing Long Jump~Quads~jacks~0~None~8.0~r~0~Quadriceps, Calves, Glutes, Hamstrings~This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.~Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can. Attempt to land with your feet out in front you, reaching as far as possible with your legs. Measure the distance from your landing point to the starting point and track results.~Landing heavily on the heels.", "Standing Low-Pulley Deltoid Raise~Shoulders~frontraise~2~Cable machine~3.5~r~0~Shoulders, Forearms~Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.~Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position. Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling. Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling. Switch arms and repeat the exercise.~Swinging the weight up with the body.", "Standing Low-Pulley One-Arm Triceps Extension~Triceps~pushdown~2~Cable machine~3.5~rs~1~Triceps, Chest, Shoulders~Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position.~Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step. Go back to the starting position by using the triceps to raise the single handle. Breathe out as you perform this step. Switch arms and repeat the exercise.~Letting the elbows drift away from the sides.", "Standing Military Press~Shoulders~ohpress~2~Barbell and plates~5.0~r~0~Shoulders, Triceps~Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.~Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other. Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position. Lower the bar down to the collarbone slowly as you inhale.~Arching the lower back to push the weight up.", "Standing Olympic Plate Hand Squeeze~Forearms~curl~2~Gym equipment (see steps)~3.5~h~0~Forearms, Biceps~To begin, stand straight while holding a weight plate by the ridge at arm's length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.~Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates. Now raise the plates back to the starting position as you exhale by closing your hands.~Swinging the body or moving the elbows forward.", "Standing One-Arm Cable Curl~Biceps~curl~2~Cable machine~3.5~rs~1~Biceps~Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.~Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance. Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move. Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.~Swinging the body or moving the elbows forward.", "Standing One-Arm Dumbbell Curl Over Incline Bench~Biceps~curl~1~Dumbbells~3.5~rs~0~Biceps~Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip.~Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position. While holding the upper arm stationary, curl the dumbbell upward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbell is at shoulder level.~Swinging the body or moving the elbows forward.", "Standing One-Arm Dumbbell Triceps Extension~Triceps~pushdown~1~Dumbbells~3.5~rs~0~Triceps, Chest, Shoulders~To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.~This will be your starting position. Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step. Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step. Switch arms and repeat the exercise.~Letting the elbows drift away from the sides.", "Standing Overhead Barbell Triceps Extension~Triceps~pushdown~2~Barbell and plates~3.5~r~0~Triceps, Shoulders~To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart.~Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position. Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step. Go back to the starting position by using the triceps to raise the barbell.~Letting the elbows drift away from the sides.", "Standing Palm-In One-Arm Dumbbell Press~Shoulders~ohpress~1~Dumbbells~5.0~rs~0~Shoulders, Triceps~Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.~Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbell up until your arm is fully extended. This the starting position. While inhaling lower the weight down until your arm is at a 90 degree angle again.~Arching the lower back to push the weight up.", "Standing Palms-In Dumbbell Press~Shoulders~ohpress~1~Dumbbells~5.0~r~1~Shoulders, Triceps~Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position.~Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended. While inhaling lower the weights down until your arm is at a 90 degree angle again.~Arching the lower back to push the weight up.", "Standing Palms-Up Barbell Behind The Back Wrist Curl~Forearms~curl~2~Barbell and plates~3.5~r~0~Forearms~Start by standing straight and holding a barbell behind your glutes at arm's length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.~You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position. While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise. Hold the contraction for a second and lower the barbell back down to the starting position while inhaling. When finished, lower the barbell down to the squat rack or the floor by bending the knees.~Swinging the body or moving the elbows forward.", "Standing Pelvic Tilt~Mobility~stretch~0~None~2.3~h~0~Lower back, Glutes~Start off with your feet hip-distance apart.~Bend your knees slightly to keep them soft and springy. You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch.~Bouncing into the stretch or pushing into pain.", "Standing Rope Crunch~Abs & core~crunch~2~Cable machine~3.5~r~0~Abdominals~Attach a rope to a high pulley and select an appropriate weight.~Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position. Perform the movement by flexing the spine, crunching the weight down as far as you can. Hold the peak contraction for a moment before returning to the starting position.~Pulling on the neck with the hands.", "Standing Soleus And Achilles Stretch~Mobility~stretch~0~None~2.3~h~0~Calves~Stand with your feet hip-distance apart, one foot slightly in front of the other.~Bend both knees, keeping your back heel on the floor. Switch sides.~Bouncing into the stretch or pushing into pain.", "Standing Toe Touches~Mobility~stretch~0~None~2.3~h~0~Hamstrings, Calves~Stand with some space in front and behind you.~Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds.~Bouncing into the stretch or pushing into pain.", "Standing Towel Triceps Extension~Triceps~pushdown~0~None~3.5~r~0~Triceps~To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.~Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step. Go back to the starting position by using the triceps to raise the towel.~Letting the elbows drift away from the sides.", "Standing Two-Arm Overhead Throw~Shoulders~ohpress~1~A medicine ball~8.0~r~0~Shoulders, Chest, Lats~Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.~Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement. The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back.~Arching the lower back to push the weight up.", "Step-up with Knee Raise~Glutes~lunge~0~None~5.0~r~0~Glutes, Hamstrings, Quadriceps~Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.~Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can. Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.~Letting the front knee drift inward or leaning the torso forward.", "Step Mill~Cardio~run~2~Gym machine~7.0~t~1~Quadriceps, Calves, Glutes, Hamstrings~To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don't trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don't fall.~Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.~Starting too fast and losing good posture.", "Stiff-Legged Barbell Deadlift~Hamstrings~rdl~2~Barbell and plates~5.0~r~1~Hamstrings, Glutes, Lower back~Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.~Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position. Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.~Rounding the lower back instead of hinging at the hips.", "Stiff-Legged Dumbbell Deadlift~Hamstrings~rdl~1~Dumbbells~5.0~r~0~Hamstrings, Glutes, Lower back~Grasp a couple of dumbbells holding them by your side at arm's length.~Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position. Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings.~Rounding the lower back instead of hinging at the hips.", "Stiff Leg Barbell Good Morning~Back~deadlift~2~Barbell and plates~5.0~r~0~Lower back, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Keeping your legs stationary, move your torso forward by bending at the hips while inhaling.~Rounding the back or jerking the weight off the floor.", "Stomach Vacuum~Mobility~stretch~0~None~2.3~h~0~Abdominals~To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.~Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone. One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position. Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds.~Bouncing into the stretch or pushing into pain.", "Straight-Arm Dumbbell Pullover~Chest~bench~1~Dumbbells~5.0~r~1~Chest, Lats, Shoulders, Triceps~Place a dumbbell standing up on a flat bench.~Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well. Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position.~Bouncing the weight or lifting the hips off the bench.", "Straight Bar Bench Mid Rows~Back~row~2~Barbell and plates~5.0~r~0~Middle back, Biceps, Lats~Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position.~Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking. After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down.~Rounding the back or jerking the weight with the arms only.", "Straight Raises on Incline Bench~Shoulders~frontraise~2~Barbell and plates~3.5~r~0~Shoulders, Traps~Place a bar on the ground behind the head of an incline bench.~Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position. To begin, raise the barbell out in front of your head while keeping your arms extended. Return to the starting position.~Swinging the weight up with the body.", "Stride Jump Crossover~Quads~jacks~2~Gym equipment (see steps)~8.0~r~0~Quadriceps, Abductors, Adductors, Calves~Stand to the side of a box with your inside foot on top of it, close to the edge.~Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward. Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.~Landing heavily on the heels.", "Sumo Deadlift with Bands~Hamstrings~deadlift~2~Barbell and plates~6.0~r~1~Hamstrings, Adductors, Forearms, Glutes~To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor.~Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet.~Rounding the back or jerking the weight off the floor.", "Sumo Deadlift with Chains~Hamstrings~deadlift~2~Barbell and plates~6.0~r~1~Hamstrings, Abductors, Adductors, Forearms~You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don't hit them when you lower the weight.~Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms. Take a breath, and then lower your hips, looking forward with your head with your chest up.~Rounding the back or jerking the weight off the floor.", "Superman~Mobility~stretch~0~None~2.3~h~0~Lower back, Glutes, Hamstrings~To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.~Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying. Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.~Bouncing into the stretch or pushing into pain.", "Supine Chest Throw~Triceps~pushdown~1~A medicine ball~8.0~r~0~Triceps, Chest, Shoulders~This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent.~Begin with the ball on your chest, held with both hands on the bottom. Explode up, extending through the elbow to throw the ball directly above you as high as possible. Catch the ball with both hands as it comes down.~Letting the elbows drift away from the sides.", "Supine One-Arm Overhead Throw~Abs & core~crunch~1~A medicine ball~8.0~rs~0~Abdominals, Chest, Lats, Shoulders~Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.~Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. The ball can be thrown to a partner or bounced off of a wall.~Pulling on the neck with the hands.", "Supine Two-Arm Overhead Throw~Abs & core~crunch~1~A medicine ball~8.0~r~0~Abdominals, Chest, Lats, Shoulders~Lay on the ground on your back with your knees bent.~Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position. Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. The ball can be thrown to a partner or bounced off of a wall.~Pulling on the neck with the hands.", "Suspended Fallout~Abs & core~crunch~2~Gym equipment (see steps)~3.5~r~1~Abdominals, Chest, Lower back, Shoulders~Adjust the straps so the handles are at an appropriate height, below waist level.~Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position. Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head. Maintain a neutral spine and keep the rest of your body straight, your shoulders being the only joints allowed to move.~Pulling on the neck with the hands.", "Suspended Push-Up~Chest~pushup~2~Gym equipment (see steps)~5.0~r~0~Chest, Shoulders, Triceps~Anchor your suspension straps securely to the top of a rack or other object.~Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture. Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex. Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position.~Letting the hips sag or flaring the elbows wide.", "Suspended Reverse Crunch~Abs & core~crunch~2~Gym equipment (see steps)~3.5~r~0~Abdominals~Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack.~Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position. Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex. At the top of the controlled motion, return to the starting position.~Pulling on the neck with the hands.", "Suspended Row~Back~row~2~Gym equipment (see steps)~5.0~r~0~Middle back, Biceps, Lats~Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position.~Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so. At the completion of the motion pause, and then return to the starting position.~Rounding the back or jerking the weight with the arms only.", "Suspended Split Squat~Quads~lunge~2~Gym equipment (see steps)~5.0~r~1~Quadriceps, Abductors, Adductors, Calves~Suspend your straps so the handles are 18-30 inches from the floor.~Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position. Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise. At the bottom of the movement, reverse the motion, extending through the hip and knee to return to the starting position.~Letting the front knee drift inward or leaning the torso forward.", "T-Bar Row with Handle~Back~row~2~Barbell and plates~5.0~r~0~Middle back, Biceps, Lats~Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.~Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position. Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position. Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement. After a brief pause, return to the starting position.~Rounding the back or jerking the weight with the arms only.", "Tate Press~Triceps~pushdown~1~Dumbbells~3.5~r~1~Triceps, Chest, Shoulders~Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.~By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.~Letting the elbows drift away from the sides.", "The Straddle~Mobility~stretch~0~None~2.3~h~0~Hamstrings, Adductors, Calves~Begin in a seated, upright position. Start by extending your legs in front of you in a V.~With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds.~Bouncing into the stretch or pushing into pain.", "Thigh Abductor~Glutes~bridge~2~Gym machine~3.5~r~0~Abductors, Glutes~To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.~Slowly press against the machine with your legs to move them away from each other while exhaling. Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.~Arching the lower back instead of squeezing the glutes.", "Thigh Adductor~Glutes~bridge~2~Gym machine~3.5~r~0~Adductors, Glutes, Hamstrings~To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.~Slowly press against the machine with your legs to move them towards each other while exhaling. Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.~Arching the lower back instead of squeezing the glutes.", "Toe Touchers~Mobility~stretch~0~None~2.3~h~0~Abdominals~To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.~Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor. Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position. While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.~Bouncing into the stretch or pushing into pain.", "Torso Rotation~Mobility~stretch~1~An exercise ball~2.3~h~0~Abdominals~Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.~Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions.~Bouncing into the stretch or pushing into pain.", "Trail Running/Walking~Cardio~walk~0~None~7.0~t~0~Quadriceps, Calves, Glutes, Hamstrings~Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling.~A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat surface. If running the trail, a 150 lb person can burn well over 500 calories in 30 minutes.~Hunching forward instead of walking tall.", "Tricep Dumbbell Kickback~Triceps~pushdown~1~Dumbbells~3.5~r~0~Triceps~Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.~Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm. After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.~Letting the elbows drift away from the sides.", "Tricep Side Stretch~Mobility~stretch~0~None~2.3~h~0~Triceps, Shoulders~Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm.~Move slowly and with control through the full range.~Bouncing into the stretch or pushing into pain.", "Triceps Overhead Extension with Rope~Triceps~pushdown~2~Cable machine~3.5~r~0~Triceps~Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.~Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position. To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head. Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position.~Letting the elbows drift away from the sides.", "Triceps Pushdown~Triceps~pushdown~2~Cable machine~3.5~r~0~Triceps~Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.~Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position. Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move.~Letting the elbows drift away from the sides.", "Triceps Pushdown - Rope Attachment~Triceps~pushdown~2~Cable machine~3.5~r~0~Triceps~Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).~Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position. Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor.~Letting the elbows drift away from the sides.", "Triceps Pushdown - V-Bar Attachment~Triceps~pushdown~2~Cable machine~3.5~r~0~Triceps~Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.~Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position. Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor.~Letting the elbows drift away from the sides.", "Tuck Crunch~Abs & core~crunch~0~None~3.5~r~0~Abdominals~To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.~Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs. Move your arms from the floor and cross them so they are resting on your chest. This is the starting position. While keeping your lower back pressed against the floor, slowly lift your torso.~Pulling on the neck with the hands.", "Two-Arm Dumbbell Preacher Curl~Biceps~curl~1~Dumbbells~3.5~r~0~Biceps~Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.~As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height. Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.~Swinging the body or moving the elbows forward.", "Two-Arm Kettlebell Clean~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Calves, Glutes, Hamstrings~Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.~Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so. Lower the kettlebells back to the starting position and repeat.~Arching the lower back to push the weight up.", "Two-Arm Kettlebell Jerk~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Calves, Quadriceps, Triceps~Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.~Move slowly and with control through the full range.~Arching the lower back to push the weight up.", "Two-Arm Kettlebell Military Press~Shoulders~ohpress~1~A kettlebell~5.0~r~1~Shoulders, Triceps~Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.~Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability.~Arching the lower back to push the weight up.", "Two-Arm Kettlebell Row~Back~row~1~A kettlebell~5.0~r~1~Middle back, Biceps, Lats~Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.~Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat.~Rounding the back or jerking the weight with the arms only.", "Underhand Cable Pulldowns~Back~latpull~2~Cable machine~5.0~r~0~Lats, Biceps, Middle back, Shoulders~Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.~Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position. As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back.~Leaning far back or pulling behind the neck.", "Upper Back-Leg Grab~Mobility~stretch~0~None~2.3~h~0~Hamstrings, Lower back, Middle back~While seated, bend forward to hug your thighs from underneath with both arms.~Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them.~Bouncing into the stretch or pushing into pain.", "Upper Back Stretch~Mobility~stretch~0~None~2.3~h~0~Middle back, Middle back~Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward.~Move slowly and with control through the full range.~Bouncing into the stretch or pushing into pain.", "Upright Barbell Row~Shoulders~ohpress~2~Barbell and plates~5.0~r~0~Shoulders, Traps~Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.~Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement. Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.~Arching the lower back to push the weight up.", "Upright Cable Row~Back~cablerow~2~Cable machine~5.0~r~1~Traps, Shoulders~Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.~Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement. Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.~Rocking the whole body back and forth.", "Upright Row - With Bands~Back~row~1~A resistance band~5.0~r~0~Traps, Shoulders~To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.~Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement. Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.~Rounding the back or jerking the weight with the arms only.", "Upward Stretch~Mobility~stretch~0~None~2.3~h~0~Shoulders, Chest, Lats~Extend both hands straight above your head, palms touching.~Slowly push your hands up and back, keeping your back straight.~Bouncing into the stretch or pushing into pain.", "V-Bar Pulldown~Back~latpull~2~Cable machine~5.0~r~1~Lats, Biceps, Middle back, Shoulders~Sit down on a pull-down machine with a V-Bar attached to the top pulley.~Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position. Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.~Leaning far back or pulling behind the neck.", "V-Bar Pullup~Back~pullup~2~Pull-up bar and V-handle~5.0~r~1~Lats, Biceps, Middle back, Shoulders~Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.~Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position. Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.~Kipping or not lowering all the way.", "Vertical Swing~Hamstrings~rdl~1~Dumbbells~8.0~r~0~Hamstrings, Glutes, Quadriceps, Shoulders~Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.~Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly. Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head. As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition.~Rounding the lower back instead of hinging at the hips.", "Walking, Treadmill~Cardio~walk~2~Gym machine~7.0~t~0~Quadriceps, Calves, Glutes, Hamstrings~To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.~Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn't burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast.~Hunching forward instead of walking tall.", "Weighted Ball Hyperextension~Back~superman~1~An exercise ball~5.0~r~1~Lower back, Glutes, Hamstrings, Middle back~To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position.~Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement. Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling.~Over-arching or straining the neck.", "Weighted Ball Side Bend~Abs & core~crunch~1~An exercise ball~3.5~r~1~Abdominals~To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.~Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head. Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position. Raise the side of your torso up by laterally flexing at the waist while exhaling.~Pulling on the neck with the hands.", "Weighted Bench Dip~Triceps~dips~2~Gym equipment (see steps)~5.0~r~1~Triceps, Chest, Shoulders~For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.~The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.~Dropping too deep and letting the shoulders roll forward.", "Weighted Crunches~Abs & core~crunch~1~A medicine ball~3.5~r~0~Abdominals~Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.~Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position. Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor. At the top of the movement, flex your abdominals and hold for a brief pause. Then inhale and slowly lower yourself back down to the starting position.~Pulling on the neck with the hands.", "Weighted Jump Squat~Quads~squat~2~Barbell and plates~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise.~The weight should be light enough that it doesn't slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position. Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles. Maintain good posture throughout the jump. As you return to the ground, absorb the impact through your legs.~Letting the knees cave inward or the heels lift.", "Weighted Pull Ups~Back~row~2~Gym equipment (see steps)~5.0~r~1~Lats, Biceps, Middle back~Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.~You'll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position. Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position. After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched.~Rounding the back or jerking the weight with the arms only.", "Weighted Sissy Squat~Quads~squat~2~Barbell and plates~5.0~r~2~Quadriceps, Calves, Glutes, Hamstrings~Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.~As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second. After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.~Letting the knees cave inward or the heels lift.", "Weighted Sit-Ups - With Bands~Abs & core~crunch~2~Gym equipment (see steps)~3.5~r~1~Abdominals~Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.~Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position. Move your torso upward until your upper body is perpendicular to the floor while exhaling.~Pulling on the neck with the hands.", "Weighted Squat~Quads~squat~2~Gym equipment (see steps)~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out.~Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position. Begin by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.~Letting the knees cave inward or the heels lift.", "Wide-Grip Barbell Bench Press~Chest~bench~2~Barbell and plates~5.0~r~1~Chest, Shoulders, Triceps~Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.~As you breathe in, come down slowly until you feel the bar on your middle chest. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.~Bouncing the weight or lifting the hips off the bench.", "Wide-Grip Decline Barbell Bench Press~Chest~bench~2~Barbell and plates~5.0~r~1~Chest, Shoulders, Triceps~Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.~As you breathe in, come down slowly until you feel the bar on your lower chest. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.~Bouncing the weight or lifting the hips off the bench.", "Wide-Grip Decline Barbell Pullover~Chest~bench~2~Barbell and plates~5.0~r~1~Chest, Shoulders, Triceps~Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms.~When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting position. Begin by moving the barbell back down in a semicircular motion as if you were going to place it on the floor, but instead, stop when the arms are parallel to the floor. Tip: Keep the arms fully extended at all times. The movement should only happen at the shoulder joint. Inhale as you perform this portion of the movement.~Bouncing the weight or lifting the hips off the bench.", "Wide-Grip Pulldown Behind The Neck~Back~latpull~2~Cable machine~5.0~r~1~Lats, Biceps, Middle back, Shoulders~Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.~Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso and head forward.~Leaning far back or pulling behind the neck.", "Wide-Grip Rear Pull-Up~Back~pullup~2~Pull-up bar~5.0~r~1~Lats, Biceps, Middle back, Shoulders~Grab the pull-up bar with the palms facing forward using a wide grip.~As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position. Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement.~Kipping or not lowering all the way.", "Wide-Grip Standing Barbell Curl~Biceps~curl~2~Barbell and plates~3.5~r~0~Biceps~Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position.~While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard. Slowly begin to bring the bar back to starting position as your breathe in.~Swinging the body or moving the elbows forward.", "Wide Stance Barbell Squat~Quads~squat~2~Barbell and plates~5.0~r~1~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.~Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance, and also maintain a straight back. This will be your starting position.~Letting the knees cave inward or the heels lift.", "Wide Stance Stiff Legs~Full body~rdl~2~Barbell and plates~6.0~r~1~Hamstrings, Adductors, Glutes, Lower back~Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position.~Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, the weight need not touch the floor.~Rounding the lower back instead of hinging at the hips.", "Wind Sprints~Abs & core~crunch~0~None~5.0~r~0~Abdominals~Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.~Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3 Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible. Continue alternating between legs until the set is complete.~Pulling on the neck with the hands.", "Windmills~Mobility~stretch~0~None~2.3~h~1~Abductors, Glutes, Hamstrings, Lower back~Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.~Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand. Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions.~Bouncing into the stretch or pushing into pain.", "Wrist Circles~Mobility~stretch~0~None~2.3~h~0~Forearms~Start by standing straight with your feet being shoulder width apart from each other. Elevate your arms to the side of you until they are fully extended and parallel to the floor at a height that is evenly aligned with your shoulders. Tip: Your torso and arms should form the letter \"T: Your palms should be facing down. This is the starting position.~Keeping your entire body stationary except for the wrists, begin to rotate both wrists forward in a circular motion. Tip: Pretend that you are trying to draw circles by using your hands as the brush. Breathe normally as you perform this exercise.~Bouncing into the stretch or pushing into pain.", "Wrist Roller~Forearms~curl~2~Gym equipment (see steps)~3.5~r~0~Forearms, Shoulders~To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.~Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position. Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.~Swinging the body or moving the elbows forward.", "Wrist Rotations with Straight Bar~Forearms~curl~2~Barbell and plates~3.5~r~0~Forearms~Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.~Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure. Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure.~Swinging the body or moving the elbows forward.", "Zercher Squats~Quads~squat~2~Barbell and plates~5.0~r~2~Quadriceps, Calves, Glutes, Hamstrings~This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.~Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.~Letting the knees cave inward or the heels lift.", "Zottman Preacher Curl~Biceps~curl~1~Dumbbells~3.5~r~1~Biceps, Forearms~Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.~As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched. Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up. As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.~Swinging the body or moving the elbows forward."];
  var XSTART = LIBROWS.length; Array.prototype.push.apply(LIBROWS,XROWS);
  var NOPLAN = /shrug|snow angel|Prone|Scapular|Wall slide|Arm circles|Plank jack|Bear crawl|Pogo|handstand|ottle|Towel|Table triceps|Back extension|Rack pull|Cossack|Assisted pistol/;
  (function(){
    var names = {}, ids = Object.keys(EXS);
    ids.forEach(function(k){ names[EXS[k].n.toLowerCase()] = 1; });
    LIBROWS.forEach(function(row){
      var a = row.split('~'); if(a.length!==12) throw new Error('Bad library row: '+row.slice(0,40)+' ('+a.length+')');
      var n = a[0], mu = a[1], fig = a[2], eq = parseInt(a[3],10), need = a[4], met = parseFloat(a[5]), kd = a[6], lv = parseInt(a[7],10), muscles = a[8];
      if(!PL[fig]) throw new Error('No base movement: '+fig+' for '+n);
      if(MUS.indexOf(mu)<0) throw new Error('Bad muscle: '+mu);
      if(names[n.toLowerCase()]) n = n+' (variation)';
      names[n.toLowerCase()] = 1;
      var id = n.toLowerCase().replace(/[^a-z0-9]/g,''); while(EXS[id]) id += 'x';
      var m = /^([rht])(\d?)(s?)$/.exec(kd); if(!m) throw new Error('Bad kind '+kd+' for '+n);
      var c;
      if(m[1]==='t') c = {k:'time',met:met};
      else if(m[1]==='h') c = {k:'hold',met:met,rest:30};
      else { c = {k:'reps',met:met,sr:m[2]?parseInt(m[2],10):3,rest:eq?60:40}; if(m[3]) c.side = 1; }
      var closer = c.k==='reps' ? 'Repeat for every rep, breathing out on the effort and in on the return. Rest between sets.' : c.k==='hold' ? 'Hold with steady breathing for the time shown, then rest before the next set.' : 'Keep a steady pace for the time shown. Ease off if you cannot talk.';
      EXS[id] = {n:n,g:MUGRP[mu],fig:fig,cap:EXS[fig].cap,m:muscles,st:[a[9],a[10],closer],mi:a[11],al:[],eq:eq,need:need,mu:mu,lv:lv,base:fig,v:1,
        pat: mu==='Quads' ? ((fig==='lunge'||fig==='stepup') ? 'lg' : 'sq') : (NOPLAN.test(n) ? 'x' : PATMU[mu])};
      if(LIBROWS.indexOf(row)>=XSTART){ EXS[id].pat = 'x'; EXS[id].xdb = 1; }
      CAL[id] = c;
      META[id] = [eq,EXS[id].pat,need];
    });
    /* alternatives for the new rows: other exercises for the same muscle */
    var all = Object.keys(EXS);
    all.forEach(function(id){
      var e = EXS[id]; if(!e.v) return;
      var same = all.filter(function(k){return k!==id && EXS[k].mu===e.mu && EXS[k].n!==e.n});
      same.sort(function(x,y){return EXS[x].eq-EXS[y].eq || (EXS[x].n<EXS[y].n?-1:1)});
      if(!same.length) return;
      var h = 0; for(var i=0;i<id.length;i++) h = (h*31+id.charCodeAt(i))>>>0;
      var step = Math.max(1,Math.floor(same.length/3)), out = [];
      for(var j=0;j<same.length && out.length<3;j++){
        var k2 = same[(h+j*step)%same.length];
        if(out.indexOf(k2)<0) out.push(k2);
      }
      e.al = out.map(function(k){
        var o = EXS[k];
        return [o.n,'Works the same area ('+o.mu.toLowerCase()+')'+(o.eq<e.eq ? ' and is easier to set up: '+o.need.toLowerCase()+'.' : '.')];
      });
    });
  })();
  var EXCOUNT = Object.keys(EXS).length;

  var userKg = null, figG = null;
  function fg(){return figG || gOf()}
  function kcalTxt(x){return x<10 ? (Math.round(x*10)/10).toFixed(1) : String(Math.round(x))}
  function mk(id,a){ // plan item from [id, ...]
    var k=CAL[id].k;
    if(k==='time') return {id:id,m:a[1],note:a[2]};
    if(k==='hold') return {id:id,s:a[1],t:a[2],note:a[3]};
    return {id:id,s:a[1],r:a[2],note:a[3]};
  }
  function burn(id,it,kg){
    var c=CAL[id], r={};
    if(c.k==='time'){ r.min=it.m; r.kcal=c.met*kg*it.m/60; return r; }
    if(c.k==='reps'){ var reps=it.s*it.r*(c.side?2:1); var sec=reps*c.sr+(it.s-1)*c.rest; r.min=sec/60; r.kcal=c.met*kg*sec/3600; r.reps=reps; r.perRep=r.kcal/reps; r.perSet=r.kcal/it.s; return r; }
    var sec2=it.s*it.t+(it.s-1)*c.rest; r.min=sec2/60; r.kcal=c.met*kg*sec2/3600; r.perSet=r.kcal/it.s; r.perSec=r.kcal/sec2; return r;
  }
  function rxTxt(id,it){
    var c=CAL[id];
    if(c.k==='time') return it.m+' minutes';
    if(c.k==='hold') return it.s+' sets × '+it.t+' sec';
    return it.s+' sets × '+it.r+' reps'+(c.side?' each leg':'');
  }
  function calCells(id,it,kg,lib){
    var c=CAL[id], cells=[];
    if(c.k==='time'){
      var pm=c.met*kg/60;
      if(lib) cells=[['Per minute',kcalTxt(pm)],['10 minutes',kcalTxt(pm*10)],['30 minutes',kcalTxt(pm*30)]];
      else cells=[['Per minute',kcalTxt(pm)],['10 minutes',kcalTxt(pm*10)],['This workout ('+it.m+' min)',kcalTxt(pm*it.m)]];
    } else if(c.k==='reps'){
      var b=burn(id,it,kg);
      cells=[['Per rep',kcalTxt(b.perRep)],['Per set ('+it.r+' reps'+(c.side?' each leg':'')+')',kcalTxt(b.perSet)],['This workout ('+it.s+' sets)',kcalTxt(b.kcal)]];
    } else {
      var h=burn(id,it,kg);
      cells=[['Per second',(Math.round(h.perSec*100)/100).toFixed(2)],['Per set ('+it.t+' sec)',kcalTxt(h.perSet)],['This workout ('+it.s+' sets)',kcalTxt(h.kcal)]];
    }
    return cells;
  }
  function calBlock(id,it,lib){
    var kg=userKg||70;
    var cells=calCells(id,it,kg,lib);
    var c=CAL[id];
    var h='<div><h5>Calories burned</h5><div class="cal">'+cells.map(function(x){return '<div><b>'+x[1]+'</b><small>kcal</small><span>'+esc(x[0])+'</span></div>'}).join('')+'</div>';
    var tm='';
    if(c.k!=='time'){var b=burn(id,it,kg); tm=' The workout takes about '+Math.max(1,Math.round(b.min))+' minutes including rests.'}
    h+='<p class="foot">'+(userKg?'Worked out for your weight of '+kg+' kg.':'Worked out for a 70 kg person. Make your plan to see numbers for your own weight.')+tm+' Estimate based on MET '+c.met+'.</p></div>';
    return h;
  }
  function exBody(id,it,lib){
    var e=EXS[id], fl=exPics(id), si=stillIdx(id);
    var h = '<div class="exbody"><div class="big2">'+fl.map(function(s,i){return '<figure>'+s+'<figcaption>'+esc(ephOf(id) ? (i?'End position':'Start position') : (e.cap[i]||''))+'</figcaption></figure>'}).join('')+'</div>';
    if(e.v) h += '<p class="hint basen">The pictures show the base movement: '+esc(EXS[e.base].n)+'. Follow the written steps below for what is different in this variation.</p>';
    h += calBlock(id,it,lib);
    h += '<p class="need"><b>You need:</b> '+esc(e.need)+'</p>';
    h += '<div><h5>How to do it</h5><ol>'+e.st.map(function(x){return '<li>'+esc(x)+'</li>'}).join('')+'</ol></div>';
    h += '<p class="mist"><b>Common mistake:</b> '+esc(e.mi)+'</p>';
    h += '<div><h5>Alternatives</h5><div class="alts">'+e.al.map(function(a){return '<div class="alt"><b>'+esc(a[0])+'</b><span>'+esc(a[1])+'</span></div>'}).join('')+'</div></div></div>';
    return h;
  }
  function libItem(id){
    var c=CAL[id];
    if(c.k==='time') return {id:id,m:10};
    if(c.k==='hold') return {id:id,s:3,t:30};
    return {id:id,s:3,r:10};
  }
  function exItem(id,it,lib){
    var e = EXS[id], b = burn(id,it,userKg||70);
    var pics = exPics(id).join('');
    var line = lib ? (e.m) : (rxTxt(id,it)+(it.note?' · '+it.note:''));
    var chip = lib ? '' : '<span class="kc">~'+Math.round(b.kcal)+' kcal</span>';
    return '<details class="ex"><summary><span class="pics">'+pics+'</span><span class="meta"><b>'+esc(e.n)+'</b><span>'+esc(line)+'</span>'+chip+'</span><span class="chev" aria-hidden="true"></span></summary>'+exBody(id,it,lib)+'</details>';
  }

  /* ---------- Exercise library: search, muscle and equipment filters, lazy rows ---------- */
  var LB = {q:'',mu:'all',eq:'all',lv:'all',n:30};
  var EQN = {'0':'No equipment','1':'Dumbbells and small gear','2':'Gym machines'};
  function libIds(st){
    var q = (st.q||'').trim().toLowerCase();
    return Object.keys(EXS).filter(function(id){
      var e = EXS[id];
      if(st.mu && st.mu!=='all'){ if(Array.isArray(st.mu)){ if(st.mu.indexOf(e.mu)<0) return false; } else if(e.mu!==st.mu) return false; }
      if(st.eq && st.eq!=='all' && e.eq>parseInt(st.eq,10)) return false;
      if(st.lv && st.lv!=='all' && e.lv>parseInt(st.lv,10)) return false;
      if(q && (e.n+' '+e.mu+' '+e.m+' '+e.need).toLowerCase().indexOf(q)<0) return false;
      return true;
    }).sort(function(a,b){
      var x = MUS.indexOf(EXS[a].mu), y = MUS.indexOf(EXS[b].mu);
      return x-y || (EXS[a].v||0)-(EXS[b].v||0) || (EXS[a].n<EXS[b].n?-1:1);
    });
  }
  function libRow(id,tag){
    var e = EXS[id], thumb = exPics(id)[0];
    var eqi = e.eq===0 ? 'No equipment' : e.eq===1 ? 'Dumbbells/gear' : 'Gym';
    var h = '<div class="lrow'+(tag&&tag.cls?' '+tag.cls:'')+'"><details class="ex lz" data-id="'+id+'"><summary><span class="pics one">'+thumb+'</span><span class="meta"><b>'+esc(e.n)+'</b><span>'+esc(e.mu)+' · '+esc(LVT[e.lv||0])+' · '+eqi+'</span>'+(tag&&tag.label?'<span class="inplan">'+esc(tag.label)+'</span>':'')+'</span><span class="chev" aria-hidden="true"></span></summary><div class="lzb"></div></details>';
    if(tag && tag.btn) h += tag.btn;
    return h+'</div>';
  }
  function chipsHtml(name,list,cur){
    return '<div class="cbs scrollx">'+list.map(function(x){return '<button type="button" class="cb'+(String(cur)===x[0]?' on':'')+'" data-lib="'+name+'" data-v="'+x[0]+'" aria-pressed="'+(String(cur)===x[0])+'">'+esc(x[1])+'</button>'}).join('')+'</div>';
  }
  function muChips(cur,total,counts){
    var l = [['all','All ('+total+')']]; MUS.forEach(function(m){ l.push([m,m+' ('+counts[m]+')']); });
    return chipsHtml('mu',l,cur);
  }
  function muCounts(){ var c = {}; MUS.forEach(function(m){c[m]=0}); Object.keys(EXS).forEach(function(k){c[EXS[k].mu]++}); return c; }
  function renderLibrary(){
    var cur = fg(), cnt = muCounts();
    var h = '<div class="fcard"><div class="frow"><label class="fl" for="lib-q">Search</label><input type="search" id="lib-q" class="sinp" placeholder="Try squat, biceps, dumbbell, hips…" autocomplete="off" value="'+esc(LB.q)+'"></div>'+
      '<div class="frow"><span class="fl">Muscle</span>'+muChips(LB.mu,EXCOUNT,cnt)+'</div>'+
      '<div class="frow"><span class="fl">Equipment</span>'+chipsHtml('eq',[['all','All'],['0','No equipment'],['1','Dumbbells'],['2','Gym']],LB.eq)+'</div>'+
      '<div class="frow"><span class="fl">Level</span>'+chipsHtml('lv',[['all','All'],['0','Beginner'],['1','Up to intermediate'],['2','Up to advanced']],LB.lv)+'</div>'+
      '<div class="frow"><span class="fl">Show the demo with</span><div class="cbs"><button type="button" class="cb'+(cur==='m'?' on':'')+'" data-lib="g" data-v="m" aria-pressed="'+(cur==='m')+'">Male athlete</button><button type="button" class="cb'+(cur==='f'?' on':'')+'" data-lib="g" data-v="f" aria-pressed="'+(cur==='f')+'">Female athlete</button></div></div></div>'+
      '<p class="hint" id="libcount"></p><div id="lib-res"></div>';
    $('lib').innerHTML = h;
    var lead = $('liblead'); if(lead) lead.textContent = EXCOUNT+' exercises for home, dumbbells and the gym, sorted by the muscle they train. Open any one for the pictures, how to do it, calories burned, the most common mistake and alternatives.';
    paintLib();
  }
  function paintLib(){
    var kp = !licensed(), ids = libIds(LB), shown = ids.slice(0,kp?6:LB.n), h = '', last = '';
    shown.forEach(function(id){
      var mu = EXS[id].mu;
      if(mu!==last){ h += '<h3 class="lgh">'+esc(mu)+'</h3>'; last = mu; }
      h += libRow(id);
    });
    if(!ids.length) h = '<p class="hint">No exercise matches. Try a shorter word or clear the filters.</p>';
    if(kp && ids.length>shown.length) h += kPrevCard('You are seeing '+shown.length+' of '+fmt(EXCOUNT)+' exercises.','Get a plan to open every exercise, with pictures, form tips, calories burned and alternatives.');
    else if(ids.length>shown.length) h += '<button type="button" class="btn ghost more" data-lib="more">Show '+Math.min(30,ids.length-shown.length)+' more ('+(ids.length-shown.length)+' left)</button>';
    $('lib-res').innerHTML = h;
    $('libcount').textContent = ids.length+' of '+EXCOUNT+' exercises'+(ids.length>shown.length?' · showing '+shown.length:'');
  }
  $('lib').addEventListener('input',function(ev){
    if(ev.target.id==='lib-q'){ LB.q = ev.target.value; LB.n = 30; paintLib(); }
  });
  $('lib').addEventListener('click',function(ev){
    var b = ev.target.closest('button[data-lib]'); if(!b) return;
    var a = b.getAttribute('data-lib'), v = b.getAttribute('data-v');
    if(a==='more'){ LB.n += 30; paintLib(); return; }
    if(a==='g') figG = v; else if(a==='mu') LB.mu = v; else if(a==='eq') LB.eq = v; else if(a==='lv') LB.lv = v;
    LB.n = 30; renderLibrary();
  });
  function openLibrary(mu){ if(mu) LB.mu = mu; LB.n = 30; renderLibrary(); show('s-library'); }
  function netKcal(id,it,kg){var b=burn(id,it,kg), m=CAL[id].met; return b.kcal*(m-1)/m}


